function escapeHtml(text) {
    if (!text) return '';
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
}

function escapeAttribute(text) {
    return escapeHtml(text).replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

function syncNumericRangeControl(input, output) {
    if (!input) return 0;
    const min = Number(input.min || 0);
    const max = Number(input.max || 100);
    const rawValue = Number(input.value);
    const value = Math.max(min, Math.min(max, Number.isFinite(rawValue) ? rawValue : min));
    const progress = max > min ? ((value - min) / (max - min)) * 100 : 0;
    input.value = String(value);
    input.style.setProperty('--range-progress', `${progress}%`);
    if (output) {
        output.value = String(value);
        output.textContent = String(value);
    }
    return value;
}

function getNexusDiscountGuard() {
    return globalThis.NexusDiscountGuard || null;
}

function evaluateNexusDiscountTranslation(sourceText, translatedText, targetLang = '') {
    const guard = getNexusDiscountGuard();
    return guard
        ? guard.evaluateDiscountTranslation(sourceText, translatedText, targetLang)
        : {
            status: 'not_applicable',
            issues: [],
            expressions: [],
            candidates: [],
            sourceRanges: [],
            targetRanges: []
        };
}

function getNexusDiscountQaIssues(sourceText, translatedText, targetLang = '') {
    const result = evaluateNexusDiscountTranslation(sourceText, translatedText, targetLang);
    /* A placeholder/range such as %s 折 cannot be safely converted without
     * runtime data.  The local test panel reports it for review, but it must
     * not create a false failed task merely because static QA cannot decide. */
    if (result.sourceAmbiguous) return [];
    return result
        .issues
        .map(issue => typeof issue === 'string' ? issue : issue.message)
        .filter(Boolean);
}

function getNexusDiscountQaStatus(sourceText, translatedText, targetLang = '') {
    const issues = getNexusDiscountQaIssues(sourceText, translatedText, targetLang);
    return issues.length ? `需确认：${issues.join('；')}` : '';
}

function maskNexusDiscountRanges(text, ranges = []) {
    const guard = getNexusDiscountGuard();
    return guard ? guard.maskRanges(text, ranges) : String(text || '');
}

function buildNexusDiscountPromptInstruction(sourceText, targetLang = '') {
    const guard = getNexusDiscountGuard();
    return guard ? guard.buildPromptInstruction(sourceText, targetLang) : '';
}

function getNexusStandaloneDiscountTranslation(sourceText, targetLang = '') {
    const guard = getNexusDiscountGuard();
    return guard ? guard.getStandaloneDiscountTranslation(sourceText, targetLang) : null;
}

function setStatus(type, text, subtext = '', actionCallback = null, actionLabel = '查看') {
    const statusBar = document.getElementById('statusBar');
    const statusIcon = document.getElementById('statusIcon');
    const statusText = document.getElementById('statusText');
    const statusSubtext = document.getElementById('statusSubtext');
    const statusAction = document.getElementById('statusAction');

    statusBar.className = `status-bar ${type}`;
    statusText.textContent = text;
    statusSubtext.textContent = subtext;

    if (actionCallback) {
        statusAction.style.display = 'block';
        statusAction.textContent = actionLabel;
        statusAction.onclick = actionCallback;
    } else {
        statusAction.style.display = 'none';
        statusAction.textContent = '查看';
    }

    statusBar.style.display = 'flex';

    if (type === 'processing') {
        startInspectorTaskTimer(text || '运行中');
    } else if (type === 'success' || type === 'error') {
        finishInspectorTaskTimer(type, text || (type === 'success' ? '任务完成' : '任务异常'));
    }

    if (type === 'success') {
        recordRecentTask({
            title: text || '任务完成',
            detail: subtext || '',
            status: 'success'
        });
        if (Notification.permission === 'granted') {
            new Notification('任务完成', {
                body: subtext || text
            });
        }
    } else if (type === 'error') {
        recordRecentTask({
            title: text || '任务异常',
            detail: subtext || '',
            status: 'error'
        });
    }
}

function hideStatus() {
    const statusBar = document.getElementById('statusBar');
    statusBar.style.display = 'none';
}

const UX_RECENT_TASKS_KEY = 'nexus_ux_recent_tasks_v1';

let inspectorTaskStartedAt = 0;
let inspectorTaskFinishedAt = 0;
let inspectorTaskTimerId = null;
let inspectorTaskStatus = 'idle';

function getActiveToolKey() {
    return document.querySelector('.nav-item.active')?.dataset.tool || 'split';
}

function setInspectorText(id, value) {
    const el = document.getElementById(id);
    if (el) el.textContent = value;
}

function formatInspectorElapsed(ms) {
    const totalSeconds = Math.max(0, Math.floor(Number(ms || 0) / 1000));
    const hours = Math.floor(totalSeconds / 3600);
    const minutes = Math.floor((totalSeconds % 3600) / 60);
    const seconds = totalSeconds % 60;
    if (hours > 0) {
        return `${hours}:${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
    }
    return `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
}

function renderInspectorTaskTimer() {
    if (!inspectorTaskStartedAt) return;
    const endAt = inspectorTaskFinishedAt || Date.now();
    setInspectorText('inspectorEstimateTime', formatInspectorElapsed(endAt - inspectorTaskStartedAt));
}

function startInspectorTaskTimer(phase = '运行中') {
    if (inspectorTaskStatus !== 'running' || !inspectorTaskStartedAt) {
        inspectorTaskStartedAt = Date.now();
        inspectorTaskFinishedAt = 0;
        inspectorTaskStatus = 'running';
    }
    setInspectorText('inspectorTaskBadge', '运行中');
    setInspectorText('inspectorTaskPhase', phase || '运行中');
    setInspectorText('inspectorEstimateBadge', '计时中');
    renderInspectorTaskTimer();

    if (!inspectorTaskTimerId) {
        inspectorTaskTimerId = setInterval(renderInspectorTaskTimer, 1000);
    }
}

function finishInspectorTaskTimer(type = 'success', phase = '') {
    if (!inspectorTaskStartedAt) return;
    const isError = type === 'error';
    const isWarning = type === 'warning';
    const isRunning = inspectorTaskStatus === 'running';
    const isTerminalWarningOverride = isWarning && inspectorTaskStatus === 'success';
    if (!isRunning && !isTerminalWarningOverride) return;
    if (isRunning) inspectorTaskFinishedAt = Date.now();
    inspectorTaskStatus = isError ? 'error' : (isWarning ? 'warning' : 'success');
    if (inspectorTaskTimerId) {
        clearInterval(inspectorTaskTimerId);
        inspectorTaskTimerId = null;
    }
    renderInspectorTaskTimer();
    setInspectorText('inspectorTaskBadge', isError ? '异常' : (isWarning ? '需处理' : '完成'));
    setInspectorText('inspectorTaskPhase', phase || (isError ? '处理异常' : (isWarning ? '处理完成，仍需修复' : '处理完成')));
    setInspectorText('inspectorEstimateBadge', isError ? '已停止' : '已计时');
}

function resetInspectorTaskTimer() {
    if (inspectorTaskTimerId) {
        clearInterval(inspectorTaskTimerId);
        inspectorTaskTimerId = null;
    }
    inspectorTaskStartedAt = 0;
    inspectorTaskFinishedAt = 0;
    inspectorTaskStatus = 'idle';
    setInspectorText('inspectorTaskBadge', '就绪');
    setInspectorText('inspectorTaskPhase', '等待开始');
    setInspectorText('inspectorEstimateBadge', '待开始');
    setInspectorText('inspectorEstimateTime', '未开始');
    setInspectorText('inspectorTaskBatches', '按任务生成');
    setInspectorText('inspectorTaskFailures', '运行中显示');
}

function loadRecentTasks() {
    try {
        return JSON.parse(localStorage.getItem(UX_RECENT_TASKS_KEY) || '[]');
    } catch {
        return [];
    }
}

function saveRecentTasks(tasks) {
    localStorage.setItem(UX_RECENT_TASKS_KEY, JSON.stringify((tasks || []).slice(0, 8)));
}

function recordRecentTask(task) {
    const nextTask = {
        id: `${Date.now()}-${Math.random().toString(16).slice(2)}`,
        tool: getActiveToolKey(),
        title: task?.title || '未命名任务',
        detail: task?.detail || '',
        status: task?.status || 'ready',
        createdAt: Date.now()
    };
    saveRecentTasks([nextTask, ...loadRecentTasks()]);
    renderRecentTasks();
}

function formatRelativeTime(timestamp) {
    const diff = Math.max(0, Date.now() - Number(timestamp || Date.now()));
    const minute = 60 * 1000;
    const hour = 60 * minute;
    if (diff < minute) return '刚刚';
    if (diff < hour) return `${Math.floor(diff / minute)} 分钟前`;
    if (diff < 24 * hour) return `${Math.floor(diff / hour)} 小时前`;
    return `${Math.floor(diff / (24 * hour))} 天前`;
}

function normalizeRecentTaskDisplayText(value = '') {
    return String(value || '')
        .replace(/失败翻译补跑完成！?/g, '硬问题重译完成')
        .replace(/失败\/需确认/g, '发现问题')
        .replace(/真实失败\/缺失/g, '翻译失败/未返回')
        .replace(/QA软风险/g, '软性需确认')
        .replace(/默认补跑/g, '可自动处理')
        .replace(/补跑失败翻译/g, '重译硬问题')
        .replace(/有可补跑项/g, '有可自动处理项');
}

function renderRecentTasks() {
    const list = document.getElementById('recentTaskList');
    if (!list) return;
    const tasks = loadRecentTasks();
    if (!tasks.length) {
        list.innerHTML = '<div class="recent-task-empty">选择文件或完成任务后会显示在这里</div>';
        return;
    }
    list.innerHTML = tasks.map(task => `
        <div class="recent-task-item ${escapeAttribute(task.status || 'ready')}">
            <span class="recent-task-icon">${task.status === 'success' ? '✓' : task.status === 'error' ? '!' : '•'}</span>
            <div>
                <strong>${escapeHtml(normalizeRecentTaskDisplayText(task.title))}</strong>
                <small>${escapeHtml(normalizeRecentTaskDisplayText(task.detail))}${task.detail ? ' · ' : ''}${formatRelativeTime(task.createdAt)}</small>
            </div>
        </div>
    `).join('');
}

function renderSelectedFileList(input, files = []) {
    const uploadArea = input?.closest?.('.upload-area-large, .upload-area-small') ||
        input?.parentElement?.querySelector?.('.upload-area-large, .upload-area-small');
    if (!uploadArea) return;
    let list = uploadArea.querySelector('.selected-file-list');
    if (!list) {
        list = document.createElement('div');
        list.className = 'selected-file-list';
        uploadArea.appendChild(list);
    }
    const selectedFiles = Array.from(files || []);
    if (!selectedFiles.length) {
        list.innerHTML = '';
        list.style.display = 'none';
        return;
    }
    list.style.display = 'grid';
    list.innerHTML = selectedFiles.slice(0, 4).map(file => `
        <div class="selected-file-pill">
            <span>${escapeHtml(file.name)}</span>
            <small>${formatFileSize(file.size || 0)}</small>
        </div>
    `).join('') + (selectedFiles.length > 4 ? `<div class="selected-file-more">还有 ${selectedFiles.length - 4} 个文件</div>` : '');
}

function bindUxFileTelemetry() {
    document.querySelectorAll('input[type="file"]').forEach(input => {
        if (input.dataset.telemetrySkip === 'true') return;
        input.addEventListener('change', () => {
            const files = Array.from(input.files || []);
            renderSelectedFileList(input, files);
            if (!files.length) return;
            const totalSize = files.reduce((sum, file) => sum + (file.size || 0), 0);
            const inputState = document.getElementById('inspectorInputState');
            const outputState = document.getElementById('inspectorOutputState');
            if (inputState) inputState.textContent = files.length > 1 ? `${files.length} 个文件` : files[0].name;
            if (outputState) outputState.textContent = '等待开始';
            updateInspectorEstimate(files);
            recordRecentTask({
                title: files.length > 1 ? `${files.length} 个文件已选择` : files[0].name,
                detail: `${formatFileSize(totalSize)} · 等待处理`,
                status: 'ready'
            });
        });
    });
}

function getToolEstimateText(tool, files, totalSize) {
    if (!files.length) return '等待文件';
    if (tool === 'split' || tool === 'convert') return totalSize > 5 * 1024 * 1024 ? '约 10 秒内' : '约数秒';
    if (tool === 'precision-replace') return totalSize > 5 * 1024 * 1024 ? '约 10 到 30 秒' : '约数秒';
    if (tool === 'lite-check') return totalSize > 5 * 1024 * 1024 ? '约 10 到 30 秒' : '约数秒';
    if (tool === 'translate') return '等待开始';
    if (tool === 'l10n-check') return files.length > 1 || totalSize > 1024 * 1024 ? '约 3 到 10 分钟' : '约 1 到 4 分钟';
    if (tool === 'glossary' || tool === 'glossary-organize') return totalSize > 1024 * 1024 ? '约 2 到 6 分钟' : '约 1 到 3 分钟';
    return '上传后估算';
}

function updateInspectorEstimate(files = []) {
    const selectedFiles = Array.from(files || []);
    const totalSize = selectedFiles.reduce((sum, file) => sum + (file.size || 0), 0);
    const filesEl = document.getElementById('inspectorEstimateFiles');
    const sizeEl = document.getElementById('inspectorEstimateSize');
    const timeEl = document.getElementById('inspectorEstimateTime');
    const badgeEl = document.getElementById('inspectorEstimateBadge');
    if (filesEl) filesEl.textContent = String(selectedFiles.length);
    if (sizeEl) sizeEl.textContent = selectedFiles.length ? formatFileSize(totalSize) : '-';
    if (inspectorTaskStatus !== 'running') {
        if (timeEl) timeEl.textContent = selectedFiles.length ? '未开始' : '等待文件';
        if (badgeEl) badgeEl.textContent = selectedFiles.length ? '待开始' : '待选择';
    }
}

const apiRuntimeHealthByProfile = new Map();

function getApiRuntimeHealthKey(profile) {
    if (!profile) return '';
    return String(
        profile.id ||
        profile.profileId ||
        `${profile.provider || 'custom'}:${profile.baseUrl || ''}:${profile.model || ''}`
    );
}

function getApiRuntimeHealth(profile) {
    const key = getApiRuntimeHealthKey(profile);
    return key ? (apiRuntimeHealthByProfile.get(key) || null) : null;
}

function setApiRuntimeHealth(profile, status, message = '') {
    const key = getApiRuntimeHealthKey(profile);
    if (!key) return;
    apiRuntimeHealthByProfile.set(key, {
        status: status || 'configured',
        message: String(message || '').trim(),
        checkedAt: Date.now()
    });
    renderApiSummary();
    document.dispatchEvent(new CustomEvent('nexus:api-runtime-health-updated'));
}

function clearApiRuntimeHealth(profile) {
    const key = getApiRuntimeHealthKey(profile);
    if (key) apiRuntimeHealthByProfile.delete(key);
}

function renderApiSummary() {
    const apiConfig = typeof getApiConfig === 'function' ? getApiConfig() : null;
    const profileName = apiConfig?.name || apiConfig?.profileName || getPlatformName(apiConfig?.provider) || '未配置通道';
    const model = apiConfig?.model || getDefaultModelForProvider?.(apiConfig?.provider) || '';
    const hasKey = Boolean(String(apiConfig?.apiKey || '').trim());
    const concurrency = Number(apiConfig?.concurrency || apiConfig?.profileConcurrency || 1);
    const visual = getPlatformVisual(apiConfig?.provider || 'custom');
    const runtimeHealth = hasKey ? getApiRuntimeHealth(apiConfig) : null;
    const healthStatus = hasKey ? (runtimeHealth?.status || 'configured') : 'missing';
    const healthPresentation = {
        missing: { inspector: '待配置', topbar: 'AI 通道待配置', className: '' },
        configured: { inspector: '待验证', topbar: 'AI 通道待验证', className: '' },
        checking: { inspector: '验证中', topbar: 'AI 通道验证中', className: 'checking' },
        online: { inspector: '可用', topbar: 'AI 通道可用', className: 'online' },
        quota: { inspector: '额度已用尽', topbar: 'AI 额度已用尽', className: 'blocked' },
        error: { inspector: '不可用', topbar: 'AI 通道不可用', className: 'blocked' }
    }[healthStatus] || { inspector: '待验证', topbar: 'AI 通道待验证', className: '' };

    const apiName = document.getElementById('inspectorApiName');
    const apiModel = document.getElementById('inspectorApiModel');
    const apiHealth = document.getElementById('inspectorApiHealth');
    const apiConcurrency = document.getElementById('inspectorApiConcurrency');
    const apiIcon = document.querySelector('.api-summary-icon');
    const topbarApiStatus = document.getElementById('topbarApiStatus');

    if (apiName) apiName.textContent = hasKey ? profileName : '未配置通道';
    if (apiModel) apiModel.textContent = hasKey ? model : '保存 API Key 后可用于翻译、检测和术语处理';
    if (apiHealth) {
        apiHealth.textContent = healthPresentation.inspector;
        apiHealth.title = runtimeHealth?.message || '';
    }
    if (apiConcurrency) apiConcurrency.textContent = hasKey ? String(concurrency) : '-';
    if (apiIcon) {
        apiIcon.className = `api-summary-icon ${hasKey ? visual.tone : 'custom'}`;
        apiIcon.textContent = hasKey ? visual.mark : 'API';
        apiIcon.title = hasKey ? visual.label : '未配置通道';
    }
    if (topbarApiStatus) {
        topbarApiStatus.classList.remove('online', 'checking', 'blocked');
        if (healthPresentation.className) topbarApiStatus.classList.add(healthPresentation.className);
        topbarApiStatus.innerHTML = `<span class="status-dot"></span>${healthPresentation.topbar}`;
        topbarApiStatus.title = runtimeHealth?.message || (hasKey
            ? '已保存通道配置；开始任务或点击“测试”后会验证实际可用性。'
            : '请先保存 API 通道。');
    }
    refreshAllVisualSelects();
}

function getProviderForModelValue(modelValue, fallbackProvider = 'custom') {
    const normalizedModel = String(modelValue || '').trim();
    if (!normalizedModel || normalizedModel === CUSTOM_MODEL_OPTION) {
        return fallbackProvider || 'custom';
    }

    const fallbackModels = PLATFORM_CONFIG[fallbackProvider]?.models || [];
    if (fallbackModels.some(model => model.id === normalizedModel)) {
        return fallbackProvider;
    }

    const directMatch = Object.entries(PLATFORM_CONFIG).find(([, platform]) =>
        (platform.models || []).some(model => model.id === normalizedModel)
    );
    if (directMatch) return directMatch[0];

    const lower = normalizedModel.toLowerCase();
    if (lower.includes('claude') || lower.includes('sonnet') || lower.includes('opus') || lower.includes('haiku')) return 'aigocodeClaude';
    if (lower.includes('gemini')) return 'gemini';
    if (lower.includes('agnes')) return 'agnes';
    if (lower.includes('deepseek')) return 'deepseek';
    if (lower.includes('gpt') || lower.includes('o1') || lower.includes('o3') || lower.includes('o4')) return 'openai';
    if (lower.includes('qwen') || lower.includes('glm') || lower.includes('kimi') || lower.includes('minimax')) return fallbackProvider || 'youdao';
    if (lower.includes('mimo')) return 'xiaomi';
    if (lower.includes('doubao')) return 'doubao';
    return fallbackProvider || 'custom';
}

function getSelectVisualConfig(select) {
    if (!select) return null;
    if (select.id === 'sourceLang' || select.id === 'targetLang') {
        const visual = getLanguageVisual(select.value);
        return { kind: 'language', mark: visual.flag, text: visual.name };
    }
    if (select.id === 'apiProvider') {
        const visual = getPlatformVisual(select.value);
        return { kind: `provider ${visual.tone}`, mark: visual.mark, text: visual.label };
    }
    if (['globalAiModel', 'glossaryModel', 'organizeGlossaryModel'].includes(select.id)) {
        const fallbackProvider = document.getElementById('apiProvider')?.value || getActiveApiProfile?.()?.provider || getApiConfig()?.provider || 'custom';
        const provider = getProviderForModelValue(select.value, fallbackProvider);
        const visual = getPlatformVisual(provider);
        return { kind: `provider ${visual.tone}`, mark: visual.mark, text: getModelTraitTags(select.value)[0] || '模型' };
    }
    return null;
}

function updateVisualSelect(select) {
    if (!select) return;
    const config = getSelectVisualConfig(select);
    if (!config) return;

    const shell = select.closest('.select-shell');
    const prefix = shell?.querySelector('.select-visual-prefix');
    const row = select.closest('.setting-row, .api-config-content .setting-row');
    if (!prefix) return;

    prefix.className = `select-visual-prefix ${config.kind}`;
    prefix.textContent = config.mark;
    prefix.title = config.text;
    if (row) row.dataset.visualText = config.text;
}

function refreshAllVisualSelects() {
    [
        'sourceLang',
        'targetLang',
        'apiProvider',
        'globalAiModel',
        'glossaryModel',
        'organizeGlossaryModel'
    ].forEach(id => updateVisualSelect(document.getElementById(id)));
}

function enhanceVisualSelect(select) {
    if (!select || select.dataset.visualEnhanced === 'true') return;
    const row = select.closest('.setting-row, .api-config-content .setting-row');
    if (!row) return;
    row.classList.add('visual-select-row');
    let shell = select.closest('.select-shell');
    if (!shell) {
        shell = document.createElement('div');
        shell.className = 'select-shell';
        select.parentNode.insertBefore(shell, select);
        shell.appendChild(select);
    }
    let prefix = shell.querySelector('.select-visual-prefix');
    if (!prefix) {
        prefix = document.createElement('span');
        prefix.className = 'select-visual-prefix';
        shell.insertBefore(prefix, select);
    }
    select.classList.add('select-with-visual-prefix');

    select.addEventListener('change', () => {
        updateVisualSelect(select);
        renderApiSummary();
    });
    select.dataset.visualEnhanced = 'true';
    updateVisualSelect(select);
}

function enhanceDeepChoiceSurfaces() {
    [
        'sourceLang',
        'targetLang',
        'apiProvider',
        'globalAiModel',
        'glossaryModel',
        'organizeGlossaryModel'
    ].forEach(id => enhanceVisualSelect(document.getElementById(id)));

    const updateModelSelects = () => {
        ['globalAiModel', 'glossaryModel', 'organizeGlossaryModel'].forEach(id => {
            const select = document.getElementById(id);
            if (!select) return;
            const row = select.closest('.setting-row');
            if (!row) return;
            let hint = row.querySelector('.model-trait-strip');
            if (!hint) {
                hint = document.createElement('div');
                hint.className = 'model-trait-strip';
                row.appendChild(hint);
            }
            hint.innerHTML = getModelTraitHtml(select.value);
            updateVisualSelect(select);
        });
    };

    document.addEventListener('change', (event) => {
        if (event.target?.matches?.('#apiProvider, #globalAiModel, #glossaryModel, #organizeGlossaryModel')) {
            updateModelSelects();
            ['globalAiModel', 'glossaryModel', 'organizeGlossaryModel'].forEach(id => {
                const select = document.getElementById(id);
                updateVisualSelect(select);
            });
        }
    });
    document.addEventListener('nexus:api-profiles-updated', () => {
        updateModelSelects();
        renderApiSummary();
    });
    updateModelSelects();
}

function revealWorkspaceInspector() {
    const panel = document.getElementById('apiConfigPanel');
    const inspector = document.getElementById('workspaceInspector');
    if (panel) {
        panel.style.display = 'none';
        panel.setAttribute('aria-hidden', 'true');
    }
    if (inspector) inspector.style.display = 'grid';
    document.body.classList.remove('api-config-open');
    if (apiConfigReturnFocus && document.contains(apiConfigReturnFocus)) {
        apiConfigReturnFocus.focus({ preventScroll: true });
    }
}

const TRANSLATION_STORAGE_KEY = 'nexus_translation_progress';
const TRANSLATION_PROGRESS_DB_NAME = 'nexus_translation_progress_db';
const TRANSLATION_PROGRESS_DB_VERSION = 2;
const TRANSLATION_PROGRESS_META_STORE = 'meta';
const TRANSLATION_PROGRESS_TASK_STORE = 'tasks';
const TRANSLATION_PROGRESS_ACTIVE_ID = 'active';
const TRANSLATION_PROGRESS_TTL_MS = 7 * 24 * 60 * 60 * 1000;
const TRANSLATION_PROGRESS_SAVE_INTERVAL = 25;
const TRANSLATION_CHANNEL_FAILURE_LIMIT = 8;
const TRANSLATION_ADAPTIVE_SUCCESS_TO_INCREASE = 4;
const TRANSLATION_ADAPTIVE_COOLDOWN_MS = 120000;
const TRANSLATION_BATCH_SETTLE_DELAY_MS = 800;
const TRANSLATION_BATCH_FAILURE_SETTLE_DELAY_MS = 5000;
const TRANSLATION_BATCH_SPLIT_MAX_DEPTH = 2;
const TRANSLATION_CHANNEL_RECOVERY_COOLDOWN_MS = 180000;
const TRANSLATION_QA_REPAIR_MAX_ATTEMPTS = 2;
const TRANSLATION_QA_REPAIR_MAX_CONCURRENCY = 2;
const TRANSLATION_RETRY_DEEP_REPAIR_LIMIT = 60;
const TRANSLATION_AGNES_TARGET_RPM = 17;
const TRANSLATION_PREVIEW_MAX_ITEMS = 60;
const TRANSLATION_PREVIEW_RENDER_EVERY = 5;
const TRANSLATION_TASK_CHECKPOINT_BATCH_SIZE = 50;
const TRANSLATION_TASK_CHECKPOINT_FLUSH_MS = 1000;
const TRANSLATE_BATCH_IMPORT_SETTLE_DELAY_MS = 600;
const TAURI_BINARY_SAVE_ARRAY_LIMIT = 2 * 1024 * 1024;
const TAURI_BINARY_SAVE_CHUNK_SIZE = 512 * 1024;
const NEXUS_CLIENT_ERROR_LOG_KEY = 'nexus_client_error_log_v1';

function normalizeTranslationRepairFingerprint(value) {
    return String(value ?? '')
        .replace(/\r\n?/g, '\n')
        .trim();
}

function hasTranslationQaRepairChanged(previousTranslated, nextTranslated) {
    return normalizeTranslationRepairFingerprint(previousTranslated) !==
        normalizeTranslationRepairFingerprint(nextTranslated);
}

function shouldAttemptNextTranslationQaRepair(previousTranslated, nextTranslated, attempt, maxAttempts = TRANSLATION_QA_REPAIR_MAX_ATTEMPTS, allowRetryOnUnchanged = false) {
    if (attempt + 1 >= maxAttempts) return false;
    return allowRetryOnUnchanged || hasTranslationQaRepairChanged(previousTranslated, nextTranslated);
}

function getTranslationQaRepairConcurrency(configuredLimit, adaptiveLimit, taskCount) {
    const configured = Number.isFinite(Number(configuredLimit)) ? Number(configuredLimit) : 1;
    const adaptive = Number.isFinite(Number(adaptiveLimit)) ? Number(adaptiveLimit) : 1;
    const count = Number.isFinite(Number(taskCount)) ? Number(taskCount) : 0;
    if (count <= 0) return 1;
    return Math.max(1, Math.min(
        TRANSLATION_QA_REPAIR_MAX_CONCURRENCY,
        Math.max(1, configured),
        Math.max(1, adaptive),
        count
    ));
}

function isSplittableTranslationBatchError(error) {
    if (!error || error?.name === 'AbortError' || error?.message === 'TRANSLATION_CANCELLED') return false;
    if (typeof error === 'string') return false;

    const httpStatus = Number(error?.status || error?.statusCode || 0);
    if ((httpStatus >= 400 && httpStatus <= 599) || error?.isRateLimited || error?.isTimeout || error?.isQuotaDepleted) {
        return false;
    }
    if (error instanceof SyntaxError || error?.isOutputTruncated || error?.isEmptyEndTurn) return true;

    const diagnostic = `${error?.message || ''} ${error?.rawText || ''}`;
    return /批量翻译返回(?:数量不一致|空译文)|接口返回(?:为空|被截断)|JSON|Unexpected\s+(?:token|end)|unterminated|string array|数组.{0,8}(?:数量|长度|格式)|(?:parse|解析).{0,8}(?:JSON|数组)/i.test(diagnostic);
}

function splitTranslationTaskBatch(tasks = []) {
    if (!Array.isArray(tasks) || tasks.length <= 1) return [];
    const midpoint = Math.ceil(tasks.length / 2);
    return [tasks.slice(0, midpoint), tasks.slice(midpoint)].filter(batch => batch.length > 0);
}

function getTranslationBatchSplitPlan(tasks, error, depth = 0, maxDepth = TRANSLATION_BATCH_SPLIT_MAX_DEPTH) {
    if (!isSplittableTranslationBatchError(error) || Number(depth) >= Number(maxDepth)) return [];
    return splitTranslationTaskBatch(tasks);
}

function getTranslationTargetRpm(profile) {
    const configured = Number(profile?.translationRpm || profile?.requestsPerMinute || 0);
    if (Number.isFinite(configured) && configured > 0) {
        return Math.max(1, Math.min(600, configured));
    }
    return profile?.provider === 'agnes' ? TRANSLATION_AGNES_TARGET_RPM : 0;
}

function shouldDeferRetryQaRepair(options = {}) {
    return options.deferAutoQaRepair !== false;
}

function shouldUseTwoStageTranslationRetry(retryTasks, options = {}) {
    return Boolean(Array.isArray(retryTasks) && retryTasks.length > 0 && options.twoStageRetry !== false);
}

function shouldRunDeferredTranslationRepair(taskCount, limit = TRANSLATION_RETRY_DEEP_REPAIR_LIMIT) {
    const count = Math.max(0, Number(taskCount) || 0);
    const boundedLimit = Math.max(0, Number(limit) || 0);
    return count > 0 && count <= boundedLimit;
}

function createTranslationRpmPacer(getTargetRpm, onCancel = () => {}, waitMs = 100, timing = {}) {
    const now = typeof timing.now === 'function'
        ? timing.now
        : () => globalThis.performance?.now?.() ?? Date.now();
    const delay = typeof timing.delay === 'function'
        ? timing.delay
        : milliseconds => new Promise(resolve => setTimeout(resolve, Math.max(0, milliseconds)));
    let lastStartedAt = 0;
    let hasStarted = false;
    let blockedUntil = 0;
    let turnQueue = Promise.resolve();

    async function waitUntilReady(beforeStart = null) {
        while (true) {
            onCancel();
            const rpm = Math.max(0, Number(getTargetRpm?.()) || 0);
            const intervalMs = rpm > 0 ? Math.ceil(60000 / rpm) : 0;
            const currentTime = now();
            const intervalReadyAt = hasStarted ? lastStartedAt + intervalMs : currentTime;
            const readyAt = Math.max(intervalReadyAt, blockedUntil);
            const remainingMs = Math.max(0, readyAt - currentTime);
            if (remainingMs <= 0) {
                const startValue = typeof beforeStart === 'function' ? await beforeStart() : undefined;
                lastStartedAt = now();
                hasStarted = true;
                return typeof beforeStart === 'function'
                    ? { startedAt: lastStartedAt, value: startValue }
                    : lastStartedAt;
            }
            await delay(Math.min(remainingMs, Math.max(1, Number(waitMs) || 100)));
        }
    }

    return {
        waitForTurn(beforeStart = null) {
            const turn = turnQueue.then(() => waitUntilReady(beforeStart));
            turnQueue = turn.catch(() => {});
            return turn;
        },
        deferFor(milliseconds) {
            const durationMs = Math.max(0, Math.min(60000, Number(milliseconds) || 0));
            if (durationMs > 0) blockedUntil = Math.max(blockedUntil, now() + durationMs);
        },
        snapshot() {
            return { lastStartedAt, blockedUntil, hasStarted };
        }
    };
}

function createTranslationRequestGate(concurrencyLimiter, rpmPacer, waitUntilActive = async () => {}) {
    return {
        async acquire() {
            if (!rpmPacer?.waitForTurn) {
                await waitUntilActive();
                return concurrencyLimiter ? await concurrencyLimiter.acquire() : (() => {});
            }
            const turn = await rpmPacer.waitForTurn(async () => {
                await waitUntilActive();
                const release = concurrencyLimiter ? await concurrencyLimiter.acquire() : null;
                try {
                    await waitUntilActive();
                    return release || (() => {});
                } catch (error) {
                    release?.();
                    throw error;
                }
            });
            return turn?.value || (() => {});
        },
        deferFor(milliseconds) {
            rpmPacer?.deferFor?.(milliseconds);
        },
        getActiveCount() {
            return concurrencyLimiter?.getActiveCount?.() || 0;
        }
    };
}

function createTranslationRequestLimiter(getCapacity, onCancel = () => {}, waitMs = 50) {
    let activeCount = 0;
    const readCapacity = () => Math.max(1, Number(getCapacity?.()) || 1);

    return {
        async acquire() {
            while (activeCount >= readCapacity()) {
                onCancel();
                await new Promise(resolve => setTimeout(resolve, Math.max(0, waitMs)));
            }
            onCancel();
            activeCount++;
            let released = false;
            return () => {
                if (released) return;
                released = true;
                activeCount = Math.max(0, activeCount - 1);
            };
        },
        getActiveCount() {
            return activeCount;
        }
    };
}

async function runWithTranslationRequestLimiter(limiter, request) {
    let releaseRequest = null;
    try {
        releaseRequest = limiter ? await limiter.acquire() : null;
        return await request();
    } catch (error) {
        const retryAfterMs = Number(error?.retryAfterMs || 0);
        if (retryAfterMs > 0) limiter?.deferFor?.(retryAfterMs);
        throw error;
    } finally {
        releaseRequest?.();
    }
}

let translationProgressDbPromise = null;
let translationProgressWriteEpoch = 0;
let pendingTranslationTaskCheckpointMap = new Map();
let pendingTranslationTaskCheckpointTimer = null;

function normalizeClientError(error) {
    if (!error) return { name: 'Error', message: '未知错误', stack: '' };
    return {
        name: error.name || error.constructor?.name || 'Error',
        message: error.message || String(error),
        stack: error.stack || ''
    };
}

function recordClientError(source, error, extra = {}) {
    const normalized = normalizeClientError(error);
    const entry = {
        source,
        ...normalized,
        extra,
        url: location.href,
        timestamp: new Date().toISOString()
    };
    try {
        const previous = JSON.parse(localStorage.getItem(NEXUS_CLIENT_ERROR_LOG_KEY) || '[]');
        previous.unshift(entry);
        localStorage.setItem(NEXUS_CLIENT_ERROR_LOG_KEY, JSON.stringify(previous.slice(0, 30)));
    } catch (storageError) {
        console.warn('Client error log skipped:', storageError);
    }
    console.error('[NEXUS client error]', entry);
}

function installClientErrorHandlers() {
    if (window.__nexusClientErrorHandlersInstalled) return;
    window.__nexusClientErrorHandlersInstalled = true;
    window.addEventListener('error', event => {
        recordClientError('window.error', event.error || event.message, {
            filename: event.filename || '',
            line: event.lineno || 0,
            column: event.colno || 0
        });
    });
    window.addEventListener('unhandledrejection', event => {
        recordClientError('unhandledrejection', event.reason || 'Promise rejection');
    });
}

installClientErrorHandlers();

function toIdbPromise(request) {
    return new Promise((resolve, reject) => {
        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error || new Error('IndexedDB request failed'));
    });
}

function waitForIdbTransaction(transaction) {
    return new Promise((resolve, reject) => {
        transaction.oncomplete = () => resolve();
        transaction.onerror = () => reject(transaction.error || new Error('IndexedDB transaction failed'));
        transaction.onabort = () => reject(transaction.error || new Error('IndexedDB transaction aborted'));
    });
}

function openTranslationProgressDb() {
    if (!globalThis.indexedDB) {
        return Promise.reject(new Error('IndexedDB is not available'));
    }
    if (translationProgressDbPromise) return translationProgressDbPromise;

    translationProgressDbPromise = new Promise((resolve, reject) => {
        const request = indexedDB.open(TRANSLATION_PROGRESS_DB_NAME, TRANSLATION_PROGRESS_DB_VERSION);
        request.onupgradeneeded = () => {
            const db = request.result;
            if (!db.objectStoreNames.contains(TRANSLATION_PROGRESS_META_STORE)) {
                db.createObjectStore(TRANSLATION_PROGRESS_META_STORE, { keyPath: 'id' });
            }
            if (!db.objectStoreNames.contains(TRANSLATION_PROGRESS_TASK_STORE)) {
                db.createObjectStore(TRANSLATION_PROGRESS_TASK_STORE, { keyPath: 'taskKey' });
            }
        };
        request.onsuccess = () => resolve(request.result);
        request.onerror = () => {
            translationProgressDbPromise = null;
            reject(request.error || new Error('Failed to open translation progress database'));
        };
        request.onblocked = () => {
            translationProgressDbPromise = null;
            reject(new Error('Translation progress database upgrade is blocked'));
        };
    });

    return translationProgressDbPromise;
}

function isBlankTranslationResult(text) {
    return String(text ?? '').trim().length === 0;
}

function isMarkedTranslationFailure(text) {
    return String(text ?? '').trimStart().startsWith('[翻译失败');
}

function isMissingTranslationResult(text) {
    const value = String(text ?? '').trim();
    if (!value) return true;
    if (!isMarkedTranslationFailure(value)) return false;
    const failureLabel = value.match(/^\[翻译失败[^\]]*\]/)?.[0] || '';
    return /返回空译文|未返回结果|空返回/.test(failureLabel);
}

function compactTranslationProgressEntry(entry) {
    if (!entry?.taskKey) return null;
    const translatedText = String(entry.translatedText ?? '');
    const statusFromText = isMissingTranslationResult(translatedText)
        ? 'missing'
        : (isMarkedTranslationFailure(translatedText) ? 'failed' : '');
    return {
        taskKey: entry.taskKey,
        status: entry.manualResolutionValid
            ? 'success'
            : (statusFromText || entry.status || 'success'),
        translatedText,
        qaStatus: entry.qaStatus || '',
        completenessRisk: entry.completenessRisk || '',
        actionSuggestion: entry.actionSuggestion || '',
        error: entry.error || '',
        userDecision: entry.userDecision || '',
        revisedText: entry.revisedText || '',
        decisionNote: entry.decisionNote || '',
        manualResolutionValid: Boolean(entry.manualResolutionValid),
        revisionApplied: Boolean(entry.revisionApplied)
    };
}

function compactTranslationProgressEntries(entries = []) {
    return entries
        .map(compactTranslationProgressEntry)
        .filter(Boolean);
}

function buildTranslationProgressRecord(data, includeTasksForFallback = false) {
    const completedTasks = includeTasksForFallback
        ? compactTranslationProgressEntries(data.completedTasks || [])
        : [];
    return {
        id: TRANSLATION_PROGRESS_ACTIVE_ID,
        version: 3,
        timestamp: Date.now(),
        fileName: data.fileName,
        sourceSignature: data.sourceSignature || '',
        totalRows: data.totalRows,
        totalTasks: data.totalTasks || 0,
        currentRow: data.currentRow,
        successCount: data.successCount,
        failCount: data.failCount,
        selectedColumns: data.selectedColumns,
        targetLang: data.targetLang,
        selectedProfileIds: data.selectedProfileIds || [],
        selectedSourceIds: data.selectedSourceIds || [],
        translateStrategy: data.translateStrategy || 'source-reference',
        referenceColumn: Number.isInteger(data.referenceColumn) ? data.referenceColumn : null,
        runCreatedAt: data.runCreatedAt || null,
        completedTasks: includeTasksForFallback ? completedTasks : []
    };
}

async function saveTranslationProgress(data) {
    const epoch = translationProgressWriteEpoch;
    const record = buildTranslationProgressRecord(data, false);

    try {
        const db = await openTranslationProgressDb();
        if (epoch !== translationProgressWriteEpoch) return false;
        const transaction = db.transaction(TRANSLATION_PROGRESS_META_STORE, 'readwrite');
        transaction.objectStore(TRANSLATION_PROGRESS_META_STORE).put(record);
        await waitForIdbTransaction(transaction);
        localStorage.removeItem(TRANSLATION_STORAGE_KEY);
        return true;
    } catch (error) {
        console.warn('IndexedDB progress save failed, falling back to localStorage:', error);
        try {
            const fallbackRecord = buildTranslationProgressRecord(data, true);
            localStorage.setItem(TRANSLATION_STORAGE_KEY, JSON.stringify(fallbackRecord));
            return true;
        } catch (storageError) {
            console.warn('Translation progress save skipped because storage is full or unavailable:', storageError);
            return false;
        }
    }
}

async function saveTranslationTaskProgressBatch(entries) {
    const compactEntries = compactTranslationProgressEntries(entries);
    if (!compactEntries.length) return true;

    const epoch = translationProgressWriteEpoch;
    try {
        const db = await openTranslationProgressDb();
        if (epoch !== translationProgressWriteEpoch) return false;
        const transaction = db.transaction(TRANSLATION_PROGRESS_TASK_STORE, 'readwrite');
        const store = transaction.objectStore(TRANSLATION_PROGRESS_TASK_STORE);
        compactEntries.forEach(entry => store.put(entry));
        await waitForIdbTransaction(transaction);
        return true;
    } catch (error) {
        console.warn('Task checkpoint save failed; metadata fallback will be used if available:', error);
        return false;
    }
}

async function deleteTranslationTaskProgress(taskKey) {
    if (!taskKey) return true;
    try {
        const db = await openTranslationProgressDb();
        const transaction = db.transaction(TRANSLATION_PROGRESS_TASK_STORE, 'readwrite');
        transaction.objectStore(TRANSLATION_PROGRESS_TASK_STORE).delete(taskKey);
        await waitForIdbTransaction(transaction);
        return true;
    } catch (error) {
        console.warn('Old translation task checkpoint cleanup failed:', error);
        return false;
    }
}

function queueTranslationTaskProgress(entry) {
    const compactEntry = compactTranslationProgressEntry(entry);
    if (!compactEntry) return;
    pendingTranslationTaskCheckpointMap.set(compactEntry.taskKey, compactEntry);

    if (pendingTranslationTaskCheckpointMap.size >= TRANSLATION_TASK_CHECKPOINT_BATCH_SIZE) {
        flushTranslationTaskProgress();
        return;
    }

    if (!pendingTranslationTaskCheckpointTimer) {
        pendingTranslationTaskCheckpointTimer = setTimeout(() => {
            flushTranslationTaskProgress();
        }, TRANSLATION_TASK_CHECKPOINT_FLUSH_MS);
    }
}

async function flushTranslationTaskProgress() {
    if (pendingTranslationTaskCheckpointTimer) {
        clearTimeout(pendingTranslationTaskCheckpointTimer);
        pendingTranslationTaskCheckpointTimer = null;
    }
    const entries = [...pendingTranslationTaskCheckpointMap.values()];
    pendingTranslationTaskCheckpointMap.clear();
    if (!entries.length) return true;
    return saveTranslationTaskProgressBatch(entries);
}

async function loadTranslationProgress() {
    let progress = null;

    try {
        const db = await openTranslationProgressDb();
        const metaTransaction = db.transaction(TRANSLATION_PROGRESS_META_STORE, 'readonly');
        progress = await toIdbPromise(metaTransaction.objectStore(TRANSLATION_PROGRESS_META_STORE).get(TRANSLATION_PROGRESS_ACTIVE_ID));
        if (progress) {
            const taskTransaction = db.transaction(TRANSLATION_PROGRESS_TASK_STORE, 'readonly');
            progress.completedTasks = await toIdbPromise(taskTransaction.objectStore(TRANSLATION_PROGRESS_TASK_STORE).getAll());
        }
    } catch (error) {
        console.warn('IndexedDB progress load failed, trying localStorage:', error);
    }

    if (!progress) {
        const stored = localStorage.getItem(TRANSLATION_STORAGE_KEY);
        if (!stored) return null;
        try {
            progress = JSON.parse(stored);
        } catch {
            return null;
        }
    }

    try {
        const age = Date.now() - progress.timestamp;
        if (age > TRANSLATION_PROGRESS_TTL_MS) {
            clearTranslationProgress();
            return null;
        }
        return progress;
    } catch {
        return null;
    }
}

function clearTranslationProgress() {
    translationProgressWriteEpoch++;
    if (pendingTranslationTaskCheckpointTimer) {
        clearTimeout(pendingTranslationTaskCheckpointTimer);
        pendingTranslationTaskCheckpointTimer = null;
    }
    pendingTranslationTaskCheckpointMap.clear();
    localStorage.removeItem(TRANSLATION_STORAGE_KEY);
    openTranslationProgressDb()
        .then(db => {
            const transaction = db.transaction(
                [TRANSLATION_PROGRESS_META_STORE, TRANSLATION_PROGRESS_TASK_STORE],
                'readwrite'
            );
            transaction.objectStore(TRANSLATION_PROGRESS_META_STORE).clear();
            transaction.objectStore(TRANSLATION_PROGRESS_TASK_STORE).clear();
            return waitForIdbTransaction(transaction);
        })
        .catch(error => console.warn('Translation progress clear skipped:', error));
}

function downloadWorkbookFile(workbook, fileName, options = {}) {
    const arrayBuffer = writeWorkbookArrayBuffer(workbook, options);
    if (arrayBuffer && typeof arrayBuffer.then === 'function') {
        return arrayBuffer.then(buffer => {
            downloadWorkbookArrayBuffer(buffer, fileName);
            return fileName;
        });
    }

    downloadWorkbookArrayBuffer(arrayBuffer, fileName);
    return Promise.resolve(fileName);
}

function downloadWorkbookArrayBuffer(arrayBuffer, fileName) {
    const blob = new Blob([arrayBuffer], {
        type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
    });
    downloadBlobFile(blob, fileName);
}

function downloadBlobFile(blob, fileName) {
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = fileName;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
}

function waitForBrowserFrame() {
    return new Promise(resolve => setTimeout(resolve, 0));
}

async function saveWorkbookFileInChunks(arrayBuffer, fileName, onProgress = null) {
    const invoke = window.__TAURI__?.core?.invoke;
    if (!invoke) {
        throw new Error('Tauri save API is unavailable');
    }

    const session = await invoke('start_binary_report_save', { filename: fileName });
    const bytes = new Uint8Array(arrayBuffer);
    const total = bytes.byteLength;
    try {
        for (let offset = 0; offset < total; offset += TAURI_BINARY_SAVE_CHUNK_SIZE) {
            const end = Math.min(offset + TAURI_BINARY_SAVE_CHUNK_SIZE, total);
            const chunk = bytes.slice(offset, end);
            await invoke('append_binary_report_chunk', {
                id: session.id,
                bytes: Array.from(chunk)
            });
            const percent = total > 0 ? Math.min(100, Math.round((end / total) * 100)) : 100;
            onProgress?.('save', `正在分块保存到下载目录... ${percent}%`);
            await waitForBrowserFrame();
        }
        const response = await invoke('finish_binary_report_save', { id: session.id });
        return String(response?.path || session.path || fileName);
    } catch (error) {
        try {
            await invoke('abort_binary_report_save', { id: session.id });
        } catch (abortError) {
            console.warn('Abort chunked save skipped:', abortError);
        }
        throw error;
    }
}

async function saveWorkbookFile(workbook, fileName, options = {}) {
    const arrayBuffer = await writeWorkbookArrayBuffer(workbook, options);
    const onProgress = typeof options.onProgress === 'function' ? options.onProgress : null;
    const invoke = window.__TAURI__?.core?.invoke;
    const byteLength = Number(arrayBuffer?.byteLength || 0);

    if (invoke) {
        try {
            if (byteLength <= TAURI_BINARY_SAVE_ARRAY_LIMIT) {
                onProgress?.('save', '正在保存到下载目录...');
                await waitForBrowserFrame();
                const response = await invoke('save_binary_report_to_downloads', {
                    filename: fileName,
                    bytes: Array.from(new Uint8Array(arrayBuffer))
                });
                return String(response?.path || fileName);
            }

            onProgress?.('save', '文件较大，正在使用稳定分块保存...');
            await waitForBrowserFrame();
            return await saveWorkbookFileInChunks(arrayBuffer, fileName, onProgress);
        } catch (error) {
            console.warn('Tauri workbook save failed, falling back to browser download:', error);
            onProgress?.('save', '桌面保存命令不可用，改用浏览器下载...');
            await waitForBrowserFrame();
        }
    }

    const blob = new Blob([arrayBuffer], {
        type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
    });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = fileName;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    return fileName;
}

async function writeWorkbookArrayBuffer(workbook, options = {}) {
    const onProgress = typeof options.onProgress === 'function' ? options.onProgress : null;
    onProgress?.('write', '正在写入 XLSX 工作簿，大文件可能需要等待一会儿...');
    await waitForBrowserFrame();

    const arrayBuffer = XLSX.write(workbook, { bookType: 'xlsx', type: 'array' });
    const listValidations = Array.isArray(options.listValidations) ? options.listValidations : [];
    const patchXlsx = typeof options.patchXlsx === 'function' ? options.patchXlsx : null;
    let result = arrayBuffer;
    if (listValidations.length > 0) {
        onProgress?.('validation', '正在添加 Excel 下拉选项...');
        await waitForBrowserFrame();
        result = await applyXlsxListValidations(arrayBuffer, listValidations);
    }
    if (patchXlsx) {
        onProgress?.('style', '正在保留源文件样式并处理报告标色...');
        await waitForBrowserFrame();
        result = await patchXlsx(result, workbook);
    }
    return result;
}

async function applyXlsxListValidations(arrayBuffer, validations) {
    if (typeof JSZip === 'undefined') {
        console.warn('Excel list validation skipped: JSZip is unavailable.');
        return arrayBuffer;
    }

    try {
        const zip = await JSZip.loadAsync(arrayBuffer);
        const grouped = new Map();
        validations.forEach(validation => {
            if (!validation?.sqref || !Array.isArray(validation.options) || validation.options.length === 0) return;
            const sheetIndex = Number.isInteger(validation.sheetIndex) ? validation.sheetIndex : 1;
            const sheetPath = validation.sheetPath || `xl/worksheets/sheet${sheetIndex}.xml`;
            if (!grouped.has(sheetPath)) grouped.set(sheetPath, []);
            grouped.get(sheetPath).push(validation);
        });

        for (const [sheetPath, sheetValidations] of grouped.entries()) {
            const sheetFile = zip.file(sheetPath);
            if (!sheetFile) continue;
            const xml = await sheetFile.async('string');
            zip.file(sheetPath, injectWorksheetListValidations(xml, sheetValidations));
        }

        return zip.generateAsync({ type: 'arraybuffer', compression: 'STORE' });
    } catch (error) {
        console.warn('Excel list validation patch skipped:', error);
        return arrayBuffer;
    }
}

function injectWorksheetListValidations(xml, validations) {
    const nodes = validations
        .map(buildListValidationXml)
        .filter(Boolean);
    if (nodes.length === 0) return xml;

    const dataValidationsXml = `<dataValidations count="${nodes.length}">${nodes.join('')}</dataValidations>`;
    const cleanXml = xml.replace(/<dataValidations\b[\s\S]*?<\/dataValidations>/g, '');
    const insertBeforeTags = ['<hyperlinks', '<pageMargins', '<ignoredErrors', '<drawing', '<legacyDrawing', '<extLst', '</worksheet>'];
    const insertIndex = insertBeforeTags
        .map(tag => cleanXml.indexOf(tag))
        .filter(index => index >= 0)
        .sort((a, b) => a - b)[0];

    if (insertIndex == null) return `${cleanXml}${dataValidationsXml}`;
    return `${cleanXml.slice(0, insertIndex)}${dataValidationsXml}${cleanXml.slice(insertIndex)}`;
}

function buildListValidationXml(validation) {
    if (!validation?.sqref || !Array.isArray(validation.options) || validation.options.length === 0) return '';
    const formula = `"${validation.options.map(option => String(option ?? '').replace(/"/g, '""')).join(',')}"`;
    const attrs = {
        type: 'list',
        allowBlank: '1',
        showErrorMessage: '1',
        showInputMessage: '1',
        sqref: validation.sqref,
        promptTitle: validation.promptTitle,
        prompt: validation.prompt,
        errorTitle: validation.errorTitle,
        error: validation.error
    };
    return `<dataValidation${xmlAttributes(attrs)}><formula1>${escapeXmlText(formula)}</formula1></dataValidation>`;
}

function xmlAttributes(attrs) {
    return Object.entries(attrs)
        .filter(([, value]) => value !== undefined && value !== null && value !== '')
        .map(([key, value]) => ` ${key}="${escapeXmlText(value)}"`)
        .join('');
}

function escapeXmlText(value) {
    return String(value)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;');
}

const TRANSLATION_PROJECTS_KEY = 'translationProjects';
const DEFAULT_TRANSLATION_PROJECT_KEY = 'nexus_default_translation_project';
const GLOSSARY_LIBRARY_KEY = 'nexus_glossary_library';
const API_PROFILES_KEY = 'nexus_api_profiles';
const ACTIVE_API_PROFILE_KEY = 'nexus_active_api_profile';
const API_REQUEST_TIMEOUT_MS = 240000;
const API_PREFLIGHT_TIMEOUT_MS = 45000;

function formatDurationSeconds(ms) {
    return `${Math.max(1, Math.ceil(ms / 1000))} 秒`;
}

function createApiTimeoutError(timeoutMs) {
    const error = new Error(`API 请求超时（超过 ${formatDurationSeconds(timeoutMs)}）。可能是接口繁忙、网络不稳定、单通道并发过高，或当前批次文本过长。`);
    error.name = 'ApiTimeoutError';
    error.isTimeout = true;
    return error;
}

function createAbortError() {
    return new DOMException('Request aborted', 'AbortError');
}

async function withHardTimeout(promise, timeoutMs = API_REQUEST_TIMEOUT_MS, signal = null) {
    if (signal?.aborted) {
        throw createAbortError();
    }

    let timeoutId = null;
    let abortHandler = null;
    const timeoutPromise = new Promise((_, reject) => {
        if (timeoutMs > 0) {
            timeoutId = setTimeout(() => {
                reject(createApiTimeoutError(timeoutMs));
            }, timeoutMs);
        }

        if (signal) {
            abortHandler = () => reject(createAbortError());
            signal.addEventListener('abort', abortHandler, { once: true });
        }
    });

    try {
        return await Promise.race([promise, timeoutPromise]);
    } finally {
        if (timeoutId) clearTimeout(timeoutId);
        if (signal && abortHandler) {
            signal.removeEventListener('abort', abortHandler);
        }
    }
}

function loadGlossaryLibrary() {
    const stored = localStorage.getItem(GLOSSARY_LIBRARY_KEY);
    if (!stored) return [];

    try {
        const library = JSON.parse(stored);
        return Array.isArray(library) ? library : [];
    } catch {
        return [];
    }
}

function saveGlossaryLibrary(library) {
    localStorage.setItem(GLOSSARY_LIBRARY_KEY, JSON.stringify(library));
}

function makeStableId(text) {
    let hash = 0;
    for (let i = 0; i < text.length; i++) {
        hash = ((hash << 5) - hash + text.charCodeAt(i)) >>> 0;
    }
    return hash.toString(36);
}

function makePromptCacheKey(namespace, text) {
    return `${namespace}_${makeStableId(String(text || ''))}`.replace(/[^a-zA-Z0-9_-]/g, '_').slice(0, 64);
}

function hasCjkText(text) {
    return /[\u3400-\u9fff]/.test(String(text || ''));
}

function hasLatinText(text) {
    return /[A-Za-z]/.test(String(text || ''));
}

function normalizeHeaderText(text) {
    return String(text || '').trim().toLowerCase().replace(/\s+/g, ' ');
}

function isIdLikeGlossaryValue(value) {
    const text = String(value || '').trim();
    if (!text) return false;
    const normalized = normalizeHeaderText(text);
    return normalized === 'id' ||
        normalized === 'string id' ||
        normalized === 'key' ||
        normalized === '编号' ||
        normalized === '序号' ||
        /^[\d._-]+$/.test(text);
}

function isChineseGlossaryHeader(value) {
    const text = normalizeHeaderText(value);
    return text.includes('中文') ||
        text.includes('简体') ||
        text.includes('繁体') ||
        text.includes('chinese') ||
        text.includes('zh-cn') ||
        text.includes('zh_cn');
}

function isEnglishGlossaryHeader(value) {
    const text = normalizeHeaderText(value);
    return text.includes('英文') ||
        text.includes('英语') ||
        text.includes('english') ||
        text === 'en' ||
        text.includes('en-us') ||
        text.includes('en_us');
}

function isGlossaryHeaderRow(source, target, type) {
    const sourceText = normalizeHeaderText(source);
    const targetText = normalizeHeaderText(target);
    const typeText = normalizeHeaderText(type);
    return (sourceText.includes('术语') && (targetText.includes('译') || targetText.includes('translation'))) ||
        (sourceText.includes('term') && (targetText.includes('translation') || targetText.includes('target'))) ||
        (isIdLikeGlossaryValue(source) && isChineseGlossaryHeader(target) && isEnglishGlossaryHeader(type));
}

function repairLegacyGlossaryTerm(source, target, type) {
    if (isGlossaryHeaderRow(source, target, type)) return null;

    if (isIdLikeGlossaryValue(source) && hasCjkText(target) && hasLatinText(type)) {
        return {
            source: String(target || '').trim(),
            target: String(type || '').trim(),
            type: ''
        };
    }

    return {
        source: String(source || '').trim(),
        target: String(target || '').trim(),
        type: String(type || '').trim()
    };
}

function normalizeGlossaryTerms(terms) {
    return (terms || []).map(term => {
        const source = term.source ?? term.term ?? '';
        const target = term.target ?? term.translation ?? '';
        const type = term.type ?? '';
        const count = Number(term.count || 1);
        const confidence = Number(term.confidence ?? term.score ?? 0);
        const repaired = repairLegacyGlossaryTerm(source, target, type);
        if (!repaired) return null;

        return {
            source: repaired.source,
            target: repaired.target,
            type: repaired.type,
            originalType: String(term.originalType || term.rawType || repaired.type || '').trim(),
            organizedType: String(term.organizedType || term.normalizedType || term.standardType || '').trim(),
            secondaryType: String(term.secondaryType || term.subType || term.subcategory || '').trim(),
            categoryReason: String(term.categoryReason || term.classificationReason || term.reason || '').trim(),
            mergeNote: String(term.mergeNote || term.duplicateNote || '').trim(),
            count: Number.isFinite(count) ? count : 1,
            confidence: Number.isFinite(confidence) ? confidence : 0,
            note: String(term.note || term.reason || term.description || '').trim(),
            extractionSource: String(term.extractionSource || term.origin || '').trim(),
            extractionBatch: String(term.extractionBatch || term.batch || '').trim(),
            referenceId: String(term.referenceId || term.id || term.rowId || term.key || '').trim(),
            referenceRows: String(term.referenceRows || term.rows || term.rowNumbers || '').trim(),
            originalTranslation: String(term.originalTranslation || term.currentTarget || term.originalTarget || term.observedTarget || '').trim(),
            finalTranslation: String(term.finalTranslation || term.finalTarget || term.revisedTarget || term.fixedTarget || '').trim(),
            aiSuggestedTranslation: String(term.aiSuggestedTranslation || term.suggestedTranslation || term.recommendedTranslation || '').trim(),
            translationDecision: String(term.translationDecision || '').trim(),
            semanticScope: String(term.semanticScope || term.contextScope || term.scope || term.usageScope || '').trim(),
            contextText: String(term.contextText || term.context || term.usageContext || '').trim(),
            english: String(term.english || term.en || term.target || term.translation || '').trim(),
            japanese: String(term.japanese || term.ja || term.jp || '').trim(),
            korean: String(term.korean || term.ko || '').trim(),
            traditionalChinese: String(term.traditionalChinese || term.zhTW || term['zh-TW'] || '').trim(),
            french: String(term.french || term.fr || '').trim(),
            german: String(term.german || term.de || '').trim(),
            spanish: String(term.spanish || term.es || '').trim(),
            portuguese: String(term.portuguese || term.pt || '').trim(),
            russian: String(term.russian || term.ru || '').trim(),
            thai: String(term.thai || term.th || '').trim(),
            vietnamese: String(term.vietnamese || term.vi || '').trim(),
            indonesian: String(term.indonesian || term.idTarget || term.idTranslation || '').trim(),
            termEntryType: String(term.termEntryType || term.entryType || term.glossaryTier || '').trim(),
            termValueLevel: String(term.termValueLevel || term.termValue || term.valueLevel || '').trim(),
            termStandardReason: String(term.termStandardReason || term.standardReason || '').trim(),
            termAction: String(term.termAction || term.action || '').trim(),
            qualityStatus: String(term.qualityStatus || term.qaStatus || '').trim(),
            qualityIssues: String(term.qualityIssues || term.issues || '').trim(),
            qualitySuggestion: String(term.qualitySuggestion || term.suggestion || '').trim()
        };
    }).filter(term => term?.source);
}

function getGlossaryEffectiveTarget(term) {
    return String(term?.finalTranslation || term?.finalTarget || term?.revisedTarget || term?.fixedTarget || term?.target || term?.translation || '').trim();
}

function getGlossaryOriginDisplayLabel(origin) {
    if (origin === 'extracted') return '提取生成';
    if (origin === 'reviewed') return '人工审核';
    return '上传记录';
}

function splitGlossaryReferenceList(value) {
    return String(value || '')
        .split(/[;,，；\s]+/)
        .map(item => item.trim())
        .filter(Boolean);
}

function extractGlossaryReferenceNumbers(value) {
    const numbers = [];
    splitGlossaryReferenceList(value).forEach(item => {
        const matches = String(item || '').match(/\d+/g) || [];
        matches.forEach(match => {
            const number = Number(match);
            if (Number.isFinite(number)) numbers.push(number);
        });
    });
    return numbers;
}

function glossaryTermAppliesToTask(term, task = null) {
    if (!term || !task) return true;
    const rowNumbers = extractGlossaryReferenceNumbers(term.referenceRows);
    const ids = new Set(splitGlossaryReferenceList(term.referenceId).map(item => normalizeHeaderText(item)).filter(Boolean));
    if (rowNumbers.length === 0 && ids.size === 0) return true;

    const taskRows = [
        task.rowIndex,
        Number.isInteger(task.rowIndex) ? task.rowIndex + 1 : null,
        task.originalRowNumber,
        task.originalReferences?.['原始行号']
    ].map(Number).filter(Number.isFinite);
    const rowMatch = rowNumbers.length > 0 && rowNumbers.some(row => taskRows.includes(row));

    const taskIds = [
        task.id,
        task.referenceId,
        task.originalReferences?.['原始行号'],
        ...Object.values(task.originalReferences || {})
    ].map(value => normalizeHeaderText(value)).filter(Boolean);
    const idMatch = ids.size > 0 && taskIds.some(id => ids.has(id));
    return rowMatch || idMatch;
}

function getGlossaryOrganizedType(term) {
    return String(term?.organizedType || term?.normalizedType || term?.standardType || term?.type || '').trim();
}

function parseDelimitedText(text, delimiter = ',') {
    const rows = [];
    let row = [];
    let cell = '';
    let quoted = false;
    const source = String(text || '').replace(/^\uFEFF/, '');

    for (let index = 0; index < source.length; index++) {
        const char = source[index];
        if (char === '"') {
            if (quoted && source[index + 1] === '"') {
                cell += '"';
                index++;
            } else {
                quoted = !quoted;
            }
            continue;
        }

        if (char === delimiter && !quoted) {
            row.push(cell);
            cell = '';
            continue;
        }

        if ((char === '\n' || char === '\r') && !quoted) {
            if (char === '\r' && source[index + 1] === '\n') index++;
            row.push(cell);
            rows.push(row);
            row = [];
            cell = '';
            continue;
        }

        cell += char;
    }

    row.push(cell);
    rows.push(row);

    return rows
        .map(currentRow => currentRow.map(value => String(value ?? '').trim()))
        .filter((currentRow, index) => index < rows.length - 1 || currentRow.some(Boolean));
}

function detectDelimitedTextSeparator(text) {
    const candidates = [',', '\t', ';', '|'];
    const sample = String(text || '')
        .replace(/^\uFEFF/, '')
        .split(/\r?\n/)
        .filter(line => line.trim())
        .slice(0, 20);
    if (!sample.length) return ',';

    const scored = candidates.map(delimiter => {
        const widths = sample.map(line => parseDelimitedText(line, delimiter)[0]?.length || 0);
        const usefulWidths = widths.filter(width => width > 1);
        const averageWidth = usefulWidths.reduce((sum, width) => sum + width, 0) / Math.max(1, usefulWidths.length);
        const stableWidthCount = new Map();
        usefulWidths.forEach(width => stableWidthCount.set(width, (stableWidthCount.get(width) || 0) + 1));
        const stability = Math.max(0, ...stableWidthCount.values());
        return {
            delimiter,
            score: usefulWidths.length * 20 + averageWidth * 3 + stability * 8
        };
    }).sort((a, b) => b.score - a.score);

    return scored[0]?.score > 0 ? scored[0].delimiter : ',';
}

function normalizeDelimitedRows(sheetRows, rawText) {
    const rows = Array.isArray(sheetRows) ? sheetRows : [];
    const firstRows = rows.slice(0, 8);
    const getNonEmptyCells = row => (Array.isArray(row) ? row : [row])
        .map(value => String(value ?? '').trim())
        .filter(Boolean);
    const looksCollapsed = firstRows.some(row => {
        const nonEmptyCells = getNonEmptyCells(row);
        if (nonEmptyCells.length !== 1) return false;
        const value = nonEmptyCells[0];
        return /[,;\t|]/.test(value) && /(原文|术语|译文|英文|source|target|translation|term)/i.test(value);
    });

    if (!looksCollapsed) {
        return rows.map(row => Array.isArray(row) ? row : [row]);
    }

    const collapsedText = rows
        .map(row => getNonEmptyCells(row)[0] || '')
        .join('\n');
    const parseCandidates = [rawText, collapsedText]
        .map(text => String(text || '').trim())
        .filter(Boolean)
        .map(text => {
            const delimiter = detectDelimitedTextSeparator(text);
            const parsedRows = parseDelimitedText(text, delimiter);
            const width = Math.max(0, ...parsedRows.slice(0, 8).map(row => row.length));
            return { parsedRows, width };
        })
        .sort((a, b) => b.width - a.width);
    return parseCandidates[0]?.width > 1 ? parseCandidates[0].parsedRows : rows;
}

async function readSpreadsheetRows(file) {
    const extension = file.name.split('.').pop().toLowerCase();

    if (extension === 'csv') {
        const { text } = await readCSVWithEncoding(file);
        const workbook = XLSX.read(text, { type: 'string', cellDates: true });
        const sheetName = workbook.SheetNames[0];
        const sheet = workbook.Sheets[sheetName];
        const sheetRows = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: '' });
        return {
            rows: normalizeDelimitedRows(sheetRows, text),
            text,
            workbook,
            sheetName
        };
    }

    const arrayBuffer = await file.arrayBuffer();
    const workbook = XLSX.read(arrayBuffer, { type: 'array', cellDates: true });
    const sheetName = workbook.SheetNames[0];
    const sheet = workbook.Sheets[sheetName];
    return {
        rows: normalizeDelimitedRows(XLSX.utils.sheet_to_json(sheet, { header: 1, defval: '' }), ''),
        text: XLSX.utils.sheet_to_csv(sheet),
        workbook,
        sheetName
    };
}

async function readSpreadsheetSheets(file) {
    const extension = file.name.split('.').pop().toLowerCase();

    if (extension === 'csv') {
        const { text, encoding } = await readCSVWithEncoding(file);
        const workbook = XLSX.read(text, { type: 'string', cellDates: true });
        const sheetName = workbook.SheetNames[0] || 'CSV';
        const sheet = workbook.Sheets[sheetName];
        const sheetRows = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: '' });
        return {
            encoding,
            workbook,
            sheets: [{
                sheetName: 'CSV',
                rows: normalizeDelimitedRows(sheetRows, text),
                hidden: false,
                hiddenState: 'visible'
            }]
        };
    }

    const arrayBuffer = await file.arrayBuffer();
    const workbook = XLSX.read(arrayBuffer, { type: 'array', cellDates: true });
    const workbookSheets = workbook?.Workbook?.Sheets || [];
    return {
        encoding: 'N/A (Excel)',
        workbook,
        sheets: workbook.SheetNames.map((sheetName, sheetIndex) => {
            const sheetMeta = workbookSheets[sheetIndex] ||
                workbookSheets.find(sheet => sheet?.name === sheetName || sheet?.Name === sheetName);
            const hiddenCode = Number(sheetMeta?.Hidden || 0);
            return {
                sheetName,
                rows: normalizeDelimitedRows(XLSX.utils.sheet_to_json(workbook.Sheets[sheetName], { header: 1, defval: '' }), ''),
                hidden: hiddenCode > 0,
                hiddenState: hiddenCode === 2 ? 'veryHidden' : (hiddenCode === 1 ? 'hidden' : 'visible')
            };
        })
    };
}

function normalizeColorValue(value) {
    const text = String(value || '').trim().toUpperCase();
    if (!text) return '';
    if (text.startsWith('#')) return text.slice(1);
    return text.replace(/^0X/, '').replace(/[^0-9A-F]/g, '');
}

