    function isTranslateConsistencyMemoryEnabled() {
        return translateConsistencyMemoryInput
            ? translateConsistencyMemoryInput.checked
            : localStorage.getItem(TRANSLATE_CONSISTENCY_MEMORY_KEY) !== 'false';
    }

