    function getTranslateTargetLanguageKeys(targetLang) {
        const map = {
            en: ['finalTranslation', 'english', 'target', 'translation', 'en'],
            ja: ['japanese', 'ja', 'jp', '日文', '日语'],
            ko: ['korean', 'ko', '韩文', '韩语'],
            'zh-TW': ['traditionalChinese', 'zhTW', 'zh-TW', '繁体', '繁体中文'],
            fr: ['french', 'fr', '法文', '法语'],
            de: ['german', 'de', '德文', '德语'],
            es: ['spanish', 'es', '西班牙文', '西班牙语'],
            pt: ['portuguese', 'pt', '葡萄牙文', '葡萄牙语'],
            ru: ['russian', 'ru', '俄文', '俄语'],
            th: ['thai', 'th', '泰文', '泰语'],
            vi: ['vietnamese', 'vi', '越南文', '越南语'],
            id: ['indonesian', 'id', '印尼文', '印尼语'],
            it: ['italian', 'it', '意大利文', '意大利语'],
            ar: ['arabic', 'ar', '阿拉伯文', '阿拉伯语'],
            tr: ['turkish', 'tr', '土耳其文', '土耳其语'],
            hi: ['hindi', 'hi', '印地文', '印地语', '印度语'],
            fil: ['filipino', 'tagalog', 'tl', 'fil', '菲律宾文', '菲律宾语', '他加禄语'],
            ms: ['malay', 'ms', '马来文', '马来语'],
            nl: ['dutch', 'nl', '荷兰文', '荷兰语'],
            pl: ['polish', 'pl', '波兰文', '波兰语'],
            uk: ['ukrainian', 'uk', '乌克兰文', '乌克兰语'],
            fa: ['persian', 'farsi', 'fa', '波斯文', '波斯语'],
            ur: ['urdu', 'ur', '乌尔都文', '乌尔都语'],
            bn: ['bengali', 'bangla', 'bn', '孟加拉文', '孟加拉语'],
            my: ['burmese', 'myanmar', 'my', '缅甸文', '缅甸语'],
            km: ['khmer', 'km', '高棉文', '高棉语', '柬埔寨语'],
            lo: ['lao', 'lo', '老挝文', '老挝语']
        };
        return map[targetLang] || [];
    }

    function getTermTranslationForLanguage(term, targetLang) {
        const keys = getTranslateTargetLanguageKeys(targetLang);
        for (const key of keys) {
            const value = term?.[key];
            if (value !== undefined && value !== null && String(value).trim()) {
                return {
                    value: String(value).trim(),
                    constraint: 'hard',
                    source: key
                };
            }
        }
        const fallback = getGlossaryEffectiveTarget(term) || term?.english || term?.originalTranslation || '';
        return {
            value: String(fallback || '').trim(),
            constraint: targetLang === 'en' && fallback ? 'hard' : 'reference',
            source: fallback ? 'reference' : ''
        };
    }

    function getTermTargetForLanguage(term, targetLang) {
        return getTermTranslationForLanguage(term, targetLang).value;
    }

    function getRelevantTranslateGlossaryTerms(texts, glossaryTerms, targetLang, limit = 32, options = {}) {
        const textList = Array.isArray(texts)
            ? texts.map(text => String(text || '').trim()).filter(Boolean)
            : [String(texts || '').trim()].filter(Boolean);
        const combined = textList.join('\n');
        const primaryTextKey = normalizeTranslateConsistencyTerm(textList[0] || '');
        const seen = new Set();
        const normalizedTerms = options.normalized && Array.isArray(glossaryTerms)
            ? glossaryTerms
            : normalizeGlossaryTerms(glossaryTerms);
        return normalizedTerms
            .filter(term => term.source && combined.includes(term.source))
            .filter(term => targetLang !== 'zh-TW' || normalizeTranslateConsistencyTerm(term.source) === primaryTextKey)
            .map(term => {
                const translation = getTermTranslationForLanguage(term, targetLang);
                return {
                    source: term.source,
                    target: translation.constraint === 'hard' ? translation.value : '',
                    referenceTarget: translation.constraint === 'reference' ? translation.value : '',
                    constraint: translation.constraint,
                    type: term.type || '',
                    note: term.note || term.qualitySuggestion || term.qualityIssues || '',
                    english: term.english || term.target || term.translation || ''
                };
            })
            .filter(term => {
                if (!term.target && !term.referenceTarget) return false;
                const key = `${term.source}|${term.constraint}|${term.target || term.referenceTarget}`;
                if (seen.has(key)) return false;
                seen.add(key);
                return true;
            })
            .sort((a, b) => b.source.length - a.source.length)
            .slice(0, limit);
    }

    function buildTranslateGlossaryPromptSection(glossaryTerms, targetLang) {
        if (!glossaryTerms.length) return '';
        const langName = getTranslateLanguageName(targetLang);
        const hardTerms = glossaryTerms.filter(term => term.constraint !== 'reference' && term.target);
        const referenceTerms = glossaryTerms.filter(term => term.constraint === 'reference' && term.referenceTarget);
        const hardRows = hardTerms.map(term => {
            const typeText = term.type ? `（${term.type}）` : '';
            const noteText = term.note ? `；${String(term.note).slice(0, 80)}` : '';
            return `- ${term.source} => ${term.target}${typeText}${noteText}`;
        }).join('\n');
        const referenceRows = referenceTerms.map(term => {
            const typeText = term.type ? `（${term.type}）` : '';
            const noteText = term.note ? `；${String(term.note).slice(0, 80)}` : '';
            return `- ${term.source} ≈ ${term.referenceTarget}${typeText}${noteText}`;
        }).join('\n');

        const sections = [];
        if (hardRows) {
            sections.push(`目标语硬性术语（已有${langName}指定译法，必须使用）：\n${hardRows}`);
        }
        if (referenceRows) {
            sections.push(`术语概念参考（不能直接照抄为${langName}最终译文；行内参考优先）：\n${referenceRows}`);
        }
        return sections.length ? `\n${sections.join('\n\n')}\n` : '';
    }

    function buildTraditionalChineseFormatRules(rules) {
        const rawLines = String(rules || '')
            .split(/\r?\n+/)
            .map(line => line.replace(/^\s*[\d一二三四五六七八九十]+[.、)]?\s*/, '').trim())
            .filter(Boolean);
        const formatLines = rawLines.filter(line =>
            /(\^|%s|%d|占位符|代文本|\\n|换行|color|outline|标签|引号|双引|单引|ID|Key|大小写|保留|不可替换|不能替换|格式|符号)/i.test(line)
        );
        return formatLines.length
            ? `\n项目格式规则：${formatLines.join('；').slice(0, 520)}`
            : '';
    }

    function isSoftTranslateLengthConstraintRule(line) {
        const text = String(line || '');
        const hasLengthConstraint = /(字数|字符|长度|超框|限长|小于|不超过|以内|≤|≥|>=|<=)/i.test(text);
        const hasStructuralConstraint = /(\^|%s|%d|占位符|代文本|\\n|color|outline|标签|ID|Key|大小写|必须保留|不可替换|不能替换|格式)/i.test(text);
        return hasLengthConstraint && !hasStructuralConstraint;
    }

    function buildCompactTranslateRules(rules, targetLang = '') {
        const baseRules = targetLang === 'zh-TW'
            ? [
                '保留占位符、数字、\\n、富文本/颜色/outline 标签和格式标记，并按语义放在正确位置。',
                '繁中任务是简体到繁体的完整本地化转换，不是摘要、截断或压缩。',
                '不得输出解释、Markdown 或思考过程；不要保留未转换的简体字。',
                '行内参考译文用于术语和语气；与普通术语参考冲突时行内参考优先。'
            ]
            : [
                '保留占位符、数字、\\n、富文本/颜色/outline 标签和格式标记，并按语义放在正确位置。',
                '按游戏 UI 本地化表达，译文自然简洁，避免超框。',
                '不得输出解释、Markdown 或思考过程；除固定专名外，不保留主源中文片段。',
                '行内参考译文用于术语、语气和长度；与普通术语参考冲突时行内参考优先。'
            ];
        const rawLines = String(rules || '')
            .split(/\r?\n+/)
            .map(line => line.replace(/^\s*[\d一二三四五六七八九十]+[.、)]?\s*/, '').trim())
            .filter(Boolean);
        const scopedLines = targetLang === 'zh-TW'
            ? rawLines.filter(line => !isSoftTranslateLengthConstraintRule(line))
            : rawLines;
        const important = scopedLines.filter(line =>
            /(\^|%s|%d|占位符|代文本|语义|位置|换行|color|outline|标签|引号|双引|单引|报错|ID|Key|大小写|必须|需要|不可|不能|保留|替换|超框|字数|字符|符号)/i.test(line)
        );
        const seen = new Set();
        const custom = (important.length ? important : scopedLines)
            .filter(line => {
                const key = line.replace(/\s+/g, '');
                if (!key || seen.has(key)) return false;
                seen.add(key);
                return true;
            })
            .join('；')
            .slice(0, 420);
        const zhTwLengthOverride = targetLang === 'zh-TW'
            ? ' 繁中目标语言时，字数/字符/超框类规则只作为译后风险提示，不得用来删除补偿、排名、奖励、领取、次数、状态、对象等核心语义。'
            : '';
        return custom ? `${baseRules.join(' ')} 其他项目规则：${custom}${zhTwLengthOverride}` : `${baseRules.join(' ')}${zhTwLengthOverride}`;
    }

    function formatPromptGlossaryTerm(term) {
        const target = term.constraint === 'reference' ? term.referenceTarget : term.target;
        const marker = term.constraint === 'reference' ? '≈' : '=>';
        const typeText = term.type ? `(${term.type})` : '';
        return `${term.source}${marker}${target}${typeText}`;
    }

    function buildPromptGlossaryPayload(glossaryTerms = [], limit = 12) {
        return (glossaryTerms || [])
            .slice(0, limit)
            .map(formatPromptGlossaryTerm)
            .filter(Boolean);
    }

    const TRANSLATE_FORMAT_TOKEN_PATTERN = /%(?:\d+\$)?[-+#0 ]*(?:\d+)?(?:\.\d+)?(?:ll|l|h)?[sdifux@]|\\n|<[^>]+>|\{[^}]+\}|\[[A-Z0-9_]+\]/gi;

    function extractFormatTokens(text) {
        return String(text || '').match(TRANSLATE_FORMAT_TOKEN_PATTERN) || [];
    }

    function createPlaceholderProtectionContext(fields = {}, options = {}) {
        const replacements = [];
        let index = 0;
        const protectedUiTokenPolicy = globalThis.NexusProtectedUiTokenPolicy;
        const sourceFieldKey = Object.prototype.hasOwnProperty.call(fields, 'sourceText')
            ? 'sourceText'
            : (Object.prototype.hasOwnProperty.call(fields, 'text') ? 'text' : '');
        const sourceText = sourceFieldKey ? fields[sourceFieldKey] : '';
        const protectedUiRequirements = protectedUiTokenPolicy?.getRequirements
            ? protectedUiTokenPolicy.getRequirements(sourceText, fields.referenceText || '', {
                projectRules: options.projectRules || currentProject?.rules || ''
            })
            : [];
        const makePlaceholder = token => {
            const placeholder = `__PH_${++index}__`;
            replacements.push({ placeholder, token });
            return placeholder;
        };
        const protect = (value, key) => {
            let protectedValue = String(value || '').replace(
                TRANSLATE_FORMAT_TOKEN_PATTERN,
                token => makePlaceholder(token)
            );
            if (
                key === sourceFieldKey &&
                protectedUiRequirements.length &&
                protectedUiTokenPolicy?.replaceProtectedTokens
            ) {
                protectedValue = protectedUiTokenPolicy.replaceProtectedTokens(
                    protectedValue,
                    protectedUiRequirements,
                    token => makePlaceholder(token)
                );
            }
            return protectedValue;
        };
        const protectedFields = {};
        Object.entries(fields).forEach(([key, value]) => {
            protectedFields[key] = protect(value, key);
        });
        return { fields: protectedFields, replacements, protectedUiRequirements };
    }

    function restoreProtectedPlaceholders(text, replacements = []) {
        let next = String(text || '');
        replacements.forEach(({ placeholder, token }) => {
            next = next.replace(new RegExp(placeholder.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'g'), token);
        });
        return next;
    }

    function countTokens(tokens) {
        return tokens.reduce((map, token) => {
            map.set(token, (map.get(token) || 0) + 1);
            return map;
        }, new Map());
    }

    function getFormatTokenIssues(sourceText, translatedText) {
        const sourceTokens = extractFormatTokens(sourceText);
        const targetTokens = extractFormatTokens(translatedText);
        const issues = [];
        if (!sourceTokens.length && !targetTokens.length) return issues;

        const sourceCounts = countTokens(sourceTokens);
        const targetCounts = countTokens(targetTokens);
        const missingTokens = [];
        const extraTokens = [];
        sourceCounts.forEach((count, token) => {
            const targetCount = targetCounts.get(token) || 0;
            for (let i = targetCount; i < count; i++) missingTokens.push(token);
        });
        targetCounts.forEach((count, token) => {
            const sourceCount = sourceCounts.get(token) || 0;
            for (let i = sourceCount; i < count; i++) extraTokens.push(token);
        });

        if (missingTokens.length) issues.push(`缺少格式/占位符：${[...new Set(missingTokens)].join(', ')}`);
        if (extraTokens.length) issues.push(`多出格式/占位符：${[...new Set(extraTokens)].join(', ')}`);
        if (!missingTokens.length && !extraTokens.length && sourceTokens.length > 1 && sourceTokens.join('\u001f') !== targetTokens.join('\u001f')) {
            issues.push(`格式/占位符顺序不一致：应保持 ${sourceTokens.join(' → ')}`);
        }
        return issues;
    }

    function extractNumberTokens(text) {
        return String(text || '').match(/\d+(?:[.,]\d+)?%?/g) || [];
    }

    function getVisibleTextForLength(text) {
        return String(text || '')
            .replace(TRANSLATE_FORMAT_TOKEN_PATTERN, '')
            .replace(/\s+/g, ' ')
            .trim();
    }

    function getTranslationLengthMultiplier(targetLang) {
        const multipliers = {
            en: 1,
            ja: 1.05,
            ko: 1.12,
            'zh-TW': 1,
            fr: 1.28,
            de: 1.35,
            es: 1.25,
            pt: 1.25,
            ru: 1.45,
            th: 1.12,
            vi: 1.18,
            id: 1.2,
            it: 1.22,
            ar: 1.28,
            tr: 1.3,
            hi: 1.2,
            fil: 1.2,
            ms: 1.2,
            nl: 1.22,
            pl: 1.32,
            uk: 1.38,
            fa: 1.24,
            ur: 1.24,
            bn: 1.2,
            my: 1.16,
            km: 1.16,
            lo: 1.16
        };
        return multipliers[targetLang] || 1.25;
    }

    function getTranslationLengthBase(sourceText, context = {}) {
        const sourceVisible = getVisibleTextForLength(sourceText);
        const referenceVisible = getVisibleTextForLength(context.referenceText || '');
        const sourceLength = sourceVisible.length;
        const referenceLength = referenceVisible.length;
        const sourceLooksCjk = /[\u3400-\u9fff]/.test(sourceVisible);
        const sourceBase = sourceLooksCjk ? sourceLength * 3 : sourceLength;
        return referenceLength > 0 ? Math.max(referenceLength, sourceBase) : sourceBase;
    }

    function getTranslationPreferredLengthMultiplier(targetLang) {
        const multipliers = {
            en: 0.95,
            ja: 1,
            ko: 1.05,
            'zh-TW': 1,
            fr: 1.12,
            de: 1.18,
            es: 1.12,
            pt: 1.12,
            ru: 1.15,
            th: 1.08,
            vi: 1.12,
            id: 1.12,
            it: 1.08,
            ar: 1.12,
            tr: 1.12,
            hi: 1.1,
            fil: 1.1,
            ms: 1.1,
            nl: 1.08,
            pl: 1.12,
            uk: 1.14,
            fa: 1.1,
            ur: 1.1,
            bn: 1.1,
            my: 1.08,
            km: 1.08,
            lo: 1.08
        };
        return multipliers[targetLang] || 1.12;
    }

    function getTranslationPreferredLengthBudget(sourceText, targetLang, context = {}) {
        const base = getTranslationLengthBase(sourceText, context);
        const budget = Math.ceil(base * getTranslationPreferredLengthMultiplier(targetLang));
        return Math.max(8, budget);
    }

    function getTranslationLengthBudget(sourceText, targetLang, context = {}) {
        const base = getTranslationLengthBase(sourceText, context);
        const budget = Math.ceil(base * getTranslationLengthMultiplier(targetLang));
        return Math.max(targetLang === 'en' ? 1 : 8, budget);
    }

    function getTranslateCompactStyleInstruction(targetLang) {
        const languageName = getTranslateLanguageName(targetLang);
        if (targetLang === 'zh-TW') {
            return '\n繁中转换策略：这是简体中文到繁体中文的本地化转换，不是摘要或改写。必须保留每个语义成分，尤其是状态词、否定词、数量词、对象名和功能名；只做必要的繁体用字与台湾/繁中常见表达调整。不要为了精简删除“人数、次数、已满、不足、列表、奖励、领取、关卡、补偿、排名”等核心信息。例如：“上阵人数已满”应为“上陣人數已滿”，不能简化成“上陣”；“挑战次数不足”应为“挑戰次數不足”，不能简化成“挑戰次數”；“昵称重置补偿”应为“暱稱重置補償”，不能简化成“暱稱重”；“昨日您在竞技场的排名为%s，获得以下奖励”应完整保留排名和奖励信息。';
        }
        const common = `\n第一遍表达策略：完整准确优先，在不丢失语义的前提下尽量简洁。优先使用短 UI 标签、名词短语和自然省略；只删除“已经、当前、进行、你的、该”等确实不影响含义的冗余表达；不要添加原文没有的信息。`;
        const languageSpecific = {
            ru: '俄语简洁策略：俄语天然更长，第一遍仍以完整含义为先。优先短 UI 用语和常见游戏表达；能用短角色/功能称呼时不要写成长书面语。若中文“管理员”或英文参考 Admin 出现在 UI 标签中，优先译为“Админ”，不要默认使用更长的“Администратор”，除非项目术语表明确要求。例如“系统管理员”优先“Админ системы”，“联盟管理员”优先“Админ альянса”，“服务器管理员”优先“Админ сервера”。不要为了长度牺牲核心含义。',
            de: '德语简洁策略：优先短复合词或常见 UI 短语，避免冗长从句和不必要冠词；完整含义优先。',
            fr: '法语简洁策略：优先短按钮/菜单表达，避免完整句式和多余冠词；完整含义优先。',
            es: '西语简洁策略：优先短按钮/菜单表达，避免完整句式和多余说明；完整含义优先。',
            pt: '葡语简洁策略：优先短按钮/菜单表达，避免完整句式和多余说明；完整含义优先。',
            it: '意大利语简洁策略：优先自然短 UI 表达，避免冗长从句和重复冠词；完整含义优先。',
            ar: '阿拉伯语简洁策略：使用自然现代标准阿拉伯语游戏 UI 表达；保持从右到左语言习惯，不要夹杂中文或未翻译英文，固定品牌/代码除外。',
            tr: '土耳其语简洁策略：土耳其语后缀较长，优先短名词短语和常见游戏表达，避免冗长解释；完整含义优先。',
            hi: '印地语简洁策略：使用自然游戏 UI 表达，保留必要英语品牌/代码，其他内容应完整译为印地语。',
            fil: '菲律宾语简洁策略：使用自然菲律宾语/Tagalog 游戏 UI 表达，避免机械直译；固定品牌/代码可保留。',
            ms: '马来语简洁策略：使用自然马来语游戏 UI 表达，优先短按钮/菜单用语；完整含义优先。'
        };
        return `${common}${languageSpecific[targetLang] ? `\n${languageSpecific[targetLang]}` : `\n${languageName}翻译应完整保留含义，并在自然前提下尽量简洁。`}`;
    }

    function getTranslationLengthIssue(sourceText, translatedText, targetLang, context = {}) {
        if (targetLang === 'zh-TW') return '';
        const targetLength = getVisibleTextForLength(translatedText).length;
        if (!targetLength) return '';
        const budget = getTranslationLengthBudget(sourceText, targetLang, context);
        if (targetLength <= budget) return '';
        return `译文长度超出建议：${targetLength}/${budget} 字符，需压缩以降低 UI 超框风险`;
    }

    function getAbnormalSpacingIssues(translatedText, targetLang) {
        const target = getVisibleTextForLength(translatedText);
        if (targetLang === 'ru' && /(?:[А-Яа-яЁё]\s+){4,}[А-Яа-яЁё]/.test(target)) {
            return ['目标俄语疑似被拆成逐字空格，需要恢复正常单词拼写'];
        }
        if (['en', 'fr', 'de', 'es', 'pt', 'vi', 'id', 'it', 'tr', 'fil', 'ms', 'nl', 'pl'].includes(targetLang) && /(?:[A-Za-z]\s+){6,}[A-Za-z]/.test(target)) {
            return ['目标译文疑似被拆成逐字空格，需要恢复正常单词拼写'];
        }
        return [];
    }

    const SIMPLIFIED_ONLY_CJK_PATTERN = /[个们为会国与龙发战级获宝进还这过后术买卖开关击伤敌属蓝红绿黄门队阳阴阵阶际陆难飞马鱼鸟风电画体质贝货责败账贵费赏赠赚赛赢边达远连选递释铁钢银铜钥钱钻铠锐锁锅锻镜长问间闯闹闻阅阔队阳险隐顶顺须顾领颁频题额颜风飞饭饮馆马骑骄骆验鲜鲨鸟鸡鸣齐齿龄]/;
    const ZH_TW_CRITICAL_SEMANTIC_TERMS = [
        { source: /上阵/, target: /上陣/, label: '上阵' },
        { source: /人数/, target: /人數/, label: '人数' },
        { source: /次数/, target: /次數/, label: '次数' },
        { source: /挑战/, target: /挑戰/, label: '挑战' },
        { source: /关卡/, target: /關卡/, label: '关卡' },
        { source: /列表/, target: /列表/, label: '列表' },
        { source: /已满|满了|满员/, target: /已滿|滿了|滿員/, label: '已满' },
        { source: /不足|不够/, target: /不足|不夠/, label: '不足' },
        { source: /奖励/, target: /獎勵/, label: '奖励' },
        { source: /领取/, target: /領取/, label: '领取' },
        { source: /任务/, target: /任務/, label: '任务' },
        { source: /活动/, target: /活動/, label: '活动' },
        { source: /等级/, target: /等級/, label: '等级' },
        { source: /失败/, target: /失敗/, label: '失败' },
        { source: /成功/, target: /成功/, label: '成功' },
        { source: /无法|不能|不可/, target: /無法|不能|不可/, label: '无法/不能' },
        { source: /没有|无|未/, target: /沒有|無|未/, label: '没有/未' }
    ];

    function isTranslateCompletenessCheckEnabled() {
        return translateCompletenessCheckInput ? translateCompletenessCheckInput.checked : true;
    }

    function getCompactVisibleLength(text) {
        return getVisibleTextForLength(text).replace(/\s+/g, '').length;
    }

    function splitMeaningSegments(text) {
        return getVisibleTextForLength(text)
            .split(/[，,。.!！?？;；:：、\r\n]+/)
            .map(segment => segment.trim())
            .filter(segment => /[\p{L}\p{N}\u3400-\u9fff]/u.test(segment) && getCompactVisibleLength(segment) >= 2);
    }

    function getStructuralMarkerCount(text) {
        const value = String(text || '');
        const matches = value.match(/[()（）\[\]【】《》「」『』«»‹›"“”'‘’]/g);
        return matches ? matches.length : 0;
    }

    function getLengthLossThreshold(targetLang) {
        if (targetLang === 'zh-TW') return 0.88;
        if (['ja', 'ko'].includes(targetLang)) return 0.72;
        if (targetLang === 'ru') return 0.82;
        return 0.68;
    }

    function getTraditionalChineseSemanticLossIssues(sourceText, translatedText) {
        const source = getVisibleTextForLength(sourceText);
        const target = getVisibleTextForLength(translatedText);
        if (!/[\u3400-\u9fff]/.test(source)) return [];
        const issues = [];
        ZH_TW_CRITICAL_SEMANTIC_TERMS.forEach(term => {
            if (term.source.test(source) && !term.target.test(target)) {
                issues.push(`繁中关键语义缺失：${term.label}`);
            }
        });
        return issues;
    }

    function getTranslationCompletenessIssues(sourceText, translatedText, targetLang, context = {}) {
        const sourceVisible = getVisibleTextForLength(sourceText);
        const targetVisible = getVisibleTextForLength(translatedText);
        const sourceLength = getCompactVisibleLength(sourceVisible);
        const targetLength = getCompactVisibleLength(targetVisible);
        const issues = [];

        if (!sourceLength) return issues;
        if (!targetLength) return ['译文为空，疑似未返回结果'];

        const sourceHasCjk = /[\u3400-\u9fff]/.test(sourceVisible);
        const sourceSegments = splitMeaningSegments(sourceVisible);
        const targetSegments = splitMeaningSegments(targetVisible);
        const minLength = Math.ceil(sourceLength * getLengthLossThreshold(targetLang));
        const shouldCheckShortness = sourceHasCjk && (
            (targetLang === 'zh-TW' && sourceLength >= 4) ||
            sourceLength >= 14 ||
            sourceSegments.length >= 2 ||
            /[，,。.!！?？;；:：、]/.test(sourceVisible)
        );

        if (shouldCheckShortness && targetLength < minLength) {
            issues.push(`疑似译文过短：${targetLength}/${minLength} 字符，可能存在内容流失`);
        }

        if (sourceSegments.length >= 2 && targetSegments.length <= 1 && targetLength < Math.ceil(sourceLength * 1.05)) {
            issues.push(`疑似内容流失：原文 ${sourceSegments.length} 个分句，译文疑似只覆盖部分内容`);
        }

        const sourceMarkers = getStructuralMarkerCount(sourceText);
        const targetMarkers = getStructuralMarkerCount(translatedText);
        if (sourceMarkers >= 2 && targetMarkers === 0 && sourceLength >= 8) {
            issues.push('疑似内容流失：原文含括号/引号结构，译文未保留对应信息');
        }

        if (targetLang === 'zh-TW') {
            issues.push(...getTraditionalChineseSemanticLossIssues(sourceText, translatedText));
            const simplifiedMatches = targetVisible.match(SIMPLIFIED_ONLY_CJK_PATTERN);
            if (simplifiedMatches?.length) {
                issues.push(`繁简转换不完整：译文仍含疑似简体字「${[...new Set(simplifiedMatches)].slice(0, 6).join('、')}」`);
            }
        }

        const referenceLength = getCompactVisibleLength(context.referenceText || '');
        if (referenceLength >= 16 && targetLength < Math.ceil(referenceLength * 0.45)) {
            issues.push('疑似内容流失：译文明显短于参考译文');
        }

        return [...new Set(issues)];
    }

    function targetLanguageUsesLatinScript(targetLang) {
        return ['en', 'fr', 'de', 'es', 'pt', 'vi', 'id', 'it', 'tr', 'fil', 'ms', 'nl', 'pl'].includes(targetLang);
    }

    const SAFE_LATIN_TOKENS_IN_RUSSIAN = new Set([
        'id', 'uid', 'slg_id', 'api', 'sdk', 'ui', 'url', 'http', 'https', 'ip', 'pc',
        'ios', 'android', 'google', 'facebook', 'huawei', 'apple', 'app', 'store',
        'game', 'center', 'vip', 'gm', 'cdk', 'qr'
    ]);

    function extractLatinTokensForQa(text) {
        return String(text || '')
            .replace(TRANSLATE_FORMAT_TOKEN_PATTERN, ' ')
            .match(/[A-Za-z][A-Za-z0-9_.+-]*/g) || [];
    }

    function normalizeLatinTokenForQa(token) {
        return String(token || '').toLowerCase().replace(/^[._+-]+|[._+-]+$/g, '');
    }

    function isAllowedRussianLatinToken(token, sourceTokens) {
        const normalized = normalizeLatinTokenForQa(token);
        if (!normalized) return true;
        if (sourceTokens.has(normalized)) return true;
        if (SAFE_LATIN_TOKENS_IN_RUSSIAN.has(normalized)) return true;
        if (/^[A-Z0-9_+-]{2,}$/.test(token)) return true;
        return false;
    }

    function getTargetLanguageLeakageIssues(sourceText, translatedText, targetLang, context = {}) {
        const target = String(translatedText || '');
        const issues = [];
        const hardAllowedTerms = (context.glossaryTerms || [])
            .filter(term => term?.constraint !== 'reference' && term?.target)
            .map(term => term.target);
        const carryoverGuard = globalThis.NexusLanguageCarryoverGuard;
        const guardOptions = {
            referenceText: context.referenceText || '',
            allowedTerms: hardAllowedTerms,
            allowlist: context.englishAllowlist || [],
            projectRules: context.projectRules || currentProject?.rules || ''
        };
        const scriptLeakageResult = carryoverGuard?.evaluateScriptLeakage
            ? carryoverGuard.evaluateScriptLeakage(sourceText, target, targetLang, guardOptions)
            : null;
        if (scriptLeakageResult?.issues?.length) {
            issues.push(...scriptLeakageResult.issues.map(issue => issue.message || issue).filter(Boolean));
        }
        const carryoverResult = carryoverGuard?.evaluateCarryover
            ? carryoverGuard.evaluateCarryover(sourceText, target, targetLang, guardOptions)
            : null;
        if (carryoverResult?.issues?.length) {
            issues.push(...carryoverResult.issues.map(issue => issue.message || issue).filter(Boolean));
        }

        if (targetLang === 'ru' && !carryoverResult?.issues?.length) {
            const sourceTokens = new Set(extractLatinTokensForQa(sourceText).map(normalizeLatinTokenForQa));
            const leakedTokens = extractLatinTokensForQa(target)
                .filter(token => !isAllowedRussianLatinToken(token, sourceTokens));
            if (leakedTokens.length) {
                issues.push(`英文专名需确认：${[...new Set(leakedTokens)].slice(0, 6).join(', ')}`);
            }
        }

        return [...new Set(issues)];
    }

    function isTranslationQaPassed(qaStatus) {
        return !qaStatus || qaStatus === '通过';
    }

    function shouldAutoRepairTranslationQa(qaStatus, targetLang = '') {
        if (isTranslationQaPassed(qaStatus)) return false;
        const text = String(qaStatus || '');
        const hardIssuePatterns = [
            /缺少格式\/占位符/,
            /多出格式\/占位符/,
            /格式\/占位符顺序不一致/,
            /受保护UI标记缺失或被翻译/,
            /数字不一致/,
            /折扣语义不一致/,
            /折扣翻译缺失/,
            /术语未遵守/,
            /玩法名疑似沿用英文/,
            /目标译文疑似照抄英文参考/,
            /目标译文仍含英文/,
            /疑似照抄英文参考术语/,
            /混入中文/,
            /混入英文/,
            /混入日文/,
            /目标.+中混入/,
            /疑似未翻译/,
            /繁简转换不完整/,
            /繁中关键语义缺失/,
            /逐字空格/
        ];
        if (targetLang === 'zh-TW' && /疑似内容流失|疑似译文过短/.test(text)) return true;
        if (hardIssuePatterns.some(pattern => pattern.test(text))) return true;
        return targetLang !== 'zh-TW' &&
            isTranslateAutoCompactLongEnabled() &&
            /译文长度超出建议/.test(text);
    }

    function getTranslationReportStatus(translatedText, qaStatus) {
        if (isMissingTranslationResult(translatedText)) return 'missing';
        if (isTranslateFailureText(translatedText)) return 'failed';
        if (!isTranslationQaPassed(qaStatus)) return 'qa_failed';
        return 'success';
    }

    function isFailedTranslationReportEntry(entry) {
        if (!entry) return false;
        if (entry.manualResolutionValid === true) return false;
        const status = String(entry.status || '').trim().toLowerCase();
        if (status && status !== 'success') return true;
        if (isTranslateFailureText(entry.translatedText)) return true;
        return !isTranslationQaPassed(entry.qaStatus);
    }

    function getTranslationReportIssueText(entry) {
        return [
            entry?.status,
            entry?.qaStatus,
            entry?.completenessRisk,
            entry?.actionSuggestion,
            entry?.error,
            entry?.translatedText
        ].filter(Boolean).join(' ');
    }

    function isMissingTranslationReportEntry(entry) {
        if (!entry) return false;
        const status = String(entry.status || '').trim().toLowerCase();
        const issueText = getTranslationReportIssueText(entry);
        if (status === 'missing') return true;
        if (/报告缺失|未返回结果|没有出现在导入报告|missing/i.test(issueText)) return true;
        return isMissingTranslationResult(entry.translatedText) && Boolean(entry.sourceText || entry.taskKey || entry.rowNumber);
    }

    function isLengthSoftRiskTranslationReportEntry(entry) {
        return /译文长度超出建议/.test(getTranslationReportIssueText(entry));
    }

    function isHardTranslationReportEntry(entry) {
        if (!entry || isMissingTranslationReportEntry(entry)) return false;
        const status = String(entry.status || '').trim().toLowerCase();
        const issueText = getTranslationReportIssueText(entry);
        if (status === 'failed' || status === 'error') return true;
        if (isTranslateFailureText(entry.translatedText)) return true;
        if (/模型翻译失败|输出被截断|返回空译文|请求超时|限流|网络异常|通道异常|格式\/占位符|缺少格式|多出格式|数字不一致|折扣语义不一致|折扣翻译缺失|术语未遵守|玩法名疑似沿用英文|目标译文疑似照抄英文参考|目标译文仍含英文|疑似照抄英文参考术语|混入中文|混入英文|混入日文|目标.+中混入|疑似未翻译|繁简转换不完整|繁中关键语义缺失|逐字空格|用户要求重新翻译|修订译文为空|硬错误不能直接接受/.test(issueText)) {
            return true;
        }
        const targetLang = translationRunReport?.targetLang || targetLangSelect?.value || '';
        return shouldAutoRepairTranslationQa(entry.qaStatus, targetLang) && !isLengthSoftRiskTranslationReportEntry(entry);
    }

    function classifyTranslationReportEntry(entry) {
        if (!isFailedTranslationReportEntry(entry)) return 'success';
        if (isMissingTranslationReportEntry(entry)) return 'missing';
        if (isHardTranslationReportEntry(entry)) return 'hard';
        if (isLengthSoftRiskTranslationReportEntry(entry)) return 'length';
        return 'soft';
    }

    function isActualTranslationFailureReportEntry(entry) {
        if (!entry) return false;
        const status = String(entry.status || '').trim().toLowerCase();
        return status === 'failed' ||
            status === 'error' ||
            isMarkedTranslationFailure(entry.translatedText);
    }

    function getTranslationReportDisplayStatus(entry) {
        if (entry?.manualResolutionValid && entry?.revisionApplied) {
            return '人工修订 · 质检通过';
        }
        if (entry?.manualResolutionValid && entry?.userDecision === 'accept_current') {
            return '人工已确认 · 接受现译';
        }
        const kind = classifyTranslationReportEntry(entry);
        if (kind === 'missing') return '未返回译文';
        if (kind === 'hard') {
            return isActualTranslationFailureReportEntry(entry)
                ? '翻译失败'
                : '已翻译 · 硬质检未通过';
        }
        if (kind === 'length') return '已翻译 · 长度需确认';
        if (kind === 'soft') return '已翻译 · 需人工确认';
        return '已翻译 · 质检通过';
    }

    function getTranslationQaDisplayText(entry) {
        const qaStatus = String(entry?.qaStatus || '');
        if (!qaStatus) return '';
        if (isMissingTranslationReportEntry(entry)) {
            return qaStatus.replace(/^需确认[:：]\s*/, '阻断：');
        }
        if (isHardTranslationReportEntry(entry)) {
            return qaStatus.replace(/^需确认[:：]\s*/, '阻断：');
        }
        return qaStatus;
    }

    function getTranslationReportIssueGroups(entries = translationRunReport?.entries || []) {
        const groups = {
            missing: [],
            hard: [],
            length: [],
            soft: []
        };
        (entries || []).forEach(entry => {
            const kind = classifyTranslationReportEntry(entry);
            if (kind === 'missing') groups.missing.push(entry);
            else if (kind === 'hard') groups.hard.push(entry);
            else if (kind === 'length') groups.length.push(entry);
            else if (kind === 'soft') groups.soft.push(entry);
        });
        return groups;
    }

    function getTranslationReportIssueSummary(entries = translationRunReport?.entries || []) {
        const groups = getTranslationReportIssueGroups(entries);
        const softRisk = groups.length.length + groups.soft.length;
        const actualFailed = groups.hard.filter(isActualTranslationFailureReportEntry).length;
        const hardQa = Math.max(0, groups.hard.length - actualFailed);
        const failedOrMissing = actualFailed + groups.missing.length;
        const autoRepairable = failedOrMissing + hardQa;
        const totalIssues = autoRepairable + softRisk;
        const success = Math.max(0, (entries || []).length - totalIssues);
        return {
            success,
            hard: groups.hard.length,
            missing: groups.missing.length,
            length: groups.length.length,
            soft: groups.soft.length,
            softRisk,
            actualFailed,
            failedOrMissing,
            hardQa,
            autoRepairable,
            totalIssues,
            retryable: autoRepairable,
            totalFailed: totalIssues
        };
    }

    function getTranslationDeliveryGate(entries = translationRunReport?.entries || []) {
        const policy = globalThis.NexusTranslationDeliveryPolicy;
        if (policy?.buildDeliveryGate) {
            return policy.buildDeliveryGate(entries, classifyTranslationReportEntry);
        }
        const blockingEntries = (entries || []).filter(entry => {
            const kind = classifyTranslationReportEntry(entry);
            return kind === 'missing' || kind === 'hard';
        });
        return {
            ready: blockingEntries.length === 0,
            blockingCount: blockingEntries.length,
            blockingEntries
        };
    }

    function formatTranslationReportIssueSummary(summary) {
        if (!summary) return '';
        const parts = [
            `翻译失败/未返回 ${summary.failedOrMissing || 0}`,
            `硬质检未通过 ${summary.hardQa || 0}`,
            `软性需确认 ${summary.softRisk || 0}`
        ];
        if (summary.length) parts.push(`超长 ${summary.length}`);
        return parts.join(' / ');
    }

    function getTranslationIssueIdentity(item = {}) {
        const taskKey = item.retryOfTaskKey || item.taskKey;
        if (taskKey) return `task:${taskKey}`;
        const sourceFile = item.sourceFile || item.source?.fileName || '';
        const sheetName = item.sheetName || item.source?.sheetName || '';
        const rowNumber = item.rowNumber || item.originalRowNumber || (Number.isInteger(item.rowIndex) ? item.rowIndex + 1 : '');
        const column = item.column || (Number.isInteger(item.colIndex) ? item.colIndex + 1 : '');
        const model = item.model || item.profile?.model || item.profile?.name || '';
        const sourceText = item.sourceText || item.text || '';
        return `fallback:${[sourceFile, sheetName, rowNumber, column, model, sourceText]
            .map(value => String(value ?? '').trim())
            .join('\u001f')}`;
    }

    function getUniqueRepairableTranslationIssueCount(
        entries = translationRunReport?.entries || [],
        tasks = failedTranslationTasks
    ) {
        const identities = new Set();
        getDefaultRetryableTranslationReportEntries(entries).forEach(entry => {
            identities.add(getTranslationIssueIdentity(entry));
        });
        (tasks || []).forEach(task => {
            identities.add(getTranslationIssueIdentity(task));
        });
        return identities.size;
    }

    function getDefaultRetryableTranslationReportEntries(entries = translationRunReport?.entries || []) {
        const groups = getTranslationReportIssueGroups(entries);
        return [...groups.missing, ...groups.hard];
    }

    function isRepairableTranslationReportEntry(entry) {
        const kind = classifyTranslationReportEntry(entry);
        return kind === 'missing' || kind === 'hard';
    }

    function getTranslationReportFailureEntries(options = {}) {
        const entries = (translationRunReport?.entries || []).filter(isFailedTranslationReportEntry);
        return options.repairableOnly ? entries.filter(isRepairableTranslationReportEntry) : entries;
    }

    function applyLocalTranslationFixes(sourceText, translatedText, targetLang = '') {
        let next = String(translatedText || '');
        const source = String(sourceText || '');
        if (source.includes('\\n') && /\r?\n/.test(next)) {
            next = next.replace(/\r\n|\r|\n/g, '\\n');
        }
        if (source.includes('管理员')) {
            next = next
                .replace(/^Администратор$/u, 'Админ')
                .replace(/^Администратор(\s+(?:системы|гильдии|альянса|сервера))$/iu, 'Админ$1');
        }
        if (targetLang === 'ru') {
            next = next
                .replace(/\bpromptly\b/gi, 'вовремя')
                .replace(/\bin time\b/gi, 'вовремя');
        }
        return next;
    }

    function summarizeTranslationQa(sourceText, translatedText, glossaryTerms, targetLang, context = {}) {
        const issues = [];
        const target = String(translatedText || '');
        issues.push(...getFormatTokenIssues(sourceText, target));

        const discountQa = evaluateNexusDiscountTranslation(sourceText, target, targetLang);
        if (!discountQa.sourceAmbiguous) {
            issues.push(...(discountQa.issues || []).map(issue => issue.message || issue).filter(Boolean));
        }
        const sourceForNumberQa = maskNexusDiscountRanges(sourceText, discountQa.sourceRanges);
        const targetForNumberQa = maskNexusDiscountRanges(target, discountQa.targetRanges);
        const sourceNumbers = extractNumberTokens(sourceForNumberQa);
        const targetNumbers = new Set(extractNumberTokens(targetForNumberQa));
        const missingNumbers = sourceNumbers.filter(number => !targetNumbers.has(number));
        if (missingNumbers.length) issues.push(`数字不一致：${[...new Set(missingNumbers)].join(', ')}`);

        glossaryTerms.filter(term => term.constraint !== 'reference').forEach(term => {
            if (sourceText.includes(term.source) && term.target && !target.includes(term.target)) {
                issues.push(`术语未遵守：${term.source} 应译为 ${term.target}`);
            }
        });

        if (!targetLanguageUsesLatinScript(targetLang)) {
            glossaryTerms.filter(term => term.constraint === 'reference' && term.referenceTarget).forEach(term => {
                const reference = String(term.referenceTarget || '').trim();
                if (reference && /[a-zA-Z]/.test(reference) && target.includes(reference)) {
                    issues.push(`疑似照抄英文参考术语：${term.source} 参考 ${reference}，需确认是否应翻成${getTranslateLanguageName(targetLang)}`);
                }
            });
        }

        issues.push(...getTargetLanguageLeakageIssues(sourceText, target, targetLang, {
            ...context,
            glossaryTerms
        }));
        issues.push(...getAbnormalSpacingIssues(target, targetLang));
        if (isTranslateCompletenessCheckEnabled()) {
            issues.push(...getTranslationCompletenessIssues(sourceText, target, targetLang, context));
        }
        const lengthIssue = getTranslationLengthIssue(sourceText, target, targetLang, context);
        if (lengthIssue) issues.push(lengthIssue);

        if (isTranslateFailureText(target)) issues.push('模型翻译失败');
        const uniqueIssues = [...new Set(issues)].filter(Boolean);
        return uniqueIssues.length ? `需确认：${uniqueIssues.join('；')}` : '通过';
    }

    function updateTranslationRunActions() {
        const hasReport = Boolean(translationRunReport);
        const issueSummary = getTranslationReportIssueSummary();
        const reportFailureCount = issueSummary.totalFailed;
        const retryableCount = getUniqueRepairableTranslationIssueCount();
        const hasFailures = retryableCount > 0;
        const deliveryGate = getTranslationDeliveryGate();
        const manualExportKinds = globalThis.NexusTranslationDeliveryPolicy?.getManualExportKinds
            ? globalThis.NexusTranslationDeliveryPolicy.getManualExportKinds(deliveryGate)
            : (deliveryGate.ready ? ['translated', 'report'] : ['translated_unverified', 'report']);
        if (translateDownloadTitle) {
            translateDownloadTitle.textContent = deliveryGate.ready
                ? '交付版已就绪'
                : '需要修复后交付';
        }
        renderTranslationResultBreakdown();
        if (downloadBtn) {
            downloadBtn.style.display = deliveryGate.ready && hasReport ? 'inline-flex' : 'none';
            downloadBtn.disabled = Boolean(activeTranslateRunId);
            downloadBtn.classList.add('primary');
            downloadBtn.classList.remove('secondary');
            downloadBtn.title = '硬错误已清零，可以保存交付版译文。';
            if (translateDownloadBtnLabel) {
                translateDownloadBtnLabel.textContent = '下载交付版';
            }
        }
        if (translateDownloadUnverifiedBtn) {
            const canExportUnverified = hasReport && manualExportKinds.includes('translated_unverified');
            translateDownloadUnverifiedBtn.style.display = canExportUnverified ? 'inline-flex' : 'none';
            translateDownloadUnverifiedBtn.disabled = Boolean(activeTranslateRunId);
            translateDownloadUnverifiedBtn.textContent = canExportUnverified
                ? `导出当前译文（未验证 · ${deliveryGate.blockingCount}）`
                : '导出当前译文（未验证）';
            translateDownloadUnverifiedBtn.title = canExportUnverified
                ? `当前仍有 ${deliveryGate.blockingCount} 条阻断问题。导出的文件会命名为 *_translated_unverified.xlsx，不能作为交付版。`
                : '';
        }
        if (!hasReport || deliveryGate.ready) {
            hideUnverifiedTranslationExportConfirmation();
        } else if (translateUnverifiedExportMessage) {
            translateUnverifiedExportMessage.textContent =
                `当前仍有 ${deliveryGate.blockingCount} 条阻断问题。导出文件会命名为 *_translated_unverified.xlsx，第一页会标注“未验证译文，请勿直接交付”。`;
        }
        if (downloadReportBtn) downloadReportBtn.style.display = hasReport ? 'inline-flex' : 'none';
        if (downloadFinalReportBtn) {
            downloadFinalReportBtn.style.display = hasReport ? 'inline-flex' : 'none';
            downloadFinalReportBtn.textContent = deliveryGate.ready ? '下载翻译报告' : '下载问题报告';
        }
        if (translateRetryImportShortcutBtn) {
            translateRetryImportShortcutBtn.style.display = hasReport || downloadSection.style.display !== 'none'
                ? 'inline-flex'
                : 'none';
            translateRetryImportShortcutBtn.title = '导入 translation_report.xlsx 或带翻译报告分页的 translated.xlsx；通过项继续复用，仅重新处理翻译失败、缺失和硬质检问题。';
        }
        if (retryFailedBtn) {
            retryFailedBtn.style.display = hasFailures ? 'inline-flex' : 'none';
            retryFailedBtn.disabled = Boolean(activeTranslateRunId);
            retryFailedBtn.classList.toggle('primary', hasFailures);
            retryFailedBtn.classList.toggle('secondary', !hasFailures);
            retryFailedBtn.textContent = retryableCount > 0
                ? `一键修复并生成交付版（${retryableCount}）`
                : '一键修复并生成交付版';
            retryFailedBtn.title = reportFailureCount > retryableCount
                ? `报告内共有 ${formatTranslationReportIssueSummary(issueSummary)}；只自动修复明确问题，软性需确认会保留当前译文。硬错误清零后才生成交付版。`
                : '自动修复翻译失败、结果缺失和硬质检问题；只有复检通过后才生成交付版。';
        }
        if (translateCompactLongImportedBtn && !importedTranslateProgressState?.entries?.length) {
            const lengthCount = Number(issueSummary.length || 0);
            translateCompactLongImportedBtn.style.display = lengthCount > 0 ? 'inline-flex' : 'none';
            translateCompactLongImportedBtn.disabled = Boolean(activeTranslateRunId) || translationRunReport?.targetLang === 'zh-TW';
            translateCompactLongImportedBtn.textContent = lengthCount > 0 ? `精简超长译文（${lengthCount}）` : '精简超长译文';
        }
    }

    function setInspectorField(id, value) {
        const el = document.getElementById(id);
        if (el) el.textContent = value;
    }

    function formatTranslateDuration(ms) {
        const totalSeconds = Math.max(0, Math.floor(Number(ms || 0) / 1000));
        const hours = Math.floor(totalSeconds / 3600);
        const minutes = Math.floor((totalSeconds % 3600) / 60);
        const seconds = totalSeconds % 60;
        if (hours > 0) {
            return `${hours}:${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
        }
        return `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
    }

    function getTranslateElapsedText() {
        return translateRunStartedAt ? formatTranslateDuration(Date.now() - translateRunStartedAt) : '00:00';
    }

    function getTranslateChannelKey(profile) {
        return profile?.id || `${profile?.provider || ''}:${profile?.model || ''}:${profile?.name || ''}` || 'default';
    }

    function createTranslationTaskSnapshot(task) {
        return {
            taskKey: task.taskKey,
            sourceFile: task.source?.fileName || '',
            sheetName: task.source?.sheetName || '',
            rowNumber: task.originalRowNumber || task.rowIndex + 1,
            column: task.colIndex + 1,
            profile: task.profile?.name || getCompactModelLabel(task.profile),
            model: task.profile?.model || '',
            sourceText: task.text || '',
            referenceText: task.referenceText || '',
            glossary: (task.glossaryTerms || []).map(formatTranslateGlossaryTerm).join('; ')
        };
    }

    function setExpectedTranslationTasks(tasks = []) {
        translationExpectedTaskMap = new Map();
        tasks.forEach(task => {
            if (!task?.taskKey) return;
            translationExpectedTaskMap.set(task.taskKey, {
                snapshot: createTranslationTaskSnapshot(task),
                task
            });
        });
    }

    function ensureTranslationReportCoversExpectedTasks(reason = '本轮预期任务未写入结果，可能通道中断、取消或结果未提交') {
        if (!translationRunReport || translationExpectedTaskMap.size === 0) return;
        const entries = Array.isArray(translationRunReport.entries) ? translationRunReport.entries : [];
        const entriesByKey = new Map(entries.filter(entry => entry?.taskKey).map(entry => [entry.taskKey, entry]));
        translationExpectedTaskMap.forEach((expectedTask, taskKey) => {
            const snapshot = expectedTask?.snapshot || expectedTask;
            const task = expectedTask?.task || null;
            const existingEntry = entriesByKey.get(taskKey);
            if (existingEntry) {
                if (isBlankTranslationResult(existingEntry.translatedText)) {
                    const failureText = makeTranslateFailureText(snapshot.sourceText, '未返回结果');
                    if (task) writeTranslationResult(task, failureText, existingEntry.qaStatus || '未返回结果');
                    Object.assign(existingEntry, snapshot, {
                        status: 'missing',
                        translatedText: failureText,
                        qaStatus: existingEntry.qaStatus || '未返回结果',
                        completenessRisk: existingEntry.completenessRisk || '',
                        actionSuggestion: '建议补译',
                        error: existingEntry.error || reason,
                        userDecision: '',
                        revisedText: '',
                        decisionNote: '',
                        manualResolutionValid: false,
                        revisionApplied: false
                    });
                }
                return;
            }
            const failureText = makeTranslateFailureText(snapshot.sourceText, '未返回结果');
            if (task) writeTranslationResult(task, failureText, '未返回结果');
            const missingEntry = {
                ...snapshot,
                status: 'missing',
                translatedText: failureText,
                qaStatus: '未返回结果',
                completenessRisk: '',
                actionSuggestion: '建议补译',
                error: reason,
                userDecision: '',
                revisedText: '',
                decisionNote: '',
                manualResolutionValid: false,
                revisionApplied: false
            };
            entries.push(missingEntry);
            entriesByKey.set(taskKey, missingEntry);
        });
        translationRunReport.entries = entries;
    }

    function getTranslateChannelStatusLabel(status) {
        const labels = {
            waiting: '等待',
            running: '翻译中',
            retrying: '重试/修复',
            paused: '暂停',
            done: '完成',
            warning: '完成，有异常',
            failed: '已停止'
        };
        return labels[status] || '等待';
    }

    function createTranslateChannelProgressRecord(profile) {
        return {
            profile,
            completed: 0,
            total: 0,
            success: 0,
            failed: 0,
            qaFailed: 0,
            congestionCount: 0,
            interruptionCount: 0,
            retryCount: 0,
            slowdownCount: 0,
            batchSplitCount: 0,
            requestCount: 0,
            requestDurationMs: 0,
            requestStats: {},
            qaRepairTaskCount: 0,
            qaRepairRetryCount: 0,
            lastRequestDurationMs: 0,
            lastRequestKind: '',
            lastRequestOutcome: '',
            lastIncidentAt: 0,
            status: 'waiting',
            message: '等待开始翻译',
            updatedAt: Date.now()
        };
    }

    function classifyTranslateChannelIncident(error) {
        const status = Number(error?.status || 0);
        const diagnostic = `${typeof error === 'string' ? error : ''} ${error?.message || ''} ${error?.rawText || ''} ${JSON.stringify(error?.payload || '')}`;
        const congestion = status === 429 || status === 503 || error?.isRateLimited ||
            /rate.?limit|too many requests|overload|high demand|quota|限流|频率|服务繁忙|拥堵/i.test(diagnostic);
        if (congestion) return 'congestion';

        const interruption = status === 408 || (status >= 500 && status <= 599) || error?.isTimeout ||
            /timeout|超时|network|网络|fetch failed|connection|无法连接|连接失败|请求接口失败|读取接口返回失败|socket|ECONN|断开|中断|临时不可用|UNAVAILABLE/i.test(diagnostic);
        return interruption ? 'interruption' : '';
    }

    function recordTranslateChannelIncident(profile, error = null, options = {}) {
        if (!profile) return;
        const key = getTranslateChannelKey(profile);
        const previous = translateChannelProgressState.get(key) || createTranslateChannelProgressRecord(profile);
        const kind = error ? classifyTranslateChannelIncident(error) : '';
        const incidentRecorded = Boolean(kind) || Boolean(options.slowdown);
        const incidentAt = incidentRecorded ? Date.now() : Number(previous.lastIncidentAt || 0);
        translateChannelProgressState.set(key, {
            ...previous,
            profile,
            congestionCount: Number(previous.congestionCount || 0) + (kind === 'congestion' ? 1 : 0),
            interruptionCount: Number(previous.interruptionCount || 0) + (kind === 'interruption' ? 1 : 0),
            retryCount: Number(previous.retryCount || 0) + (options.retry ? 1 : 0),
            slowdownCount: Number(previous.slowdownCount || 0) + (options.slowdown ? 1 : 0),
            lastIncidentAt: incidentAt,
            updatedAt: Date.now()
        });
        renderTranslateChannelProgress();
    }

    function getTranslateChannelIncidentCount(profile) {
        if (!profile) return 0;
        const state = translateChannelProgressState.get(getTranslateChannelKey(profile));
        return Number(state?.congestionCount || 0) + Number(state?.interruptionCount || 0);
    }

    function recordTranslateChannelBatchSplit(profile, sourceSize, splitSizes = [], reason = '') {
        if (!profile) return;
        const key = getTranslateChannelKey(profile);
        const previous = translateChannelProgressState.get(key) || createTranslateChannelProgressRecord(profile);
        translateChannelProgressState.set(key, {
            ...previous,
            profile,
            batchSplitCount: Number(previous.batchSplitCount || 0) + 1,
            status: 'retrying',
            message: `批量结构异常，自动拆分 ${sourceSize} → ${splitSizes.join('+')}${reason ? `（${reason}）` : ''}`,
            updatedAt: Date.now()
        });
        renderTranslateChannelProgress();
    }

    function recordTranslateRequestTiming(profile, kind, startedAt, details = {}) {
        if (!profile || !startedAt) return;
        try {
            const key = getTranslateChannelKey(profile);
            const previous = translateChannelProgressState.get(key) || createTranslateChannelProgressRecord(profile);
            const durationMs = Math.max(0, Date.now() - startedAt);
            const requestCount = Number(previous.requestCount || 0) + 1;
            const requestDurationMs = Number(previous.requestDurationMs || 0) + durationMs;
            const outcome = details.outcome || 'success';
            const requestKind = ['batch', 'single', 'qa-repair'].includes(kind) ? kind : 'other';
            const requestStats = { ...(previous.requestStats || {}) };
            const previousKindStats = requestStats[requestKind] || {};
            requestStats[requestKind] = {
                requestCount: Number(previousKindStats.requestCount || 0) + 1,
                successCount: Number(previousKindStats.successCount || 0) + (outcome === 'success' ? 1 : 0),
                errorCount: Number(previousKindStats.errorCount || 0) + (outcome === 'success' ? 0 : 1),
                durationMs: Number(previousKindStats.durationMs || 0) + durationMs,
                submittedItemCount: Number(previousKindStats.submittedItemCount || 0) + Math.max(1, Number(details.itemCount || 1))
            };
            translateChannelProgressState.set(key, {
                ...previous,
                profile,
                requestCount,
                requestDurationMs,
                requestStats,
                lastRequestDurationMs: durationMs,
                lastRequestKind: kind,
                lastRequestOutcome: outcome,
                updatedAt: Date.now()
            });
            console.info('翻译请求计时', {
                provider: profile.provider || '',
                model: profile.model || '',
                kind,
                itemCount: Number(details.itemCount || 1),
                attempt: Number(details.attempt || 1),
                durationMs,
                outcome,
                incident: details.error ? classifyTranslateChannelIncident(details.error) : ''
            });
            renderTranslateChannelProgress();
        } catch {
            // Telemetry must never turn a successful translation into a retry or failure.
        }
    }

    function recordTranslateQaRepairAttempt(profile, attempt = 0) {
        if (!profile) return;
        const key = getTranslateChannelKey(profile);
        const previous = translateChannelProgressState.get(key) || createTranslateChannelProgressRecord(profile);
        translateChannelProgressState.set(key, {
            ...previous,
            profile,
            qaRepairTaskCount: Number(previous.qaRepairTaskCount || 0) + (Number(attempt) === 0 ? 1 : 0),
            qaRepairRetryCount: Number(previous.qaRepairRetryCount || 0) + (Number(attempt) > 0 ? 1 : 0),
            updatedAt: Date.now()
        });
        renderTranslateChannelProgress();
    }

    function initTranslateChannelProgress(tasks = []) {
        translateChannelProgressState = new Map();
        tasks.forEach(task => {
            const key = getTranslateChannelKey(task.profile);
            const previous = translateChannelProgressState.get(key) || createTranslateChannelProgressRecord(task.profile);
            previous.total += 1;
            translateChannelProgressState.set(key, previous);
        });
        renderTranslateChannelProgress();
    }

    function updateTranslateChannelProgress(profile, updates = {}) {
        if (!profile) return;
        const key = getTranslateChannelKey(profile);
        const previous = translateChannelProgressState.get(key) || createTranslateChannelProgressRecord(profile);
        translateChannelProgressState.set(key, {
            ...previous,
            ...updates,
            profile,
            updatedAt: Date.now()
        });
        renderTranslateChannelProgress();
    }

    function recordTranslateChannelResult(task, status) {
        const key = getTranslateChannelKey(task.profile);
        const previous = translateChannelProgressState.get(key) || createTranslateChannelProgressRecord(task.profile);
        const next = {
            ...previous,
            profile: task.profile,
            completed: previous.completed + 1,
            success: previous.success + (status === 'success' ? 1 : 0),
            failed: previous.failed + (status === 'success' ? 0 : 1),
            qaFailed: previous.qaFailed + (status === 'qa_failed' ? 1 : 0),
            updatedAt: Date.now()
        };
        if (next.total > 0 && next.completed >= next.total) {
            next.status = next.failed > 0 ? 'warning' : 'done';
            next.message = next.failed > 0
                ? `已完成，发现问题 ${next.failed} 个`
                : '已完成全部翻译';
        } else if (!['retrying', 'paused', 'failed', 'warning'].includes(next.status)) {
            next.status = 'running';
        }
        translateChannelProgressState.set(key, next);
        renderTranslateChannelProgress();
    }

    function markUnfinishedTranslateChannels(status = 'failed', message = '任务已停止，未完成后续翻译') {
        translateChannelProgressState.forEach((state, key) => {
            if (state.total > 0 && state.completed < state.total && !['failed', 'done', 'warning'].includes(state.status)) {
                translateChannelProgressState.set(key, {
                    ...state,
                    status,
                    message,
                    updatedAt: Date.now()
                });
            }
        });
        renderTranslateChannelProgress();
    }

    function renderTranslateChannelProgress() {
        if (!translateChannelStatusPanel || !translateChannelStatusGrid) return;
        const states = [...translateChannelProgressState.values()];
        if (states.length === 0) {
            translateChannelStatusPanel.style.display = 'none';
            translateChannelStatusGrid.innerHTML = '';
            return;
        }

        translateChannelStatusPanel.style.display = 'block';
        translateChannelStatusGrid.innerHTML = states.map(state => {
            const total = Math.max(0, Number(state.total || 0));
            const completed = Math.max(0, Number(state.completed || 0));
            const percent = total > 0 ? Math.min(100, Math.round((completed / total) * 100)) : 0;
            const label = getTranslateChannelStatusLabel(state.status);
            const modelText = getModelDisplayName(state.profile?.provider, state.profile?.model);
            const failureText = state.failed > 0
                ? ` · 发现问题 ${state.failed}${state.qaFailed > 0 ? `（质检 ${state.qaFailed}）` : ''}`
                : '';
            const lastText = state.updatedAt && ['running', 'retrying'].includes(state.status)
                ? ` · 最后更新 ${formatTranslateDuration(Date.now() - state.updatedAt)} 前`
                : '';
            const congestionCount = Number(state.congestionCount || 0);
            const interruptionCount = Number(state.interruptionCount || 0);
            const retryCount = Number(state.retryCount || 0);
            const slowdownCount = Number(state.slowdownCount || 0);
            const batchSplitCount = Number(state.batchSplitCount || 0);
            const requestCount = Number(state.requestCount || 0);
            const requestStats = state.requestStats || {};
            const batchRequestCount = Number(requestStats.batch?.requestCount || 0);
            const singleRequestCount = Number(requestStats.single?.requestCount || 0);
            const qaRepairRequestCount = Number(requestStats['qa-repair']?.requestCount || 0);
            const qaRepairTaskCount = Number(state.qaRepairTaskCount || 0);
            const qaRepairRetryCount = Number(state.qaRepairRetryCount || 0);
            const averageRequestMs = requestCount > 0
                ? Number(state.requestDurationMs || 0) / requestCount
                : 0;
            const averageRequestText = averageRequestMs >= 1000
                ? `${(averageRequestMs / 1000).toFixed(1)}秒`
                : `${Math.round(averageRequestMs)}毫秒`;
            const incidentCount = congestionCount + interruptionCount;
            const healthAdvice = incidentCount >= 3 || slowdownCount >= 2
                ? '<span class="channel-health-advice">建议降低并发</span>'
                : '';
            return `
                <div class="channel-status-card ${escapeAttribute(state.status || 'waiting')}">
                    <div class="channel-status-top">
                        <span class="channel-status-name" title="${escapeAttribute(getApiProfileLabel(state.profile))}">${escapeHtml(state.profile?.name || getPlatformName(state.profile?.provider))}</span>
                        <span class="channel-status-badge">${escapeHtml(label)}</span>
                    </div>
                    <div class="channel-status-meter">
                        <div class="channel-status-fill" style="width: ${percent}%"></div>
                    </div>
                    <div class="channel-status-meta">
                        <span>${completed} / ${total}</span>
                        <span>${percent}%</span>
                    </div>
                    <div class="channel-status-message">${escapeHtml(modelText)}${state.message ? ` · ${escapeHtml(state.message)}` : ''}${failureText}${lastText}</div>
                    <div class="channel-health-row" aria-label="通道健康统计">
                        <span class="channel-health-chip${congestionCount ? ' warning' : ''}">拥堵 ${congestionCount}</span>
                        <span class="channel-health-chip${interruptionCount ? ' danger' : ''}">超时/断连 ${interruptionCount}</span>
                        <span class="channel-health-chip${retryCount ? ' warning' : ''}">重试 ${retryCount}</span>
                        <span class="channel-health-chip${slowdownCount ? ' warning' : ''}">降速 ${slowdownCount}</span>
                        ${batchSplitCount ? `<span class="channel-health-chip warning">拆批 ${batchSplitCount}</span>` : ''}
                        ${qaRepairTaskCount ? `<span class="channel-health-chip warning">QA修复 ${qaRepairTaskCount}${qaRepairRetryCount ? ` · 续修 ${qaRepairRetryCount}` : ''}</span>` : ''}
                        ${requestCount ? `<span class="channel-health-chip" title="批量 ${batchRequestCount} / 单条 ${singleRequestCount} / QA修复 ${qaRepairRequestCount}">请求 ${requestCount}（批 ${batchRequestCount} / 单 ${singleRequestCount} / 修 ${qaRepairRequestCount}）· 均时 ${averageRequestText}</span>` : ''}
                        ${healthAdvice}
                    </div>
                </div>
            `;
        }).join('');
    }

    function updateTranslateInspectorRuntime() {
        if (getActiveToolKey() !== 'translate') return;
        const states = [...translateChannelProgressState.values()];
        const failures = states.reduce((sum, state) => sum + Number(state.failed || 0), 0);
        const running = states.filter(state => ['running', 'retrying'].includes(state.status)).length;
        const paused = states.filter(state => state.status === 'paused').length;
        const hasTiming = Boolean(translateRunStartedAt || translateRunSummaryState.total > 0 || translateRunSummaryState.completed > 0);
        const languageText = getTranslateLanguageRunHeadline();
        setInspectorField('inspectorTaskBadge', translateRunSummaryState.phase || '运行中');
        setInspectorField('inspectorInputState', originalFileName || '等待文件');
        setInspectorField('inspectorOutputState', activeTranslateRunId ? `${languageText ? `${languageText} · ` : ''}运行中写入` : (translatedWorkbook ? `${languageText ? `${languageText} · ` : ''}已生成结果` : '等待开始'));
        setInspectorField('inspectorTaskPhase', isPaused ? `${languageText ? `${languageText} · ` : ''}已暂停` : (translateRunSummaryState.phase || `${languageText ? `${languageText} · ` : ''}翻译运行中`));
        setInspectorField('inspectorDataState', activeTranslateRunId ? '实时保存进度' : '仅在浏览器内处理');
        setInspectorField('inspectorEstimateBadge', activeTranslateRunId ? '计时中' : (hasTiming ? '已计时' : '待开始'));
        setInspectorField('inspectorEstimateTime', getTranslateElapsedText());
        setInspectorField('inspectorTaskBatches', `${translateRunSummaryState.completed}/${translateRunSummaryState.total}`);
        setInspectorField('inspectorTaskFailures', failures > 0 ? `问题 ${failures} 个` : (running || paused ? '暂无问题' : '运行中显示'));
    }

    function updateTranslateRunSummary(completed, total, phase = '') {
        translateRunSummaryState = {
            completed: Math.max(0, Number(completed || 0)),
            total: Math.max(0, Number(total || 0)),
            phase: phase || translateRunSummaryState.phase || '翻译运行中'
        };
        const states = [...translateChannelProgressState.values()];
        const failures = states.reduce((sum, state) => sum + Number(state.failed || 0), 0);
        const activeStates = states.filter(state => ['running', 'retrying'].includes(state.status));
        const activeText = activeStates.slice(0, 2)
            .map(state => `${state.profile?.name || getCompactModelLabel(state.profile)}${state.message ? `：${state.message}` : ''}`)
            .join('；');
        const progressInfo = document.getElementById('translateProgressInfo');
        if (progressInfo && progressSection.style.display !== 'none') {
            const statusPrefix = isPaused ? '翻译已暂停' : (translateRunSummaryState.phase || '正在翻译');
            const languageText = getTranslateLanguageRunHeadline();
            progressInfo.textContent = `${statusPrefix}${languageText ? `：${languageText}` : ''}...（已完成 ${translateRunSummaryState.completed}/${translateRunSummaryState.total} 个，用时 ${getTranslateElapsedText()}${failures ? `，发现问题 ${failures} 个` : ''}${activeText ? `，${activeText}` : ''}）`;
        }
        renderTranslateLanguageRunStatus();
        updateTranslateInspectorRuntime();
    }

    function startTranslateElapsedTimer() {
        translateRunStartedAt = Date.now();
        if (translateElapsedTimer) clearInterval(translateElapsedTimer);
        translateElapsedTimer = setInterval(() => {
            updateTranslateRunSummary(translateRunSummaryState.completed, translateRunSummaryState.total);
            renderTranslateChannelProgress();
        }, 1000);
    }

    function stopTranslateElapsedTimer() {
        if (translateElapsedTimer) clearInterval(translateElapsedTimer);
        translateElapsedTimer = null;
        updateTranslateRunSummary(translateRunSummaryState.completed, translateRunSummaryState.total);
    }

    function normalizeTranslationProgressEntries(progress) {
        const rawEntries = Array.isArray(progress?.completedTasks)
            ? progress.completedTasks
            : (Array.isArray(progress?.translationRunReport?.entries) ? progress.translationRunReport.entries : []);
        const entriesByKey = new Map();
        rawEntries.forEach(entry => {
            const compactEntry = compactTranslationProgressEntry(entry);
            if (!compactEntry) return;
            entriesByKey.set(compactEntry.taskKey, compactEntry);
        });
        return [...entriesByKey.values()];
    }

    function countTranslationProgressEntries(entries = [...translationProgressTasks.values()]) {
        return entries.reduce((counts, entry) => {
            const status = String(entry?.status || '').trim().toLowerCase();
            if (['failed', 'missing', 'error', 'qa_failed'].includes(status) || isTranslateFailureText(entry?.translatedText)) {
                counts.failCount++;
            } else {
                counts.successCount++;
            }
            return counts;
        }, { successCount: 0, failCount: 0 });
    }

    function getTranslateSourceSignature() {
        const signatureParts = translateSources.map(source => {
            const header = Array.isArray(source.rows?.[0]) ? source.rows[0].join('\u001f') : '';
            const rowCount = Array.isArray(source.rows) ? source.rows.length : 0;
            const colCount = Array.isArray(source.rows?.[0]) ? source.rows[0].length : 0;
            return [
                source.fileName,
                source.sheetName,
                source.fileSize || '',
                source.fileLastModified || '',
                rowCount,
                colCount,
                header
            ].join('\u001e');
        });
        return makeStableId(signatureParts.join('\u001d'));
    }

    function buildTranslationProgressPayload(currentRow = 1) {
        return {
            fileName: originalFileName,
            sourceSignature: getTranslateSourceSignature(),
            totalRows: sheetData?.length || 0,
            totalTasks: translationRunReport?.totalTasks || translationProgressTasks.size,
            currentRow,
            successCount,
            failCount,
            selectedColumns: [...selectedColumns],
            targetLang: document.getElementById('targetLang')?.value || '',
            selectedTargetLangs: getSelectedTranslateTargetLangs(),
            selectedProfileIds: [...selectedTranslateProfileIds],
            selectedSourceIds: [...selectedTranslateSourceIds],
            translateStrategy: getTranslateStrategy(),
            referenceColumn,
            runCreatedAt: translationRunReport?.createdAt || null,
            completedTasks: globalThis.indexedDB ? [] : [...translationProgressTasks.values()]
        };
    }

    function saveCurrentTranslationProgress(currentRow = 1) {
        if (!originalFileName) return Promise.resolve(false);
        return saveTranslationProgress(buildTranslationProgressPayload(currentRow));
    }

    function formatTranslateGlossaryTerm(term) {
        if (term.constraint === 'reference') {
            return `${term.source}≈${term.referenceTarget || term.english || ''}（参考）`;
        }
        return `${term.source}=>${term.target}`;
    }

    function getTranslationCompletenessRiskLabel(qaStatus = '') {
        const text = String(qaStatus || '');
        if (!text || text === '通过') return '';
        const risks = [];
        if (/疑似译文过短/.test(text)) risks.push('疑似译文过短');
        if (/疑似内容流失/.test(text)) risks.push('疑似内容流失');
        if (/繁简转换不完整/.test(text)) risks.push('繁简转换不完整');
        if (/繁中关键语义缺失/.test(text)) risks.push('繁中关键语义缺失');
        if (/混入英文|混入中文|目标.+中混入|疑似照抄英文|目标译文仍含英文|玩法名疑似沿用英文|英文玩法名需确认|英文专名需确认|英文参考短语需确认|英文参考词需确认|源文英文专名需确认|游戏借词|英文词需确认|与中文原文高度一致/.test(text)) {
            risks.push('语言混入风险');
        }
        if (/受保护UI标记缺失或被翻译/.test(text)) risks.push('等级/UI 标记不一致');
        if (/译文明显短于参考译文/.test(text)) risks.push('明显短于参考译文');
        if (/括号\/引号结构/.test(text)) risks.push('结构信息可能缺失');
        return [...new Set(risks)].join('；');
    }

    function getTranslationActionSuggestion(status, qaStatus = '') {
        if (status === 'failed' || status === 'missing') return '建议重新翻译';
        if (/译文长度超出建议/.test(String(qaStatus || ''))) return '可二次精简；精简失败则保留原译文人工确认';
        if (status === 'qa_failed') {
            const hardQa = isHardTranslationReportEntry({
                status,
                translatedText: '已有译文',
                qaStatus
            });
            if (hardQa) return '阻断交付：必须重新翻译或填写修订译文';
            const completenessRisk = getTranslationCompletenessRiskLabel(qaStatus);
            if (completenessRisk) return '建议复查原文和译文；确认可用后选择“接受现译”';
            return '保留当前译文，建议人工确认';
        }
        return '';
    }

    function buildTranslationReportEntry(task, translated, qaStatus = '') {
        const normalizedTranslated = normalizeTranslateResultText(translated, task.text);
        const status = getTranslationReportStatus(normalizedTranslated, qaStatus);
        const qaTerms = task.glossaryTerms || [];
        const completenessRisk = getTranslationCompletenessRiskLabel(qaStatus);
        return {
            taskKey: task.taskKey,
            status,
            sourceFile: task.source?.fileName || '',
            sheetName: task.source?.sheetName || '',
            rowNumber: task.originalRowNumber || task.rowIndex + 1,
            column: task.colIndex + 1,
            profile: task.profile?.name || getCompactModelLabel(task.profile),
            model: task.profile?.model || '',
            sourceText: task.text,
            referenceText: task.referenceText || '',
            translatedText: normalizedTranslated,
            glossary: qaTerms.map(formatTranslateGlossaryTerm).join('; '),
            qaStatus,
            completenessRisk,
            actionSuggestion: getTranslationActionSuggestion(status, qaStatus),
            error: status === 'failed' || status === 'missing'
                ? normalizedTranslated
                : (status === 'qa_failed' ? qaStatus : ''),
            userDecision: '',
            revisedText: '',
            decisionNote: '',
            manualResolutionValid: false,
            revisionApplied: false
        };
    }

    function restoreTranslationProgressSettings(progress) {
        if (Array.isArray(progress.selectedSourceIds) && progress.selectedSourceIds.length > 0) {
            const knownSourceIds = new Set(translateSources.map(source => source.id));
            const nextSourceIds = progress.selectedSourceIds.filter(id => knownSourceIds.has(id));
            if (nextSourceIds.length > 0) {
                selectedTranslateSourceIds = new Set(nextSourceIds);
                rebuildTranslateSheetData();
                renderTranslateSheetSelectList();
            }
        }

        if (Array.isArray(progress.selectedColumns) && sheetData?.[0]) {
            selectedColumns = progress.selectedColumns
                .map(Number)
                .filter(index => Number.isInteger(index) && index >= 0 && index < sheetData[0].length);
        }

        if (Array.isArray(progress.selectedProfileIds)) {
            selectedTranslateProfileIds = new Set(progress.selectedProfileIds);
            renderTranslateProfileList();
        }

        const targetLangSelect = document.getElementById('targetLang');
        const hasTargetLang = targetLangSelect && [...targetLangSelect.options].some(option => option.value === progress.targetLang);
        if (progress.targetLang && hasTargetLang) {
            targetLangSelect.value = progress.targetLang;
        }
        if (Array.isArray(progress.selectedTargetLangs)) {
            const knownTargets = new Set(getTranslateTargetLanguageOptions().map(option => option.value));
            const restoredTargets = progress.selectedTargetLangs.filter(lang => knownTargets.has(lang));
            if (restoredTargets.length > 0) {
                selectedTranslateTargetLangs = new Set(restoredTargets);
                renderTranslateTargetLanguageList();
            }
        }

        if (translateStrategySelect && progress.translateStrategy) {
            translateStrategySelect.value = progress.translateStrategy;
        }
        referenceColumn = Number.isInteger(progress.referenceColumn) ? progress.referenceColumn : null;
        renderColumnList();
    }

    function restoreCompletedTranslationTasks(tasks, savedEntries, targetLang = '', options = {}) {
        const taskKeys = new Set(tasks.map(task => task.taskKey));
        const entries = savedEntries.filter(entry => taskKeys.has(entry.taskKey));
        const entriesByKey = new Map(entries.map(entry => [entry.taskKey, entry]));
        const completedTaskKeys = new Set();
        translationProgressTasks = new Map();
        const restoredReportEntries = [];

        tasks.forEach(task => {
            const entry = entriesByKey.get(task.taskKey);
            if (!entry) return;
            const savedStatus = String(entry.status || '').trim().toLowerCase();
            const canRestoreAsCompleted =
                !['failed', 'missing', 'error'].includes(savedStatus) &&
                !isTranslateFailureText(entry.translatedText);
            if (!canRestoreAsCompleted) return;

            const translated = normalizeTranslateResultText(entry.translatedText, task.text);
            const currentQaStatus = options.trustSavedQa
                ? (entry.qaStatus || '通过')
                : summarizeTranslationQa(
                    task.text,
                    translated,
                    task.glossaryTerms || [],
                    targetLang || translationRunReport?.targetLang || targetLangSelect?.value || '',
                    task
                );
            const reportEntry = buildTranslationReportEntry(task, translated, currentQaStatus);
            const decisionPolicy = globalThis.NexusTranslationDeliveryPolicy;
            const userDecision = decisionPolicy?.normalizeDecision
                ? decisionPolicy.normalizeDecision(entry.userDecision)
                : (entry.userDecision || '');
            const currentKind = classifyTranslationReportEntry(reportEntry);
            const manualResolutionValid = decisionPolicy?.isManualResolutionValid
                ? decisionPolicy.isManualResolutionValid(
                    userDecision,
                    currentKind,
                    isTranslationQaPassed(currentQaStatus)
                )
                : (
                    (userDecision === 'accept_current' && ['success', 'soft', 'length'].includes(currentKind)) ||
                    (userDecision === 'use_revision' && isTranslationQaPassed(currentQaStatus))
                );
            Object.assign(reportEntry, {
                userDecision,
                revisedText: entry.revisedText || '',
                decisionNote: entry.decisionNote || '',
                manualResolutionValid,
                revisionApplied: userDecision === 'use_revision' && Boolean(entry.revisionApplied)
            });
            if (userDecision === 'must_retry') {
                reportEntry.status = 'qa_failed';
                reportEntry.qaStatus = appendTranslationQaIssue(reportEntry.qaStatus, '用户要求重新翻译');
                reportEntry.completenessRisk = '用户要求重新翻译';
                reportEntry.actionSuggestion = '阻断交付：重新翻译该行';
                reportEntry.error = reportEntry.qaStatus;
            } else if (reportEntry.manualResolutionValid) {
                reportEntry.status = 'success';
            }
            writeTranslationResult(task, translated, reportEntry.qaStatus);
            restoredReportEntries.push(reportEntry);
            const compactEntry = compactTranslationProgressEntry(reportEntry);
            if (compactEntry) translationProgressTasks.set(task.taskKey, compactEntry);
            if (!isRepairableTranslationReportEntry(reportEntry)) {
                completedTaskKeys.add(task.taskKey);
            }
        });
        if (translationRunReport) {
            translationRunReport.entries = restoredReportEntries;
        }

        const counts = countTranslationProgressEntries([...translationProgressTasks.values()]);
        successCount = counts.successCount;
        failCount = counts.failCount;
        return tasks.filter(task => !completedTaskKeys.has(task.taskKey));
    }

    function normalizeTranslateImportKeyPart(value) {
        return String(value ?? '').trim().replace(/\s+/g, ' ');
    }

    function makeTranslateImportMatchKey(parts = []) {
        return parts.map(normalizeTranslateImportKeyPart).join('\u001f');
    }

    function getTaskImportMatchKeys(task) {
        const sourceFile = task.source?.fileName || '';
        const sheetName = task.source?.sheetName || '';
        const rowNumber = task.originalRowNumber || task.rowIndex + 1;
        const column = task.colIndex + 1;
        const model = task.profile?.model || '';
        const profile = task.profile?.name || getCompactModelLabel(task.profile);
        const sourceText = task.text || '';
        const modelKeys = [...new Set([model, profile].filter(Boolean))];
        const keys = [];
        modelKeys.forEach(modelKey => {
            keys.push(makeTranslateImportMatchKey([sourceFile, sheetName, rowNumber, column, modelKey, sourceText]));
            keys.push(makeTranslateImportMatchKey([sheetName, rowNumber, column, modelKey, sourceText]));
            keys.push(makeTranslateImportMatchKey([rowNumber, column, modelKey, sourceText]));
        });
        keys.push(makeTranslateImportMatchKey([sourceFile, sheetName, rowNumber, column, sourceText]));
        keys.push(makeTranslateImportMatchKey([sheetName, rowNumber, column, sourceText]));
        keys.push(makeTranslateImportMatchKey([rowNumber, column, sourceText]));
        return [...new Set(keys)];
    }

    function getImportedEntryMatchKeys(entry) {
        const sourceFile = entry.sourceFile || '';
        const sheetName = entry.sheetName || '';
        const rowNumber = entry.rowNumber || '';
        const column = entry.column || '';
        const sourceText = entry.sourceText || '';
        const modelKeys = [...new Set([entry.model, entry.profile].filter(Boolean))];
        const keys = [];
        modelKeys.forEach(modelKey => {
            keys.push(makeTranslateImportMatchKey([sourceFile, sheetName, rowNumber, column, modelKey, sourceText]));
            keys.push(makeTranslateImportMatchKey([sheetName, rowNumber, column, modelKey, sourceText]));
            keys.push(makeTranslateImportMatchKey([rowNumber, column, modelKey, sourceText]));
        });
        keys.push(makeTranslateImportMatchKey([sourceFile, sheetName, rowNumber, column, sourceText]));
        keys.push(makeTranslateImportMatchKey([sheetName, rowNumber, column, sourceText]));
        keys.push(makeTranslateImportMatchKey([rowNumber, column, sourceText]));
        return [...new Set(keys)].filter(key => key.replace(/\u001f/g, '').trim());
    }

    function buildTranslateImportTaskIndex(tasks = []) {
        const index = new Map();
        tasks.forEach(task => {
            getTaskImportMatchKeys(task).forEach(key => {
                if (!index.has(key)) index.set(key, []);
                index.get(key).push(task);
            });
        });
        return index;
    }

    function buildTranslateImportTaskLookup(tasks = []) {
        return {
            taskByKey: new Map(tasks.map(task => [task.taskKey, task])),
            fallbackIndex: buildTranslateImportTaskIndex(tasks)
        };
    }

    function findImportedTranslationTaskMatch(entry, taskByKey, fallbackIndex) {
        if (entry.taskKey && taskByKey.has(entry.taskKey)) {
            return taskByKey.get(entry.taskKey);
        }
        for (const key of getImportedEntryMatchKeys(entry)) {
            const matches = fallbackIndex.get(key) || [];
            if (matches.length === 1) return matches[0];
        }
        return null;
    }

    function buildImportedTranslationRestoreEntries(tasks = [], targetLang = '', options = {}) {
        const state = importedTranslateProgressState;
        if (!state?.entries?.length) {
            return { entries: [], matched: 0, unmatched: 0, skippedTargetMismatch: 0, reviewedForCurrentContext: false };
        }
        if (state.targetLang && targetLang && state.targetLang !== targetLang) {
            return {
                entries: [],
                matched: 0,
                unmatched: 0,
                skippedTargetMismatch: state.entries.length,
                reviewedForCurrentContext: false
            };
        }

        const reviewGlossaryTerms = targetLang ? getSelectedTranslateGlossaryTerms() : [];
        const reviewContextKey = targetLang
            ? getImportedTranslationReviewContextKey(targetLang, reviewGlossaryTerms)
            : '';
        const canReuseReviewedEntries = Boolean(
            targetLang &&
            state.reviewedAt &&
            state.targetLang === targetLang &&
            state.reviewContextKey === reviewContextKey
        );
        const reviewedStateEntries = targetLang && !canReuseReviewedEntries
            ? reviewImportedTranslationEntries(state.entries || [], targetLang, reviewGlossaryTerms)
            : (state.entries || []);
        if (targetLang && !canReuseReviewedEntries) {
            const issueSummary = getTranslationReportIssueSummary(reviewedStateEntries);
            state.entries = reviewedStateEntries;
            state.targetLang = state.targetLang || targetLang;
            state.reviewedAt = Date.now();
            state.reviewContextKey = reviewContextKey;
            state.issueSummary = issueSummary;
            state.failedOrMissingCount = issueSummary.retryable;
            state.reusableEntries = reviewedStateEntries.filter(isReusableImportedTranslationEntry);
            state.suspiciousEntries = reviewedStateEntries.filter(entry =>
                entry.status === 'missing' ||
                (
                    entry.status === 'qa_failed' &&
                    entry.translatedText &&
                    !isTranslateFailureText(entry.translatedText)
                )
            );
        }

        const taskLookup = options.taskLookup || buildTranslateImportTaskLookup(tasks);
        const taskByKey = taskLookup.taskByKey;
        const fallbackIndex = taskLookup.fallbackIndex;
        const allowFallbackMatch = !state.targetLang || state.targetLang === targetLang;
        const usedTaskKeys = new Set();
        const entries = [];
        let unmatched = 0;
        let skippedTargetMismatch = 0;
        const includeQaFailed = Boolean(options.includeQaFailed);
        const restoreCandidates = reviewedStateEntries.filter(entry => {
            if (!entry?.translatedText || isTranslateFailureText(entry.translatedText)) return false;
            const kind = classifyTranslationReportEntry(entry);
            return includeQaFailed ||
                kind === 'success' ||
                kind === 'length' ||
                kind === 'soft';
        });

        restoreCandidates.forEach(entry => {
            if (!entry.taskKey && !allowFallbackMatch) {
                skippedTargetMismatch++;
                return;
            }
            const task = findImportedTranslationTaskMatch(entry, taskByKey, fallbackIndex);
            if (!task || usedTaskKeys.has(task.taskKey)) {
                unmatched++;
                return;
            }
            usedTaskKeys.add(task.taskKey);
            entries.push({
                taskKey: task.taskKey,
                status: entry.manualResolutionValid ? 'success' : (entry.status || 'success'),
                translatedText: entry.translatedText,
                qaStatus: entry.qaStatus || '',
                completenessRisk: entry.completenessRisk || '',
                actionSuggestion: entry.actionSuggestion || '',
                error: '',
                userDecision: entry.userDecision || '',
                revisedText: entry.revisedText || '',
                decisionNote: entry.decisionNote || '',
                manualResolutionValid: Boolean(entry.manualResolutionValid),
                revisionApplied: Boolean(entry.revisionApplied)
            });
        });

        return {
            entries,
            matched: entries.length,
            unmatched,
            skippedTargetMismatch,
            reviewedForCurrentContext: Boolean(targetLang)
        };
    }

    function reviewImportedTranslationEntries(entries = [], targetLang = '', selectedGlossaryTerms = null) {
        const glossaryTerms = Array.isArray(selectedGlossaryTerms)
            ? selectedGlossaryTerms
            : getSelectedTranslateGlossaryTerms();
        return (entries || []).map(entry =>
            buildReviewedImportedTranslationEntry(entry, targetLang, glossaryTerms)
        );
    }

    function buildReviewedImportedTranslationEntry(entry, targetLang = '', selectedGlossaryTerms = null) {
        const policy = globalThis.NexusTranslationDeliveryPolicy;
        const selection = policy?.selectImportedTranslation
            ? policy.selectImportedTranslation(entry)
            : {
                decision: '',
                candidateText: entry?.translatedText || '',
                revisionApplied: false,
                forceRetry: false,
                acceptRequested: false,
                decisionError: ''
            };
        const baseEntry = {
            ...entry,
            userDecision: selection.decision || '',
            translatedText: selection.candidateText,
            manualResolutionValid: false,
            revisionApplied: Boolean(selection.revisionApplied)
        };

        if (selection.decisionError) {
            const qaStatus = `需确认：${selection.decisionError}`;
            return {
                ...baseEntry,
                status: 'qa_failed',
                qaStatus,
                completenessRisk: '人工处理决定无效',
                actionSuggestion: '阻断交付：补充修订译文，或把处理决定改为“必须重译”',
                error: qaStatus
            };
        }

        if (selection.forceRetry) {
            const qaStatus = '需确认：用户要求重新翻译';
            return {
                ...baseEntry,
                status: 'qa_failed',
                qaStatus,
                completenessRisk: '用户要求重新翻译',
                actionSuggestion: '阻断交付：重新翻译该行',
                error: qaStatus
            };
        }

        const importedStatus = normalizeImportedTranslationStatus(baseEntry);
        if (
            !baseEntry.translatedText ||
            (
                !selection.revisionApplied &&
                (
                    ['failed', 'missing'].includes(importedStatus) ||
                    isTranslateFailureText(baseEntry.translatedText)
                )
            )
        ) {
            return { ...baseEntry, status: importedStatus };
        }
        const sourceText = entry.sourceText || '';
        const referenceText = entry.referenceText || '';
        const translatedText = baseEntry.translatedText || '';
        const glossaryTerms = Array.isArray(selectedGlossaryTerms)
            ? selectedGlossaryTerms
            : getSelectedTranslateGlossaryTerms();
        const currentTerms = getRelevantTranslateGlossaryTerms(
            [sourceText, referenceText],
            glossaryTerms,
            targetLang,
            24,
            { normalized: Array.isArray(selectedGlossaryTerms) }
        );
        const qaStatus = summarizeTranslationQa(
            sourceText,
            translatedText,
            currentTerms,
            targetLang,
            {
                referenceText,
                glossaryTerms: currentTerms,
                projectRules: currentProject?.rules || ''
            }
        );
        let reviewedEntry;
        if (isTranslationQaPassed(qaStatus)) {
            reviewedEntry = {
                ...baseEntry,
                status: 'success',
                qaStatus: '通过',
                completenessRisk: '',
                actionSuggestion: '',
                error: ''
            };
        } else {
            reviewedEntry = {
                ...baseEntry,
                status: 'qa_failed',
                qaStatus,
                completenessRisk: getTranslationCompletenessRiskLabel(qaStatus) || '译后复查风险',
                actionSuggestion: getTranslationActionSuggestion('qa_failed', qaStatus),
                error: qaStatus
            };
        }

        if (selection.acceptRequested) {
            const kind = classifyTranslationReportEntry(reviewedEntry);
            const canAccept = policy?.canAcceptCurrentKind
                ? policy.canAcceptCurrentKind(kind)
                : ['success', 'soft', 'length'].includes(kind);
            if (canAccept) {
                return {
                    ...reviewedEntry,
                    status: 'success',
                    manualResolutionValid: true,
                    completenessRisk: reviewedEntry.completenessRisk || '',
                    actionSuggestion: '人工已确认接受现译',
                    error: ''
                };
            }
            const blockedQa = appendTranslationQaIssue(
                reviewedEntry.qaStatus,
                '硬错误不能直接接受，必须重译或提供修订译文'
            );
            return {
                ...reviewedEntry,
                status: 'qa_failed',
                qaStatus: blockedQa,
                manualResolutionValid: false,
                actionSuggestion: '阻断交付：改为“必须重译”，或填写修订译文后选择“使用修订译文”',
                error: blockedQa
            };
        }

        if (selection.revisionApplied && isTranslationQaPassed(reviewedEntry.qaStatus)) {
            reviewedEntry.manualResolutionValid = true;
            reviewedEntry.actionSuggestion = '人工修订已通过复检';
        }
        return reviewedEntry;
    }

    function reviewImportedTranslationCompleteness() {
        const state = importedTranslateProgressState;
        if (!state?.entries?.length) {
            alert('请先导入之前下载的翻译报告或带“翻译报告”分页的译文文件。');
            return false;
        }
        const currentTargetLang = targetLangSelect?.value || document.getElementById('targetLang')?.value || '';
        const targetLang = state.targetLang || currentTargetLang;
        if (!targetLang) {
            alert('请先选择目标语言，工具需要知道按哪种语言规则复查。');
            return false;
        }
        if (state.targetLang && currentTargetLang && state.targetLang !== currentTargetLang) {
            const confirmed = confirm(`导入报告疑似为 ${getTranslateLanguageName(state.targetLang)}，当前页面选择的是 ${getTranslateLanguageName(currentTargetLang)}。\n\n将按导入报告语言复查，是否继续？`);
            if (!confirmed) return false;
        }

        const reviewGlossaryTerms = getSelectedTranslateGlossaryTerms();
        const reviewedEntries = reviewImportedTranslationEntries(state.entries, targetLang, reviewGlossaryTerms);
        let reportMissingEntries = [];
        if (sheetData && translateSources.length && selectedColumns.length && getSelectedTranslateProfiles().length) {
            const allTasks = collectTranslationTasks(getSelectedTranslateProfiles(), { deferGlossary: true });
            reportMissingEntries = buildImportedReportMissingTaskEntries(allTasks, reviewedEntries);
        }
        const mergedReviewedEntries = [...reviewedEntries, ...reportMissingEntries];
        const reusableEntries = mergedReviewedEntries.filter(isReusableImportedTranslationEntry);
        const suspiciousEntries = mergedReviewedEntries.filter(entry =>
            entry.status === 'missing' ||
            (
                entry.status === 'qa_failed' &&
                entry.translatedText &&
                !isTranslateFailureText(entry.translatedText)
            )
        );
        const issueSummary = getTranslationReportIssueSummary(mergedReviewedEntries);
        const failedOrMissingCount = issueSummary.retryable;
        importedTranslateProgressState = {
            ...state,
            targetLang,
            entries: mergedReviewedEntries,
            reusableEntries,
            suspiciousEntries,
            reviewedAt: Date.now(),
            reviewContextKey: getImportedTranslationReviewContextKey(targetLang, reviewGlossaryTerms),
            reviewSummary: {
                total: mergedReviewedEntries.length,
                reusable: reusableEntries.length,
                suspicious: suspiciousEntries.length,
                failedOrMissing: failedOrMissingCount,
                reportMissing: reportMissingEntries.length
            },
            issueSummary,
            failedOrMissingCount
        };
        updateTranslateProgressImportStatus();
        if (suspiciousEntries.length) {
            const missingText = reportMissingEntries.length ? `，其中 ${reportMissingEntries.length} 条是报告缺失任务` : '';
            setStatus('warning', '复查完成，发现可疑译文', `共 ${suspiciousEntries.length} 条疑似漏译/不完整${missingText}。可直接补译可疑行，也可在“定向重译问题类型”里只勾选混入中文等类型。`);
        } else {
            setStatus('success', '复查完成', '未发现明显漏译或内容不完整风险。');
        }
        return true;
    }

    function importedEntryMatchesTask(entry, task) {
        if (!entry || !task) return false;
        const rowNumber = task.originalRowNumber || task.rowIndex + 1;
        const column = task.colIndex + 1;
        if (entry.rowNumber && entry.rowNumber !== rowNumber) return false;
        if (entry.column && entry.column !== column) return false;
        if (entry.sourceText && normalizeTranslateImportKeyPart(entry.sourceText) !== normalizeTranslateImportKeyPart(task.text)) return false;
        if (entry.sheetName && task.source?.sheetName && normalizeTranslateImportKeyPart(entry.sheetName) !== normalizeTranslateImportKeyPart(task.source.sheetName)) return false;
        if (entry.sourceFile && task.source?.fileName && normalizeTranslateImportKeyPart(entry.sourceFile) !== normalizeTranslateImportKeyPart(task.source.fileName)) return false;
        return Boolean(entry.rowNumber || entry.column || entry.sourceText);
    }

    function findTaskForImportedTranslationEntry(entry, tasks = []) {
        if (entry.taskKey) {
            const exact = tasks.find(task => task.taskKey === entry.taskKey);
            if (exact) return exact;
        }
        const candidates = tasks.filter(task => importedEntryMatchesTask(entry, task));
        if (!candidates.length) return null;
        const modelKeys = new Set([entry.model, entry.profile].filter(Boolean).map(normalizeTranslateImportKeyPart));
        const modelMatch = candidates.find(task =>
            modelKeys.has(normalizeTranslateImportKeyPart(task.profile?.model || '')) ||
            modelKeys.has(normalizeTranslateImportKeyPart(task.profile?.name || getCompactModelLabel(task.profile)))
        );
        return modelMatch || candidates[0];
    }

    function buildImportedReportMissingTaskEntries(tasks = [], entries = []) {
        if (!tasks.length) return [];
        const taskByKey = new Map(tasks.map(task => [task.taskKey, task]));
        const fallbackIndex = buildTranslateImportTaskIndex(tasks);
        const coveredTaskKeys = new Set();

        entries.forEach(entry => {
            const task = findImportedTranslationTaskMatch(entry, taskByKey, fallbackIndex);
            if (task?.taskKey) coveredTaskKeys.add(task.taskKey);
        });

        return tasks
            .filter(task => !coveredTaskKeys.has(task.taskKey))
            .map(task => ({
                taskKey: task.taskKey,
                status: 'missing',
                sourceFile: task.source?.fileName || '',
                sheetName: task.source?.sheetName || '',
                rowNumber: task.originalRowNumber || task.rowIndex + 1,
                column: task.colIndex + 1,
                profile: task.profile?.name || getCompactModelLabel(task.profile),
                model: task.profile?.model || '',
                sourceText: task.text || '',
                referenceText: task.referenceText || '',
                translatedText: '',
                glossary: '',
                qaStatus: '报告缺失：该任务没有出现在导入报告中',
                completenessRisk: '报告缺失',
                actionSuggestion: '重新处理该行',
                error: '导入报告缺少该任务记录'
            }));
    }

    function initializeTranslateOutputFromImportedReport(tasks = [], targetLang = '', options = {}) {
        translateSources.forEach(source => {
            source.outputRows = (source.rows || []).map(row => Array.isArray(row) ? [...row] : []);
            source.outputHeader = source.outputRows[0] || [];
            source.outputColMap = new Map();
        });
        translatedDataLocal = sheetData ? sheetData.map(row => Array.isArray(row) ? [...row] : []) : [];
        translatedWorkbook = null;
        translationRunReport = {
            createdAt: new Date().toISOString(),
            sourceName: originalFileName,
            targetLang,
            totalTasks: tasks.length,
            successCount: 0,
            failCount: 0,
            entries: []
        };
        translationProgressTasks = new Map();
        failedTranslationTasks = [];
        const restored = buildImportedTranslationRestoreEntries(tasks, targetLang, options);
        if (restored.entries.length) {
            restoreCompletedTranslationTasks(tasks, restored.entries, targetLang, {
                trustSavedQa: restored.reviewedForCurrentContext
            });
        }
        return restored;
    }

    function setImportedRetryPreparationState(isPreparing, count = 0) {
        if (translateBtn) translateBtn.disabled = isPreparing;
        if (translateBtnLabel && isPreparing) translateBtnLabel.textContent = `正在准备 ${count} 条...`;
        if (translateRetrySuspiciousBtn) {
            translateRetrySuspiciousBtn.disabled = isPreparing;
            if (isPreparing) translateRetrySuspiciousBtn.textContent = `正在准备 ${count} 条...`;
        }
    }

    async function yieldTranslatePreparationPaint() {
        await new Promise(resolve => requestAnimationFrame(() => setTimeout(resolve, 0)));
    }

    async function retrySuspiciousImportedTranslations(previewOverride = null) {
        const state = importedTranslateProgressState;
        const retryPreview = previewOverride || getImportedIssueRetryPreview(state);
        if (!retryPreview.entries.length) {
            alert(retryPreview.custom
                ? '所选问题类型没有可重译的行。请换一个报告问题类型，或先点击“复查已完成译文”。'
                : '没有需要补译的可疑行。请先导入报告并点击“复查已完成译文”，或在“定向重译问题类型”里勾选要处理的问题。');
            return;
        }
        if (!sheetData || !translateSources.length) {
            alert('请先上传与报告对应的原文件，再补译报告问题行。');
            return;
        }
        if (selectedColumns.length === 0) {
            columnSelectSection.style.display = 'block';
            renderColumnList();
            columnSelectSection.scrollIntoView({ behavior: 'smooth', block: 'center' });
            alert('请先选择要翻译的原文列，工具需要用它定位报告问题行。');
            return;
        }
        const activeProfiles = getSelectedTranslateProfiles();
        if (!activeProfiles.length) {
            setStatus('error', '未选择可用补译通道', '请先勾选至少一个翻译模型通道。', revealApiConfigPanel, '去配置');
            return;
        }
        const targetLang = state.targetLang || targetLangSelect?.value || '';
        if (state.targetLang && targetLangSelect?.value && state.targetLang !== targetLangSelect.value) {
            const confirmed = confirm(`导入报告是 ${getTranslateLanguageName(state.targetLang)}，当前页面选择的是 ${getTranslateLanguageName(targetLangSelect.value)}。\n\n将切换到 ${getTranslateLanguageName(state.targetLang)} 后补译可疑行，是否继续？`);
            if (!confirmed) return;
            targetLangSelect.value = state.targetLang;
            selectedTranslateTargetLangs = new Set([state.targetLang]);
            renderTranslateTargetLanguageList();
        }
        const retryScope = retryPreview.custom
            ? `所选问题类型（${formatImportedIssueFilterSelection(retryPreview)}）`
            : '可疑行';
        setImportedRetryPreparationState(true, retryPreview.entries.length);
        setStatus('processing', `正在准备${retryScope}`, `正在建立源文件索引并定位 ${retryPreview.entries.length} 条报告问题，完成后会自动开始补译。`);
        await yieldTranslatePreparationPaint();

        let retryTasks = [];
        try {
            const allTasks = collectTranslationTasks(activeProfiles, { deferGlossary: true });
            const taskLookup = buildTranslateImportTaskLookup(allTasks);
            const usedTaskKeys = new Set();
            retryPreview.entries.forEach(entry => {
                const task = findImportedTranslationTaskMatch(entry, taskLookup.taskByKey, taskLookup.fallbackIndex);
                if (!task || usedTaskKeys.has(task.taskKey)) return;
                retryTasks.push(task);
                usedTaskKeys.add(task.taskKey);
            });

            if (!retryTasks.length) {
                setStatus('error', '未定位到报告问题行', '请确认当前上传文件、工作表、所选列与导入报告来自同一次翻译。');
                return;
            }

            initializeTranslateOutputFromImportedReport(allTasks, targetLang, { taskLookup });
            failedTranslationTasks = retryTasks;
            updateTranslationRunActions();
        } catch (error) {
            recordClientError('prepare-imported-translation-retry', error);
            setStatus('error', '准备补译失败', error?.message || '建立任务索引时发生异常');
            return;
        } finally {
            setImportedRetryPreparationState(false);
            updateTranslateProgressImportStatus();
            updateTranslationRunActions();
        }

        setStatus('processing', `已准备${retryScope}补译`, `定位到 ${retryTasks.length}/${retryPreview.entries.length} 条报告问题行，将复用其余成功译文。`);
        await retryFailedTranslations({ skipConfirm: true, deferAutoQaRepair: true });
    }

    async function handleTranslatePrimaryAction() {
        const retryPreview = getImportedIssueRetryPreview(importedTranslateProgressState);
        if (retryPreview.custom) {
            await retrySuspiciousImportedTranslations(retryPreview);
            return;
        }
        await startTranslate();
    }

    function appendTranslationQaIssue(qaStatus, issue) {
        const text = String(qaStatus || '').trim();
        if (!issue) return text || '通过';
        if (!text || text === '通过') return `需确认：${issue}`;
        if (text.includes(issue)) return text;
        return `${text}；${issue}`;
    }

    function getTranslationQaIssueList(qaStatus = '') {
        return String(qaStatus || '')
            .replace(/^需确认[:：]\s*/, '')
            .split(/[；;]/)
            .map(item => item.trim())
            .filter(Boolean);
    }

    function hasBlockingCompactQa(qaStatus = '') {
        if (isTranslationQaPassed(qaStatus)) return false;
        const issues = getTranslationQaIssueList(qaStatus);
        if (!issues.length) return false;
        return issues.some(issue => !/译文长度超出建议/.test(issue));
    }

    function upsertTranslationRunReportEntry(task, translated, qaStatus = '', options = {}) {
        translationRunReport = translationRunReport || {
            createdAt: new Date().toISOString(),
            sourceName: originalFileName,
            targetLang: targetLangSelect?.value || '',
            totalTasks: 0,
            successCount: 0,
            failCount: 0,
            entries: []
        };
        const reportEntry = buildTranslationReportEntry(task, translated, qaStatus);
        const entries = translationRunReport.entries || [];
        const existingIndex = entries.findIndex(entry =>
            entry.taskKey === task.taskKey ||
            importedEntryMatchesTask(entry, task)
        );
        const existingEntry = existingIndex >= 0 ? entries[existingIndex] : null;
        if (options.preserveResolution && existingEntry) {
            const decisionPolicy = globalThis.NexusTranslationDeliveryPolicy;
            const userDecision = decisionPolicy?.normalizeDecision
                ? decisionPolicy.normalizeDecision(existingEntry.userDecision)
                : (existingEntry.userDecision || '');
            const currentKind = classifyTranslationReportEntry(reportEntry);
            const manualResolutionValid = decisionPolicy?.isManualResolutionValid
                ? decisionPolicy.isManualResolutionValid(
                    userDecision,
                    currentKind,
                    isTranslationQaPassed(reportEntry.qaStatus)
                )
                : (
                    (userDecision === 'accept_current' && ['success', 'soft', 'length'].includes(currentKind)) ||
                    (userDecision === 'use_revision' && isTranslationQaPassed(reportEntry.qaStatus))
                );
            Object.assign(reportEntry, {
                userDecision,
                revisedText: existingEntry.revisedText || '',
                decisionNote: existingEntry.decisionNote || '',
                manualResolutionValid,
                revisionApplied: userDecision === 'use_revision' && Boolean(existingEntry.revisionApplied)
            });
            if (userDecision === 'must_retry') {
                reportEntry.status = 'qa_failed';
                reportEntry.qaStatus = appendTranslationQaIssue(reportEntry.qaStatus, '用户要求重新翻译');
                reportEntry.completenessRisk = '用户要求重新翻译';
                reportEntry.actionSuggestion = '阻断交付：重新翻译该行';
                reportEntry.error = reportEntry.qaStatus;
            } else if (manualResolutionValid) {
                reportEntry.status = 'success';
            }
        }
        if (existingIndex >= 0) entries[existingIndex] = reportEntry;
        else entries.push(reportEntry);
        translationRunReport.entries = entries;

        const compactEntry = compactTranslationProgressEntry(reportEntry);
        if (compactEntry) translationProgressTasks.set(task.taskKey, compactEntry);
        queueTranslationTaskProgress(reportEntry);
        return reportEntry;
    }

    function refreshTranslationRunCountsFromReport() {
        const counts = countTranslationProgressEntries([...translationProgressTasks.values()]);
        successCount = counts.successCount;
        failCount = counts.failCount;
        if (translationRunReport) {
            translationRunReport.successCount = counts.successCount;
            translationRunReport.failCount = counts.failCount;
        }
    }

    function restoreImportedReportEntriesToOutput(tasks = [], entries = [], targetLang = '') {
        if (!tasks.length || !entries.length) return { matched: 0, unmatched: 0 };
        const taskByKey = new Map(tasks.map(task => [task.taskKey, task]));
        const fallbackIndex = buildTranslateImportTaskIndex(tasks);
        const usedTaskKeys = new Set();
        let matched = 0;
        let unmatched = 0;

        entries.forEach(entry => {
            if (!entry?.translatedText || isTranslateFailureText(entry.translatedText)) return;
            const task = findImportedTranslationTaskMatch(entry, taskByKey, fallbackIndex) ||
                findTaskForImportedTranslationEntry(entry, tasks);
            if (!task || usedTaskKeys.has(task.taskKey)) {
                unmatched++;
                return;
            }
            usedTaskKeys.add(task.taskKey);
            const qaStatus = summarizeTranslationQa(task.text, entry.translatedText, task.glossaryTerms || [], targetLang, task);
            const restoredReportEntry = upsertTranslationRunReportEntry(task, entry.translatedText, qaStatus);
            const decisionPolicy = globalThis.NexusTranslationDeliveryPolicy;
            const userDecision = decisionPolicy?.normalizeDecision
                ? decisionPolicy.normalizeDecision(entry.userDecision)
                : (entry.userDecision || '');
            const currentKind = classifyTranslationReportEntry(restoredReportEntry);
            const manualResolutionValid = decisionPolicy?.isManualResolutionValid
                ? decisionPolicy.isManualResolutionValid(
                    userDecision,
                    currentKind,
                    isTranslationQaPassed(qaStatus)
                )
                : (
                    (userDecision === 'accept_current' && ['success', 'soft', 'length'].includes(currentKind)) ||
                    (userDecision === 'use_revision' && isTranslationQaPassed(qaStatus))
                );
            Object.assign(restoredReportEntry, {
                userDecision,
                revisedText: entry.revisedText || '',
                decisionNote: entry.decisionNote || '',
                manualResolutionValid,
                revisionApplied: userDecision === 'use_revision' && Boolean(entry.revisionApplied)
            });
            if (userDecision === 'must_retry') {
                restoredReportEntry.status = 'qa_failed';
                restoredReportEntry.qaStatus = appendTranslationQaIssue(restoredReportEntry.qaStatus, '用户要求重新翻译');
                restoredReportEntry.completenessRisk = '用户要求重新翻译';
                restoredReportEntry.actionSuggestion = '阻断交付：重新翻译该行';
                restoredReportEntry.error = restoredReportEntry.qaStatus;
            } else if (restoredReportEntry.manualResolutionValid) {
                restoredReportEntry.status = 'success';
            }
            writeTranslationResult(task, entry.translatedText, restoredReportEntry.qaStatus);
            const compactEntry = compactTranslationProgressEntry(restoredReportEntry);
            if (compactEntry) translationProgressTasks.set(task.taskKey, compactEntry);
            queueTranslationTaskProgress(restoredReportEntry);
            matched++;
        });

        refreshTranslationRunCountsFromReport();
        return { matched, unmatched };
    }

    function buildLongTranslationCompactJobs(entries = [], tasks = [], activeProfiles = [], targetLang = '') {
        const lengthEntries = getTranslationReportIssueGroups(entries).length;
        const jobs = [];
        const usedIdentity = new Set();
        lengthEntries.forEach(entry => {
            const matchedTask = findTaskForImportedTranslationEntry(entry, tasks);
            if (!matchedTask || !entry.translatedText || isTranslateFailureText(entry.translatedText)) return;
            const identity = [
                matchedTask.source?.id || matchedTask.source?.fileName || '',
                matchedTask.source?.sheetName || '',
                matchedTask.originalRowNumber || matchedTask.rowIndex + 1,
                matchedTask.colIndex + 1,
                matchedTask.text || ''
            ].join('\u001f');
            if (usedIdentity.has(identity)) return;
            usedIdentity.add(identity);
            const profile = activeProfiles[jobs.length % activeProfiles.length] || matchedTask.profile;
            const task = {
                ...matchedTask,
                profile,
                taskKey: buildTranslationTaskKey(
                    matchedTask.source,
                    matchedTask.rowIndex,
                    matchedTask.colIndex,
                    profile,
                    matchedTask.referenceColIndex,
                    targetLang
                ),
                glossaryTerms: getRelevantTranslateGlossaryTerms(
                    [matchedTask.text, matchedTask.referenceText],
                    getSelectedTranslateGlossaryTerms(),
                    targetLang,
                    24
                )
            };
            jobs.push({
                entry,
                task,
                currentTranslation: entry.translatedText
            });
        });
        return jobs;
    }

    async function compactLongImportedTranslations() {
        if (activeTranslateRunId) {
            setStatus('warning', '当前已有翻译任务运行中', '请等待当前任务结束后再精简超长译文。');
            return;
        }
        const entries = importedTranslateProgressState?.entries?.length
            ? importedTranslateProgressState.entries
            : (translationRunReport?.entries || []);
        if (!entries.length) {
            alert('请先导入 translation_report.xlsx，或在当前页面生成翻译报告后再精简超长译文。');
            return;
        }
        if (!sheetData || !translateSources.length) {
            alert('请先上传与报告对应的原文件，工具需要用原文件定位并输出新版译文。');
            return;
        }
        if (selectedColumns.length === 0) {
            columnSelectSection.style.display = 'block';
            renderColumnList();
            columnSelectSection.scrollIntoView({ behavior: 'smooth', block: 'center' });
            alert('请先选择要翻译的原文列，工具需要用它定位超长行。');
            return;
        }
        if (!currentProject) {
            alert('请先选择游戏项目，工具需要项目规则来判断精简边界。');
            return;
        }

        const stateTargetLang = importedTranslateProgressState?.targetLang || translationRunReport?.targetLang || '';
        const currentTargetLang = targetLangSelect?.value || '';
        const targetLang = stateTargetLang || currentTargetLang;
        if (!targetLang) {
            alert('请先选择目标语言，工具需要知道按哪种语言规则精简。');
            return;
        }
        if (targetLang === 'zh-TW') {
            setStatus('warning', '繁中不做超长精简', '繁中只做完整繁简转换和漏译检查，不会为了长度删除语义。');
            return;
        }
        if (stateTargetLang && currentTargetLang && stateTargetLang !== currentTargetLang) {
            const confirmed = confirm(`导入报告是 ${getTranslateLanguageName(stateTargetLang)}，当前页面选择的是 ${getTranslateLanguageName(currentTargetLang)}。\n\n将切换到 ${getTranslateLanguageName(stateTargetLang)} 后精简超长译文，是否继续？`);
            if (!confirmed) return;
            if (targetLangSelect) targetLangSelect.value = stateTargetLang;
            selectedTranslateTargetLangs = new Set([stateTargetLang]);
            renderTranslateTargetLanguageList();
        }

        const activeProfiles = getSelectedTranslateProfiles();
        if (!activeProfiles.length) {
            setStatus('error', '未选择可用精简通道', '请先勾选至少一个翻译模型通道。', revealApiConfigPanel, '去配置');
            return;
        }
        const allTasks = collectTranslationTasks(activeProfiles);
        const compactJobs = buildLongTranslationCompactJobs(entries, allTasks, activeProfiles, targetLang);
        if (!compactJobs.length) {
            setStatus('success', '没有可精简的超长行', '当前报告没有可定位的“译文长度超出建议”行。旧报告可先点“复查已完成译文”按新版规则重新检测。');
            return;
        }

        const confirmed = confirm(`将只对 ${compactJobs.length} 条超长译文做二次精简。\n\n成功译文会先恢复到输出文件；精简失败、疑似漏译或变短后丢意思时，会保留原译文并在报告标记“需确认：长度超出”。\n\n确定开始吗？`);
        if (!confirmed) return;

        const runId = `compact_${Date.now().toString(36)}`;
        const runController = new AbortController();
        currentTranslateAbortController = runController;
        activeTranslateRunId = runId;
        isTranslationCancelled = false;
        isPaused = false;

        initializeTranslateOutputFromImportedReport(allTasks, targetLang);
        setExpectedTranslationTasks(allTasks);
        const restored = restoreImportedReportEntriesToOutput(allTasks, entries, targetLang);
        if (translationRunReport) {
            translationRunReport.targetLang = targetLang;
            translationRunReport.totalTasks = allTasks.length;
        }

        progressSection.style.display = 'block';
        downloadSection.style.display = 'none';
        pauseBtn.style.display = 'inline-flex';
        resumeBtn.style.display = 'none';
        downloadProgressBtn.style.display = 'none';
        initTranslateChannelProgress(compactJobs.map(job => job.task));
        startTranslateElapsedTimer();
        translateRunSummaryState = {
            completed: 0,
            total: compactJobs.length,
            phase: `${getTranslateLanguageName(targetLang)}超长精简中`
        };
        updateTranslateRunSummary(0, compactJobs.length, translateRunSummaryState.phase);
        setStatus(
            'processing',
            '正在精简超长译文',
            `已恢复 ${restored.matched} 条报告译文，只处理 ${compactJobs.length} 条超长行；其余成功项不会重跑。`
        );

        let completed = 0;
        let accepted = 0;
        let keptOriginal = 0;
        let nextIndex = 0;
        const sourceLang = sourceLangSelect?.value || 'zh';
        const rules = currentProject?.rules || '';
        const compactProfileCapacity = activeProfiles.reduce((sum, profile) => {
            const profileLimit = getProfileConcurrency(profile);
            return sum + (Number.isFinite(profileLimit) ? profileLimit : 1);
        }, 0);
        const pageConcurrencyLimit = getTranslatePageConcurrencyLimit();
        const compactConcurrencyLimit = pageConcurrencyLimit || compactProfileCapacity || 1;
        const workerCount = Math.max(1, Math.min(
            compactJobs.length,
            compactProfileCapacity || 1,
            compactConcurrencyLimit,
            3
        ));

        async function runCompactWorker() {
            while (nextIndex < compactJobs.length) {
                const job = compactJobs[nextIndex++];
                throwIfTranslationCancelled(runId);
                while (isPaused && !isTranslationCancelled) {
                    await waitForResume();
                    throwIfTranslationCancelled(runId);
                }

                const { task, entry, currentTranslation } = job;
                updateTranslateChannelProgress(task.profile, {
                    status: 'running',
                    message: `超长精简中，并发 ${workerCount}`
                });
                const lengthQa = entry.qaStatus || getTranslationLengthIssue(task.text, currentTranslation, targetLang, task);
                let repaired = currentTranslation;
                let finalText = currentTranslation;
                let finalQa = appendTranslationQaIssue(lengthQa, '长度超出，二次精简未采纳，保留原译文');
                let status = 'qa_failed';

                try {
                    repaired = await repairTranslationWithRetry(
                        task,
                        currentTranslation,
                        lengthQa,
                        sourceLang,
                        targetLang,
                        rules,
                        task.profile,
                        runController.signal,
                        2
                    );
                    repaired = applyLocalTranslationFixes(task.text, repaired, targetLang);
                    const currentLength = getVisibleTextForLength(currentTranslation).length;
                    const repairedLength = getVisibleTextForLength(repaired).length;
                    const repairedQa = translatePostCheckInput?.checked
                        ? summarizeTranslationQa(task.text, repaired, task.glossaryTerms || [], targetLang, task)
                        : getTranslationLengthIssue(task.text, repaired, targetLang, task) || '通过';

                    if (
                        repaired &&
                        !isTranslateFailureText(repaired) &&
                        repairedLength > 0 &&
                        repairedLength < currentLength &&
                        !hasBlockingCompactQa(repairedQa)
                    ) {
                        finalText = repaired;
                        finalQa = repairedQa;
                        status = getTranslationReportStatus(finalText, finalQa);
                        accepted++;
                    } else {
                        keptOriginal++;
                    }
                } catch (error) {
                    if (error.name === 'AbortError' || error.message === 'TRANSLATION_CANCELLED') throw error;
                    keptOriginal++;
                    finalQa = appendTranslationQaIssue(finalQa, `精简失败：${summarizeTranslateError(error)}`);
                }

                writeTranslationResult(task, finalText, finalQa);
                upsertTranslationRunReportEntry(task, finalText, finalQa);
                recordTranslateChannelResult(task, status);
                completed++;
                const percent = Math.round((completed / compactJobs.length) * 100);
                updateTranslateProgress(completed, compactJobs.length, percent);
                updateTranslateRunSummary(completed, compactJobs.length, `${getTranslateLanguageName(targetLang)}超长精简中`);
                if (completed % TRANSLATION_PROGRESS_SAVE_INTERVAL === 0) {
                    await saveCurrentTranslationProgress(task?.rowIndex || 1);
                }
                if (shouldRenderTranslationPreview(status, completed)) {
                    const translationList = document.getElementById('translationList');
                    addTranslationItem(translationList, task.text, finalText, task.rowIndex, task.colIndex, task.profile, targetLang);
                }
            }
        }

        try {
            await Promise.all(Array.from({ length: workerCount }, () => runCompactWorker()));
            refreshTranslationRunCountsFromReport();
            ensureTranslationReportCoversExpectedTasks();
            await flushTranslationTaskProgress();
            await saveCurrentTranslationProgress(1);
            translatedWorkbook = buildTranslationWorkbook();
            translatedData = translatedDataLocal;
            progressSection.style.display = 'none';
            downloadSection.style.display = 'block';
            updateTranslationRunActions();

            const deliveryGate = getTranslationDeliveryGate();
            let autoSaveMessage = '';
            try {
                const savedPaths = await autoSaveTranslationOutputs();
                autoSaveMessage = deliveryGate.ready
                    ? (savedPaths.length ? `；已自动保存：${savedPaths.join('；')}` : '')
                    : `；仍有 ${deliveryGate.blockingCount} 条阻断问题，未生成交付版${savedPaths.length ? `；问题报告已保存：${savedPaths.join('；')}` : ''}`;
            } catch (saveError) {
                console.warn('超长精简结果自动保存失败:', saveError);
                autoSaveMessage = deliveryGate.ready
                    ? '；自动保存失败，请点击下载按钮手动保存'
                    : `；仍有 ${deliveryGate.blockingCount} 条阻断问题，未生成交付版；问题报告自动保存失败`;
            }
            setTranslateDownloadLanguageSummary(
                deliveryGate.ready
                    ? `${getTranslateLanguageName(targetLang)}超长精简完成：采纳 ${accepted} 条，保留原译文 ${keptOriginal} 条；交付版可用。`
                    : `${getTranslateLanguageName(targetLang)}超长精简完成，但仍有 ${deliveryGate.blockingCount} 条阻断问题，未生成交付版。`
            );
            setStatus(
                keptOriginal > 0 || !deliveryGate.ready ? 'warning' : 'success',
                deliveryGate.ready ? '超长译文精简完成' : '精简完成，仍有阻断问题',
                `已处理 ${completed}/${compactJobs.length} 条；采纳 ${accepted} 条，保留原译文 ${keptOriginal} 条。${autoSaveMessage}`
            );
            if (keptOriginal > 0 || !deliveryGate.ready) {
                finishInspectorTaskTimer('warning', deliveryGate.ready ? '超长译文精简完成，有内容待确认' : '精简完成，仍有阻断问题');
            }
        } catch (error) {
            if (error.name === 'AbortError' || error.message === 'TRANSLATION_CANCELLED') {
                setStatus('warning', '超长精简已取消', '已保留当前已处理的译文，可下载当前进度或重新导入报告继续。');
                finishInspectorTaskTimer('warning', '超长精简已取消');
            } else {
                recordClientError('compact-long-translation', error);
                setStatus('error', '超长精简失败', error?.message || '未知错误');
            }
        } finally {
            if (currentTranslateAbortController === runController) currentTranslateAbortController = null;
            if (activeTranslateRunId === runId) activeTranslateRunId = null;
            stopTranslateElapsedTimer();
            isPaused = false;
            pauseBtn.style.display = 'inline-flex';
            resumeBtn.style.display = 'none';
            downloadProgressBtn.style.display = 'none';
            updateTranslationRunActions();
            updateTranslateInspectorRuntime();
        }
    }

    function buildTranslationTaskKey(source, rowIndex, colIndex, profile, referenceColIndex = null, targetLangOverride = null) {
        const keyTargetLang = targetLangOverride || document.getElementById('targetLang')?.value || '';
        return [
            source?.fileName || '',
            source?.sheetName || '',
            keyTargetLang,
            rowIndex,
            colIndex,
            referenceColIndex ?? '',
            getTranslateChannelKey(profile)
        ].join('|');
    }

    function collectTranslationTasks(activeProfiles, options = {}) {
        const tasks = [];
        let filteredEmpty = 0;
        let filteredSpecial = 0;
        const deferGlossary = Boolean(options.deferGlossary);
        const glossaryTerms = deferGlossary ? [] : getSelectedTranslateGlossaryTerms();
        const targetLang = document.getElementById('targetLang').value;

        for (let i = 1; i < (sheetData?.length || 0); i++) {
            const row = sheetData[i];
            if (!row) continue;
            const source = findTranslateSourceForRow(i);
            if (!source) continue;

            for (const originalColIndex of selectedColumns) {
                const cell = row[originalColIndex];
                if (cell === undefined || cell === null) {
                    filteredEmpty++;
                    continue;
                }
                const cellText = String(cell).trim();
                if (!cellText) {
                    filteredEmpty++;
                    continue;
                }

                activeProfiles.forEach(profile => {
                    const referenceText = getTranslateReferenceText(row, originalColIndex);
                    const glossary = deferGlossary
                        ? []
                        : getRelevantTranslateGlossaryTerms([cellText, referenceText], glossaryTerms, targetLang, 24);
                    const referenceColIndex = referenceText ? referenceColumn : null;
                    const passthrough = isSpecialCode(cellText, targetLang);
                    if (passthrough) filteredSpecial++;
                    tasks.push({
                        rowIndex: i,
                        originalRowIndex: source.rowMap?.get(i) ?? i,
                        originalRowNumber: getTranslateOriginalRowNumber(i),
                        colIndex: originalColIndex,
                        sourceColumnName: getTranslateColumnName(originalColIndex),
                        text: cellText,
                        referenceText,
                        referenceColIndex,
                        referenceColumnName: Number.isInteger(referenceColIndex) ? getTranslateColumnName(referenceColIndex) : '',
                        source,
                        profile,
                        passthrough,
                        glossaryTerms: glossary,
                        taskKey: buildTranslationTaskKey(source, i, originalColIndex, profile, referenceColIndex, targetLang)
                    });
                });
            }
        }

        console.log(`收集到 ${tasks.length} 个翻译任务 (过滤空值: ${filteredEmpty}, 过滤特殊代码: ${filteredSpecial})`);
        return tasks;
    }

    function writeTranslationResult(task, translated, qaStatus = '') {
        const outputRows = getTranslateSourceOutput(task.source);
        const cols = ensureTranslateOutputColumn(task);
        const outputRowIndex = task.originalRowIndex ?? task.rowIndex;
        const row = outputRows[outputRowIndex] || [];
        const normalizedTranslated = normalizeTranslateResultText(translated, task.text);
        row[cols.translationCol] = normalizedTranslated;
        if (cols.qaCol >= 0) {
            row[cols.qaCol] = getTranslationQaDisplayText({
                status: getTranslationReportStatus(normalizedTranslated, qaStatus),
                translatedText: normalizedTranslated,
                qaStatus
            });
        }
        outputRows[outputRowIndex] = row;
        translatedWorkbook = null;
    }

    function buildTranslationWorkbook() {
        const selectedSources = getSelectedTranslateSources();
        if (!selectedSources.length) return null;

        const workbook = XLSX.utils.book_new();
        selectedSources.forEach((source, index) => {
            const rows = getTranslateSourceOutput(source);
            const baseName = source.sheetName && source.sheetName !== 'CSV'
                ? source.sheetName
                : source.fileName.replace(/\.(csv|xlsx|xls)$/i, '');
            const safeName = String(baseName || `Sheet${index + 1}`).replace(/[\\/?*[\]:]/g, '_').slice(0, 31) || `Sheet${index + 1}`;
            XLSX.utils.book_append_sheet(workbook, XLSX.utils.aoa_to_sheet(rows), safeName);
        });

        if (translationRunReport?.entries?.length) {
            XLSX.utils.book_append_sheet(workbook, XLSX.utils.aoa_to_sheet(buildTranslationReportRows()), '翻译报告');
        }

        return workbook;
    }

    function buildTranslationReportRows() {
        ensureTranslationReportCoversExpectedTasks();
        const targetLang = translationRunReport?.targetLang || targetLangSelect?.value || '';
        const rows = [
            ['翻译报告元数据'],
            ['目标语言代码', targetLang],
            ['目标语言', getTranslateLanguageName(targetLang) || targetLang],
            ['生成时间', new Date().toISOString()],
            [],
            [
            '任务Key',
            '处理状态',
            '机器状态',
            '来源文件',
            '工作表',
            '原始行号',
            '列',
            '通道',
            '模型',
            '原文',
            '参考译文',
            '译文',
            '命中术语',
            '译后检测',
            '完整性风险',
            '处理建议',
            '错误',
            '处理决定（可选）',
            '修订译文（可选）',
            '处理备注（可选）'
            ]
        ];

        (translationRunReport?.entries || []).forEach(entry => {
            rows.push([
                entry.taskKey || '',
                getTranslationReportDisplayStatus(entry),
                entry.status || '',
                entry.sourceFile || '',
                entry.sheetName || '',
                entry.rowNumber || '',
                entry.column || '',
                entry.profile || '',
                entry.model || '',
                entry.sourceText || '',
                entry.referenceText || '',
                entry.translatedText || '',
                entry.glossary || '',
                getTranslationQaDisplayText(entry),
                entry.completenessRisk || getTranslationCompletenessRiskLabel(entry.qaStatus || ''),
                entry.actionSuggestion || getTranslationActionSuggestion(entry.status || '', entry.qaStatus || ''),
                entry.error || '',
                globalThis.NexusTranslationDeliveryPolicy?.getDecisionLabel
                    ? globalThis.NexusTranslationDeliveryPolicy.getDecisionLabel(entry.userDecision)
                    : (entry.userDecision || ''),
                entry.revisedText || '',
                entry.decisionNote || ''
            ]);
        });

        const retryableEntries = [];
        const seenRetryableEntries = new Set();
        getDefaultRetryableTranslationReportEntries().forEach(entry => {
            const identity = getTranslationIssueIdentity(entry);
            if (seenRetryableEntries.has(identity)) return;
            seenRetryableEntries.add(identity);
            retryableEntries.push(entry);
        });

        if (retryableEntries.length) {
            rows.push([]);
            rows.push([
                '需重新处理任务',
                `共 ${retryableEntries.length} 条；可能是翻译失败、未返回译文，或已有译文但硬质检未通过`
            ]);
            rows.push([
                '任务Key',
                '处理状态',
                '机器状态',
                '来源文件',
                '工作表',
                '原始行号',
                '列',
                '通道',
                '模型',
                '原文',
                '参考译文',
                '当前译文',
                '质检原因',
                '处理建议',
                '处理决定（可选）',
                '修订译文（可选）',
                '处理备注（可选）'
            ]);
            retryableEntries.forEach(entry => {
                const qaReason =
                    (!isTranslationQaPassed(entry.qaStatus) ? getTranslationQaDisplayText(entry) : '') ||
                    entry.error ||
                    entry.completenessRisk ||
                    '';
                rows.push([
                    entry.taskKey || '',
                    getTranslationReportDisplayStatus(entry),
                    entry.status || '',
                    entry.sourceFile || '',
                    entry.sheetName || '',
                    entry.rowNumber || '',
                    entry.column || '',
                    entry.profile || '',
                    entry.model || '',
                    entry.sourceText || '',
                    entry.referenceText || '',
                    entry.translatedText || '',
                    qaReason,
                    entry.actionSuggestion || getTranslationActionSuggestion(entry.status || '', entry.qaStatus || ''),
                    globalThis.NexusTranslationDeliveryPolicy?.getDecisionLabel
                        ? globalThis.NexusTranslationDeliveryPolicy.getDecisionLabel(entry.userDecision)
                        : (entry.userDecision || ''),
                    entry.revisedText || '',
                    entry.decisionNote || ''
                ]);
            });
        }

        return rows;
    }

    function sanitizeTranslationFileStem(value) {
        return String(value || 'translation')
            .replace(/\.(csv|xlsx|xls)$/i, '')
            .replace(/[\\/:*?"<>|]+/g, '_')
            .replace(/\s+/g, '_')
            .replace(/_+/g, '_')
            .replace(/^_+|_+$/g, '')
            .slice(0, 120) || 'translation';
    }

    function getTranslationOutputFileName(kind) {
        const base = sanitizeTranslationFileStem(originalFileName);
        const languageSuffix = activeTranslationOutputSuffix ||
            translationRunReport?.targetLang ||
            targetLangSelect?.value ||
            '';
        const suffix = languageSuffix ? `_${sanitizeTranslationFileStem(languageSuffix)}` : '';
        return `${base}${suffix}_${kind}.xlsx`;
    }

    async function downloadTranslationReport() {
        if (!translationRunReport) {
            alert('暂无翻译报告');
            return;
        }
        const workbook = buildTranslationReportWorkbook();
        const fileName = getTranslationOutputFileName('translation_report');
        try {
            setTranslateDownloadLanguageSummary('正在保存翻译报告到下载目录...');
            const savedPath = await saveWorkbookFile(workbook, fileName, {
                onProgress: (_phase, message) => setTranslateDownloadLanguageSummary(message)
            });
            setTranslateDownloadLanguageSummary(`翻译报告已保存：${savedPath}`);
            setStatus('success', '翻译报告已保存', savedPath);
        } catch (error) {
            console.error('保存翻译报告失败:', error);
            recordClientError('translation-report-download', error);
            setTranslateDownloadLanguageSummary('翻译报告保存失败，请稍后重试。');
            setStatus('error', '翻译报告保存失败', error.message || String(error));
        }
    }

    function buildTranslationReportWorkbook() {
        const workbook = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(workbook, XLSX.utils.aoa_to_sheet(buildTranslationReportRows()), '翻译报告');
        XLSX.utils.book_append_sheet(workbook, XLSX.utils.aoa_to_sheet([
            ['怎么处理', '填写方式', '重新导入后的结果'],
            ['在哪里填写', '顶部主表或下方“需重新处理任务”清单都可以', '工具会按任务合并读取，不会丢失处理决定'],
            ['让工具自动修复', '在“处理决定（可选）”填写：必须重译', '该行进入一键修复队列'],
            ['使用人工修改', '填写“修订译文（可选）”，并在处理决定填写：使用修订译文', '先按当前规则复检；通过后直接写入结果'],
            ['确认专名可保留', '仅对软性需确认填写：接受现译', '记录确认并复用；混入中文、明确英文残留、缺失等硬错误不能这样放行'],
            ['补充上下文', '可在“处理备注（可选）”填写原因', '随报告保留，方便后续审计'],
            [],
            ['重要', '阻断问题未清零时，工具不会自动生成正式交付版。', '如确需查看或人工修改，可在工具中主动导出 *_translated_unverified.xlsx；该文件不是交付版。']
        ]), '处理说明');
        return workbook;
    }

    async function autoSaveTranslationOutputs() {
        const savedPaths = [];
        ensureTranslationReportCoversExpectedTasks();
        const deliveryGate = getTranslationDeliveryGate();
        const autoSaveKinds = globalThis.NexusTranslationDeliveryPolicy?.getAutoSaveKinds
            ? globalThis.NexusTranslationDeliveryPolicy.getAutoSaveKinds(deliveryGate)
            : (deliveryGate.ready ? ['translated', 'report'] : ['report']);
        if (autoSaveKinds.includes('translated')) {
            const workbook = translatedWorkbook || buildTranslationWorkbook();
            if (workbook) {
                translatedWorkbook = workbook;
                savedPaths.push(await saveWorkbookFile(workbook, getTranslationOutputFileName('translated')));
                translatedWorkbook = null;
                await waitForBrowserFrame();
            }
        }
        if (translationRunReport && autoSaveKinds.includes('report')) {
            const reportWorkbook = buildTranslationReportWorkbook();
            savedPaths.push(await saveWorkbookFile(reportWorkbook, getTranslationOutputFileName('translation_report')));
            await waitForBrowserFrame();
        }
        const resultPaths = savedPaths.filter(Boolean);
        resultPaths.deliveryGate = deliveryGate;
        return resultPaths;
    }

    function buildFailedTranslationRetryPlan(activeProfiles, sourceTasks = failedTranslationTasks) {
        return [...sourceTasks].map((task, index) => {
            const originalProfile = task.profile;
            const profile = activeProfiles[index % Math.max(1, activeProfiles.length)];
            return {
                task,
                originalProfile,
                profile,
                remapped: Boolean(originalProfile && profile && getTranslateChannelKey(originalProfile) !== getTranslateChannelKey(profile))
            };
        });
    }

    function getRetrySubmitModeLabel(profile) {
        const batchSize = getTranslationBatchSize(profile);
        if (batchSize <= 1) return `单条提交，并发 ${getProfileConcurrency(profile)}`;
        return `批量提交，每批最多 ${batchSize} 条，并发 ${getProfileConcurrency(profile)}`;
    }

    function summarizeRetryPlan(retryPlan) {
        const grouped = new Map();
        retryPlan.forEach(item => {
            const fromLabel = getApiProfileLabel(item.originalProfile);
            const toLabel = getApiProfileLabel(item.profile);
            const key = `${fromLabel}=>${toLabel}`;
            const previous = grouped.get(key) || {
                fromLabel,
                toLabel,
                profile: item.profile,
                count: 0,
                remapped: false
            };
            previous.count += 1;
            previous.remapped = previous.remapped || item.remapped;
            grouped.set(key, previous);
        });

        return [...grouped.values()].map(group => {
            const relation = group.remapped ? `${group.fromLabel} → ${group.toLabel}` : group.toLabel;
            const reason = group.remapped ? '（按当前勾选通道接管）' : '（当前勾选通道）';
            return `${relation}：${group.count} 条，${getRetrySubmitModeLabel(group.profile)}${reason}`;
        }).join('\n');
    }

    function rebuildFailedTranslationTasksFromReport(activeProfiles) {
        if (failedTranslationTasks.length > 0) return [...failedTranslationTasks];

        const failedEntries = getDefaultRetryableTranslationReportEntries();
        const issueSummary = getTranslationReportIssueSummary();
        if (failedEntries.length === 0) return [];

        if (!sheetData || !translateSources.length || selectedColumns.length === 0) {
            setStatus(
                'warning',
                '无法恢复待处理任务',
                '当前报告里有可自动处理项，但页面缺少原文件或原文列选择。请重新上传同一份原文件并选择原文列，再开始重译。'
            );
            return [];
        }

        const allTasks = collectTranslationTasks(activeProfiles, { deferGlossary: true });
        const restoredTasks = [];
        const usedTaskKeys = new Set();

        failedEntries.forEach(entry => {
            const task = findTaskForImportedTranslationEntry(entry, allTasks);
            if (!task || usedTaskKeys.has(task.taskKey)) return;
            restoredTasks.push({
                ...task,
                retryOfTaskKey: entry.taskKey || task.taskKey
            });
            usedTaskKeys.add(task.taskKey);
        });

        if (restoredTasks.length > 0) {
            failedTranslationTasks = restoredTasks;
            if (restoredTasks.length < failedEntries.length) {
                setStatus(
                    'warning',
                    '已恢复部分待处理任务',
                    `报告中有 ${formatTranslationReportIssueSummary(issueSummary)}；共有 ${failedEntries.length} 个可自动处理项，当前文件和列可定位 ${restoredTasks.length} 个。未定位项请确认原文件、工作表、原文列和目标语言没有变化。`
                );
            } else {
                setStatus('processing', '已准备硬问题重译任务', `已从翻译报告恢复 ${restoredTasks.length} 个翻译失败、结果缺失或硬质检问题；软性需确认不会自动重译。`);
            }
            updateTranslationRunActions();
        }

        return restoredTasks;
    }

    async function retryFailedTranslations(options = {}) {
        const activeProfiles = getSelectedTranslateProfiles();
        if (!activeProfiles.length) {
            setStatus(
                'error',
                '未选择可用重译通道',
                '重译会使用当前勾选的翻译模型通道。请先勾选至少一个可用通道后再处理硬问题。',
                revealApiConfigPanel,
                '去配置'
            );
            return;
        }

        const retryTasks = rebuildFailedTranslationTasksFromReport(activeProfiles);
        if (!retryTasks.length) {
            const reportFailureCount = getTranslationReportFailureEntries().length;
            const issueSummary = getTranslationReportIssueSummary();
            const reportRepairableCount = issueSummary.retryable;
            setStatus(
                reportFailureCount > 0 && reportRepairableCount === 0 ? 'success' : 'warning',
                reportFailureCount > 0 && reportRepairableCount === 0 ? '没有需要自动重译的硬问题' : '没有可重新处理的硬问题',
                reportFailureCount > 0 && reportRepairableCount === 0
                    ? `报告里还有 ${formatTranslationReportIssueSummary(issueSummary)}，但没有可自动处理项。超长行可点“精简超长译文”，其他软性问题建议下载报告人工确认。`
                    : (translationRunReport
                        ? '当前翻译报告里没有可定位的硬问题。可以先下载报告查看问题行，或重新上传同一份原文件后再试。'
                        : '当前没有翻译报告或待处理任务记录。')
            );
            return;
        }

        const retryPlan = buildFailedTranslationRetryPlan(activeProfiles, retryTasks);
        if (!options.skipConfirm) {
            const confirmed = confirm(`将重新翻译 ${retryPlan.length} 个硬问题，包括翻译失败、结果缺失和硬质检未通过。\n\n处理规则：第一阶段统一批量重译并做本地 QA，不会边翻译边逐条调用 AI 修复；批量后最多选取 ${TRANSLATION_RETRY_DEEP_REPAIR_LIMIT} 个残余阻断项进入有界深度修复，超出的条目会保留并在下一轮轮转处理。已有译文的硬问题最多定向修复一次；缺失项最多补译一次，必要时再定向修复一次。\n\n使用文本翻译里当前勾选的模型通道；勾选多个通道时会轮询分配，不再强制沿用原通道。软性需确认和超长行不会在这里自动重译；超长行请使用“精简超长译文”。\n\n${summarizeRetryPlan(retryPlan)}\n\n确定开始重译吗？`);
            if (!confirmed) return;
        }

        const retryTargetLang = document.getElementById('targetLang').value;
        const retryGlossaryTerms = getSelectedTranslateGlossaryTerms();
        pendingRetryTranslationTasks = retryPlan.map(({ task, profile }) => {
            return {
                ...task,
                profile,
                retryOfTaskKey: task.retryOfTaskKey || task.taskKey,
                taskKey: buildTranslationTaskKey(task.source, task.rowIndex, task.colIndex, profile, task.referenceColIndex, retryTargetLang),
                glossaryTerms: getRelevantTranslateGlossaryTerms(
                    [task.text, task.referenceText],
                    retryGlossaryTerms,
                    retryTargetLang,
                    24,
                    { normalized: true }
                )
            };
        });
        failedTranslationTasks = [];
        updateTranslationRunActions();
        try {
            const result = await startTranslate({
                deferAutoQaRepair: shouldDeferRetryQaRepair(options),
                twoStageRetry: options.twoStageRetry !== false,
                glossaryTermsSnapshot: retryGlossaryTerms,
                suppressAutoSave: Boolean(options.suppressAutoSave)
            });
            return result;
        } finally {
            pendingRetryTranslationTasks = null;
            updateTranslationRunActions();
        }
    }

    function getTranslateBatchTargetLangs() {
        const targets = getSelectedTranslateTargetLangs();
        if (targets.length > 0) return targets;
        return targetLangSelect?.value ? [targetLangSelect.value] : [];
    }

    function getMultiTargetOutputSuffix(targetLang) {
        return targetLang || 'target';
    }

    async function startMultiTargetTranslate(targetLangs) {
        if (isTranslateMultiTargetRunning) {
            setStatus('warning', '多语言翻译正在运行', '请等待当前队列完成，或点击“取消任务”停止。');
            return { status: 'running' };
        }
        if (!targetLangs.length) {
            alert('请至少选择一种目标语言');
            return { status: 'empty' };
        }

        const autoRetryText = isTranslateAutoRetryMultiTargetEnabled()
            ? '\n\n已开启“多语言自动重译硬问题”：每种语言完成后若有翻译失败、结果缺失或硬质检问题，会额外重译一次再进入下一语言。'
            : '';
        const confirmed = confirm(`将按顺序翻译 ${targetLangs.length} 种目标语言：${targetLangs.map(getTranslateLanguageName).join('、')}。\n\n每种语言都会保存独立报告；只有硬错误清零时才保存交付版译文，避免把有问题的文件误用于交付。${autoRetryText}\n\n是否开始？`);
        if (!confirmed) return { status: 'cancelled' };

        const originalTargetLang = targetLangSelect?.value || targetLangs[0];
        const savedSuffix = activeTranslationOutputSuffix;
        isTranslateMultiTargetRunning = true;
        let completedTargets = 0;
        let stopped = false;
        const retryTargets = [];
        updateTranslateLanguageRunState({
            targets: targetLangs,
            currentIndex: 0,
            completed: [],
            failed: [],
            status: 'queued'
        });
        setTranslateDownloadLanguageSummary(`多语言队列准备中：${targetLangs.map(getTranslateLanguageName).join('、')}`);

        try {
            for (let index = 0; index < targetLangs.length; index++) {
                const targetLang = targetLangs[index];
                if (isTranslationCancelled) {
                    stopped = true;
                    break;
                }
                if (targetLangSelect) targetLangSelect.value = targetLang;
                selectedTranslateTargetLangs = new Set(targetLangs);
                renderTranslateTargetLanguageList();
                clearTranslationProgress();
                activeTranslationOutputSuffix = getMultiTargetOutputSuffix(targetLang);
                updateTranslateLanguageRunState({
                    targets: targetLangs,
                    currentIndex: index,
                    status: 'running'
                });
                setTranslateDownloadLanguageSummary(`正在翻译 ${getTranslateLanguageName(targetLang)}（${index + 1}/${targetLangs.length}），复检通过后会自动保存交付版。`);
                setStatus(
                    'processing',
                    `多语言翻译 ${index + 1}/${targetLangs.length}`,
                    `正在处理 ${getTranslateLanguageName(targetLang)}。硬错误清零后保存交付版；否则只保存问题报告，再继续下一种语言。`
                );
                const result = await startTranslate({
                    skipMultiTarget: true,
                    outputSuffix: getMultiTargetOutputSuffix(targetLang),
                    multiTargetIndex: index,
                    multiTargetTotal: targetLangs.length
                });
                if (!['success', 'needs_action'].includes(result?.status) || isTranslationCancelled) {
                    stopped = true;
                    markTranslateLanguageFailed(targetLang);
                    break;
                }
                completedTargets++;
                let repairableCount = Number(result.repairableCount || 0);
                let failureCount = Number(result.failCount || result.failureCount || 0);
                if (repairableCount > 0 && isTranslateAutoRetryMultiTargetEnabled()) {
                    setTranslateDownloadLanguageSummary(`${getTranslateLanguageName(targetLang)}首次完成，有 ${repairableCount} 个可自动处理的硬问题，正在重译一次。`);
                    setStatus(
                        'processing',
                        `自动重译 ${getTranslateLanguageName(targetLang)} 的硬问题`,
                        `将只重新处理 ${repairableCount} 个翻译失败、结果缺失或硬质检问题，通过译文继续复用。`
                    );
                    const retryResult = await retryFailedTranslations({
                        skipConfirm: true,
                        deferAutoQaRepair: true,
                        twoStageRetry: true
                    });
                    if (['success', 'needs_action'].includes(retryResult?.status)) {
                        repairableCount = Number(retryResult.repairableCount || 0);
                        failureCount = Number(retryResult.failCount || retryResult.failureCount || failureCount);
                    } else {
                        repairableCount = Math.max(repairableCount, failedTranslationTasks.length || 0);
                    }
                }
                if (repairableCount > 0) {
                    retryTargets.push({ targetLang, repairableCount, failureCount });
                    markTranslateLanguageFailed(targetLang);
                    setTranslateDownloadLanguageSummary(`${getTranslateLanguageName(targetLang)}仍有 ${repairableCount} 个阻断问题，未生成交付版；问题报告已保存。多语言队列进度：${completedTargets}/${targetLangs.length}`);
                } else {
                    markTranslateLanguageCompleted(targetLang);
                    setTranslateDownloadLanguageSummary(`${getTranslateLanguageName(targetLang)}硬错误已清零，交付版和报告已保存。多语言队列进度：${completedTargets}/${targetLangs.length}`);
                }
            }
        } finally {
            isTranslateMultiTargetRunning = false;
            activeTranslationOutputSuffix = savedSuffix;
            if (targetLangSelect && originalTargetLang) targetLangSelect.value = originalTargetLang;
            renderTranslateTargetLanguageList();
        }

        if (!stopped && completedTargets === targetLangs.length) {
            clearTranslationProgress();
            updateTranslateLanguageRunState({
                currentIndex: -1,
                status: retryTargets.length ? 'needs_action' : 'success'
            });
            const retryText = retryTargets.length
                ? ` 其中 ${retryTargets.map(item => `${getTranslateLanguageName(item.targetLang)} ${item.repairableCount} 项`).join('、')} 仍阻断交付，只保存了问题报告。点击“导入报告继续处理”，逐个导入对应语言的 *_translation_report.xlsx 即可。`
                : '';
            setTranslateDownloadLanguageSummary(
                retryTargets.length
                    ? `多语言队列已处理完成：${targetLangs.map(getTranslateLanguageName).join('、')}。仅硬错误清零的语言生成了交付版。${retryText}`
                    : `多语言翻译已完成：${targetLangs.map(getTranslateLanguageName).join('、')}。每种语言已分别保存交付版和报告。`
            );
            setStatus(
                retryTargets.length ? 'warning' : 'success',
                retryTargets.length ? '多语言队列完成，有语言未生成交付版' : '多语言翻译完成',
                retryTargets.length
                    ? `已处理 ${completedTargets}/${targetLangs.length} 种目标语言；有阻断问题的语言只保存报告。${retryText}`
                    : `已处理 ${completedTargets}/${targetLangs.length} 种目标语言，每种语言已分别保存交付版和报告。`
            );
            if (retryTargets.length) {
                finishInspectorTaskTimer('warning', '多语言队列完成，仍有阻断问题');
            }
            return {
                status: retryTargets.length ? 'needs_action' : 'success',
                completedTargets,
                retryTargets
            };
        }

        updateTranslateLanguageRunState({
            status: 'stopped'
        });
        setTranslateDownloadLanguageSummary(`多语言翻译已停止：已完成 ${completedTargets}/${targetLangs.length} 种语言。`);
        setStatus('warning', '多语言翻译已停止', `已完成 ${completedTargets}/${targetLangs.length} 种目标语言。未完成语言可以稍后重新勾选后继续。`);
        finishInspectorTaskTimer('warning', '多语言翻译已停止');
        return { status: 'cancelled', completedTargets };
    }

    async function startTranslate(options = {}) {
        if (activeTranslateRunId && progressSection.style.display !== 'none') {
            setStatus('warning', '已有翻译任务正在运行', '请先点击“取消任务”停止当前任务，或点击“暂停”保存当前进度。');
            return { status: 'running' };
        }

        const sourceLang = sourceLangSelect?.value || document.getElementById('sourceLang').value;
        const targetLangs = getTranslateBatchTargetLangs();
        if (!options.skipMultiTarget && !pendingRetryTranslationTasks && targetLangs.length > 1) {
            return startMultiTargetTranslate(targetLangs);
        }
        if (!options.skipMultiTarget && targetLangs.length === 1 && targetLangSelect) {
            targetLangSelect.value = targetLangs[0];
        }
        let targetLang = targetLangSelect?.value || document.getElementById('targetLang').value;
        const runLanguageLabel = getTranslateRunLanguageLabel(targetLang, options);
        const previousOutputSuffix = activeTranslationOutputSuffix;
        if (options.outputSuffix !== undefined) {
            activeTranslationOutputSuffix = options.outputSuffix || '';
        }
        let activeProfiles = getSelectedTranslateProfiles();
        const retryTasks = pendingRetryTranslationTasks ? [...pendingRetryTranslationTasks] : null;
        const twoStageRetryRun = shouldUseTwoStageTranslationRetry(retryTasks, options);
        const deferAutoQaRepairForRun = Boolean(
            twoStageRetryRun ||
            options.deferAutoQaRepair ||
            (!retryTasks && isTranslateFastBatchModeEnabled())
        );
        const glossaryTermsForRun = Array.isArray(options.glossaryTermsSnapshot)
            ? options.glossaryTermsSnapshot
            : getSelectedTranslateGlossaryTerms();
        let runOutcome = 'started';
        let runReportFailureCount = 0;
        let runRepairableCount = 0;
        let deferredRetryRepairSummary = null;

        console.log('🚀 开始翻译', { targetLang, currentProject: currentProject?.name, selectedColumns, sheetDataLength: sheetData?.length });

        if (!currentProject) {
            alert('请先选择游戏项目');
            if (options.outputSuffix !== undefined) activeTranslationOutputSuffix = previousOutputSuffix;
            return { status: 'blocked', reason: 'no-project' };
        }

        if (!retryTasks && (!sheetData || sheetData.length === 0)) {
            console.error('❌ sheetData为空');
            alert('请先上传并成功载入要翻译的文件');
            if (options.outputSuffix !== undefined) activeTranslationOutputSuffix = previousOutputSuffix;
            return { status: 'blocked', reason: 'no-file' };
        }

        if (
            !retryTasks &&
            importedTranslateProgressState?.entries?.length &&
            !importedTranslateProgressState.reviewedAt
        ) {
            const reviewCompleted = reviewImportedTranslationCompleteness();
            if (!reviewCompleted) {
                if (options.outputSuffix !== undefined) activeTranslationOutputSuffix = previousOutputSuffix;
                return { status: 'cancelled', reason: 'import-review-cancelled' };
            }
            targetLang = targetLangSelect?.value || targetLang;
        }

        let resumeProgress = null;
        const shouldIgnoreSavedProgress = Boolean(
            options.ignoreSavedProgress ||
            importedTranslateProgressState?.entries?.length
        );
        if (!retryTasks && shouldIgnoreSavedProgress) {
            clearTranslationProgress();
        } else if (!retryTasks) {
            const savedProgress = await loadTranslationProgress();
            const progressMatchesFile = savedProgress &&
                savedProgress.fileName === originalFileName &&
                (!savedProgress.sourceSignature || savedProgress.sourceSignature === getTranslateSourceSignature());
            if (progressMatchesFile) {
                const savedTargetLang = savedProgress.targetLang || '';
                const currentTargetLang = targetLang;
                const progressMatchesTargetLang = !savedTargetLang || savedTargetLang === currentTargetLang;

                if (!progressMatchesTargetLang) {
                    const savedLangName = getTranslateLanguageName(savedTargetLang);
                    const currentLangName = getTranslateLanguageName(currentTargetLang);
                    const startCurrentLanguage = confirm(`检测到同文件存在 ${savedLangName} 的未完成翻译进度，但当前选择的是 ${currentLangName}。\n\n点击“确定”将忽略旧进度并开始 ${currentLangName} 新翻译；点击“取消”则不开始任务。`);
                    if (startCurrentLanguage) {
                        clearTranslationProgress();
                    } else {
                        if (options.outputSuffix !== undefined) activeTranslationOutputSuffix = previousOutputSuffix;
                        return { status: 'cancelled', reason: 'resume-target-mismatch' };
                    }
                } else {
                    const savedEntries = normalizeTranslationProgressEntries(savedProgress);
                    const counts = countTranslationProgressEntries(savedEntries);
                    const shouldResume = confirm(`检测到未完成的 ${getTranslateLanguageName(currentTargetLang)} 翻译任务，已完成 ${counts.successCount + counts.failCount} 个（成功 ${counts.successCount}，失败 ${counts.failCount}）。是否继续？`);
                    if (shouldResume) {
                        restoreTranslationProgressSettings(savedProgress);
                        resumeProgress = savedProgress;
                        targetLang = document.getElementById('targetLang').value;
                        activeProfiles = getSelectedTranslateProfiles();
                    } else {
                        clearTranslationProgress();
                    }
                }
            } else if (savedProgress?.fileName === originalFileName && savedProgress.sourceSignature) {
                clearTranslationProgress();
            }
        }

        if (!retryTasks && selectedColumns.length === 0) {
            columnSelectSection.style.display = 'block';
            renderColumnList();
            columnSelectSection.scrollIntoView({ behavior: 'smooth', block: 'center' });
            alert('请先选择要翻译的列');
            if (options.outputSuffix !== undefined) activeTranslationOutputSuffix = previousOutputSuffix;
            return { status: 'blocked', reason: 'no-columns' };
        }

        if (!ensureTranslateProfilesConfigured('文本翻译')) {
            progressSection.style.display = 'none';
            downloadSection.style.display = 'none';
            if (options.outputSuffix !== undefined) activeTranslationOutputSuffix = previousOutputSuffix;
            return { status: 'blocked', reason: 'no-profiles' };
        }

        activeProfiles = getSelectedTranslateProfiles();
        isTranslationCancelled = false;
        isPaused = false;
        const runId = `translate_${Date.now().toString(36)}`;
        const runController = new AbortController();
        activeTranslateRunId = runId;
        currentTranslateAbortController = runController;
        const runSignal = runController.signal;

        progressSection.style.display = 'block';
        downloadSection.style.display = 'none';
        pauseBtn.style.display = 'inline-flex';
        resumeBtn.style.display = 'none';
        downloadProgressBtn.style.display = 'none';
        if (Number(options.multiTargetTotal) > 1) {
            updateTranslateLanguageRunState({
                targets: getTranslateBatchTargetLangs(),
                currentIndex: Number(options.multiTargetIndex) || 0,
                status: 'running'
            });
        } else {
            updateTranslateLanguageRunState({
                targets: [targetLang],
                currentIndex: 0,
                completed: [],
                failed: [],
                status: 'running'
            });
            setTranslateDownloadLanguageSummary(`正在翻译 ${getTranslateLanguageName(targetLang)}；硬错误清零后生成交付版，否则只生成问题报告。`);
        }
        hideStatus();

        const translationList = document.getElementById('translationList');
        if (!retryTasks) translationList.innerHTML = '';

        const totalRows = sheetData.length;
        const totalCells = (totalRows - 1) * selectedColumns.length * activeProfiles.length;

        console.log(`📈 预计翻译 ${totalCells} 个单元格 (共 ${totalRows} 行, ${selectedColumns.length} 列)`);

        if (!retryTasks) {
            translateSources.forEach(source => {
                source.outputRows = (source.rows || []).map(row => Array.isArray(row) ? [...row] : []);
                source.outputHeader = source.outputRows[0] || [];
                source.outputColMap = new Map();
            });
            translatedDataLocal = sheetData ? sheetData.map(row => Array.isArray(row) ? [...row] : []) : [];
            translatedWorkbook = null;
            const savedEntries = normalizeTranslationProgressEntries(resumeProgress);
            translationRunReport = {
                createdAt: resumeProgress?.runCreatedAt || resumeProgress?.translationRunReport?.createdAt || new Date().toISOString(),
                sourceName: originalFileName,
                targetLang,
                totalTasks: 0,
                successCount: 0,
                failCount: 0,
                entries: []
            };
            failedTranslationTasks = [];
            translationProgressTasks = new Map(savedEntries.map(entry => [entry.taskKey, entry]));
        } else if (!translationRunReport) {
            translationRunReport = {
                createdAt: new Date().toISOString(),
                sourceName: originalFileName,
                targetLang,
                totalTasks: retryTasks.length,
                successCount,
                failCount,
                entries: []
            };
        }

        let startRow = 1;
        if (!retryTasks) {
            successCount = 0;
            failCount = 0;
        }
        let translateCount = 0;
        let runSuccessCount = 0;
        let runFailCount = 0;

        setStatus('processing', `正在翻译 ${runLanguageLabel}`, `预计翻译 ${totalCells} 个单元格`);

        try {
            console.log('📊 翻译任务统计:', { totalRows, startRow, selectedColumns });

            const allTranslationTasks = retryTasks || collectTranslationTasks(activeProfiles);
            translateRunConsistencyTerms = targetLang === 'zh-TW'
                ? []
                : buildTranslateRunConsistencyTerms(allTranslationTasks);
            const translateConsistencyExamplePool = targetLang === 'zh-TW'
                ? null
                : buildTranslateConsistencyExamplePool(translationRunReport?.entries || [], targetLang);
            allTranslationTasks.forEach(task => {
                task.consistencyTerms = translateRunConsistencyTerms.length
                    ? getRelevantTranslateConsistencyTerms([task.text, task.referenceText], translateRunConsistencyTerms, TRANSLATE_CONSISTENCY_TASK_TERM_LIMIT)
                    : [];
                task.consistencyExamples = translateConsistencyExamplePool
                    ? getRelevantTranslateConsistencyExamples(task, translateConsistencyExamplePool)
                    : [];
            });
            setExpectedTranslationTasks(allTranslationTasks);
            let translationTasks = allTranslationTasks;
            const translationMemory = new Map();
            const translationMemoryPromises = new Map();

            function buildTranslationMemoryKey(task) {
                const glossaryKey = (task.glossaryTerms || [])
                    .map(term => `${term.source}|${term.constraint || 'hard'}|${term.target || term.referenceTarget || ''}`)
                    .join('|');
                return makeStableId([
                    task.profile?.id || task.profile?.model || '',
                    sourceLang,
                    targetLang,
                    currentProject?.id || makeStableId(currentProject?.rules || ''),
                    task.text,
                    task.referenceText || '',
                    glossaryKey
                ].join('\u001f'));
            }

            function rememberSuccessfulTranslation(task, translated) {
                if (isTranslateFailureText(translated)) return;
                translationMemory.set(buildTranslationMemoryKey(task), translated);
            }

            function seedTranslationMemoryFromProgress(tasks) {
                tasks.forEach(task => {
                    const entry = translationProgressTasks.get(task.taskKey);
                    if (
                        !entry?.translatedText ||
                        String(entry.status || '').toLowerCase() !== 'success' ||
                        !isTranslationQaPassed(entry.qaStatus) ||
                        isTranslateFailureText(entry.translatedText)
                    ) return;
                    translationMemory.set(buildTranslationMemoryKey(task), entry.translatedText);
                });
            }

            let importedRestoreSummary = { matched: 0, unmatched: 0, skippedTargetMismatch: 0 };
            if (!retryTasks) {
                const restoreEntriesByKey = new Map();
                if (resumeProgress) {
                    normalizeTranslationProgressEntries(resumeProgress).forEach(entry => {
                        if (entry.taskKey) restoreEntriesByKey.set(entry.taskKey, entry);
                    });
                }
                importedRestoreSummary = buildImportedTranslationRestoreEntries(allTranslationTasks, targetLang);
                importedRestoreSummary.entries.forEach(entry => {
                    restoreEntriesByKey.set(entry.taskKey, entry);
                });
                if (restoreEntriesByKey.size > 0) {
                    translationTasks = restoreCompletedTranslationTasks(
                        allTranslationTasks,
                        [...restoreEntriesByKey.values()],
                        targetLang
                    );
                }
                const restoredCounts = countTranslationProgressEntries([...translationProgressTasks.values()]);
                translateCount = restoredCounts.successCount + restoredCounts.failCount;
            }
            seedTranslationMemoryFromProgress(allTranslationTasks);

            if (translationRunReport) {
                translationRunReport.totalTasks = allTranslationTasks.length;
            }

            let completedCount = 0;
            const totalTasks = translationTasks.length;
            initTranslateChannelProgress(translationTasks);
            translateRunSummaryState = {
                completed: 0,
                total: totalTasks,
                phase: retryTasks
                    ? `${runLanguageLabel}硬问题重译准备中`
                    : (deferAutoQaRepairForRun ? `${runLanguageLabel}快速翻译准备中` : `${runLanguageLabel}翻译准备中`)
            };
            updateTranslateRunSummary(0, totalTasks, translateRunSummaryState.phase);

            if (totalTasks === 0) {
                translatedWorkbook = buildTranslationWorkbook();
                translatedData = translatedDataLocal;
                progressSection.style.display = 'none';
                downloadSection.style.display = 'block';
                ensureTranslationReportCoversExpectedTasks();
                const latestEntryByTask = new Map();
                (translationRunReport?.entries || []).forEach(entry => {
                    if (entry.taskKey) latestEntryByTask.set(entry.taskKey, entry);
                });
                failedTranslationTasks = allTranslationTasks.filter(task => {
                    const entry = latestEntryByTask.get(task.taskKey);
                    return entry && isRepairableTranslationReportEntry(entry);
                });
                if (translationRunReport) {
                    const restoredCounts = countTranslationProgressEntries([...translationProgressTasks.values()]);
                    translationRunReport.successCount = restoredCounts.successCount;
                    translationRunReport.failCount = restoredCounts.failCount;
                }
                const deliveryGate = getTranslationDeliveryGate();
                if (!deliveryGate.ready) {
                    await flushTranslationTaskProgress();
                    await saveCurrentTranslationProgress(1);
                } else {
                    clearTranslationProgress();
                }
                document.getElementById('translatedCount').textContent = translateCount;
                updateTranslationRunActions();
                let autoSaveMessage = '';
                if (options.suppressAutoSave) {
                    autoSaveMessage = deliveryGate.ready
                        ? '；交付版已生成，请点击下载按钮保存'
                        : `；仍有 ${deliveryGate.blockingCount} 条阻断问题，未生成交付版`;
                } else {
                    try {
                        const savedPaths = await autoSaveTranslationOutputs();
                        autoSaveMessage = deliveryGate.ready
                            ? (savedPaths.length ? `；已自动保存：${savedPaths.join('；')}` : '')
                            : `；仍有 ${deliveryGate.blockingCount} 条阻断问题，未生成交付版${savedPaths.length ? `；问题报告已保存：${savedPaths.join('；')}` : ''}`;
                    } catch (saveError) {
                        console.warn('自动保存翻译结果失败:', saveError);
                        autoSaveMessage = deliveryGate.ready
                            ? '；自动保存失败，请点击下载按钮手动保存'
                            : `；仍有 ${deliveryGate.blockingCount} 条阻断问题，未生成交付版；问题报告自动保存失败`;
                    }
                }
                const issueSummary = getTranslationReportIssueSummary();
                runReportFailureCount = issueSummary.totalFailed;
                runRepairableCount = deliveryGate.blockingCount;
                const hasRepairableFailures = !deliveryGate.ready;
                if (hasRepairableFailures) markTranslateLanguageFailed(targetLang);
                else markTranslateLanguageCompleted(targetLang);
                if (!options.skipMultiTarget) {
                    updateTranslateLanguageRunState({
                        currentIndex: -1,
                        status: hasRepairableFailures ? 'needs_action' : 'success'
                    });
                }
                const restoredCompleteText = resumeProgress
                    ? '已恢复上次结果，没有剩余需要翻译的文本。'
                    : (importedRestoreSummary.matched > 0
                        ? `已复用导入报告 ${importedRestoreSummary.matched} 条，没有剩余需要翻译的文本。`
                        : '没有需要翻译的有效文本。');
                const repairableText = hasRepairableFailures
                    ? `仍有 ${runRepairableCount} 个翻译失败、结果缺失或硬质检问题可自动处理。`
                    : '';
                setTranslateDownloadLanguageSummary(
                    `${getTranslateLanguageName(targetLang)}已恢复。${restoredCompleteText}${repairableText}`
                );
                updateTranslateRunSummary(
                    0,
                    0,
                    hasRepairableFailures ? `${runLanguageLabel}已恢复，有可自动处理项` : `${runLanguageLabel}翻译完成`
                );
                setStatus(
                    hasRepairableFailures ? 'warning' : 'success',
                    hasRepairableFailures ? `${runLanguageLabel}仍有阻断问题，未生成交付版` : `${runLanguageLabel}翻译完成`,
                    `${restoredCompleteText}${repairableText}${autoSaveMessage}`
                );
                if (hasRepairableFailures) {
                    finishInspectorTaskTimer('warning', `${runLanguageLabel}仍有阻断问题`);
                }
                runOutcome = hasRepairableFailures ? 'needs_action' : 'success';
                return {
                    status: runOutcome,
                    targetLang,
                    successCount,
                    failCount,
                    failureCount: runReportFailureCount,
                    repairableCount: runRepairableCount
                };
            }

            const runProfiles = getProfilesFromTranslationTasks(translationTasks);
            const consistencyMemoryStatus = translateRunConsistencyTerms.length > 0
                ? `；已启用自动一致性记忆 ${translateRunConsistencyTerms.length} 个高频短语`
                : (isTranslateConsistencyMemoryEnabled() ? '；未发现需要约束的重复短语' : '；自动一致性记忆已关闭');
            startTranslateElapsedTimer();
            updateTranslateRunSummary(0, totalTasks, `${runLanguageLabel}通道预检中`);
            setStatus(
                'processing',
                retryTasks ? `正在检查 ${runLanguageLabel} 重译通道...` : `正在检查 ${runLanguageLabel} 翻译通道...`,
                `${runProfiles.length} 个通道参与，会先确认 Key、Base URL 和模型权限；预检失败时不会启动批量翻译${consistencyMemoryStatus}。`
            );
            await preflightTranslateProfiles(runProfiles, sourceLang, targetLang, runSignal);
            throwIfTranslationCancelled(runId);

            await saveCurrentTranslationProgress(1);
            updateTranslateRunSummary(
                0,
                totalTasks,
                retryTasks
                    ? `${runLanguageLabel}硬问题重译中`
                    : (deferAutoQaRepairForRun ? `${runLanguageLabel}快速翻译运行中` : `${runLanguageLabel}翻译运行中`)
            );
            const importReuseStatus = importedRestoreSummary.matched > 0
                ? `；已复用导入报告 ${importedRestoreSummary.matched} 条`
                : '';
            const importMismatchStatus = importedRestoreSummary.skippedTargetMismatch > 0
                ? `；${importedRestoreSummary.skippedTargetMismatch} 条导入记录因目标语言不一致未复用`
                : '';
            const translateRunModeStatus = deferAutoQaRepairForRun
                ? '；快速模式已开启：第一轮只记录 QA，不逐条 AI 修复'
                : '';
            setStatus(
                'processing',
                retryTasks ? `正在重译 ${runLanguageLabel} 硬问题...` : (deferAutoQaRepairForRun ? `${runLanguageLabel}快速翻译中` : `${runLanguageLabel}翻译中`),
                `本轮 ${totalTasks} 个任务，已启用 ${translateChannelProgressState.size} 个通道${consistencyMemoryStatus}${translateRunModeStatus}${importReuseStatus}${importMismatchStatus}。通道状态会在进度面板实时更新。`
            );

            function commitTranslateResult(task, translated, qaStatusOverride = null) {
                throwIfTranslationCancelled(runId);
                const normalizedTranslated = normalizeTranslateResultText(translated, task.text);
                const qaTerms = task.glossaryTerms || [];
                const qaStatus = qaStatusOverride ?? (translatePostCheckInput?.checked
                    ? summarizeTranslationQa(task.text, normalizedTranslated, qaTerms, targetLang, task)
                    : '');
                const status = getTranslationReportStatus(normalizedTranslated, qaStatus);
                const previousTaskKeys = new Set([task.taskKey, task.retryOfTaskKey].filter(Boolean));
                previousTaskKeys.forEach(previousTaskKey => {
                    const previousEntry = translationProgressTasks.get(previousTaskKey);
                    if (!previousEntry) return;
                    const previousCounts = countTranslationProgressEntries([previousEntry]);
                    successCount = Math.max(0, successCount - previousCounts.successCount);
                    failCount = Math.max(0, failCount - previousCounts.failCount);
                    translationProgressTasks.delete(previousTaskKey);
                });
                if (task.retryOfTaskKey && task.retryOfTaskKey !== task.taskKey) {
                    deleteTranslationTaskProgress(task.retryOfTaskKey);
                }
                if (status !== 'success') {
                    failCount++;
                    runFailCount++;
                } else {
                    successCount++;
                    runSuccessCount++;
                }
                writeTranslationResult(task, normalizedTranslated, qaStatus);
                translateCount++;
                completedCount++;

                translationRunReport = translationRunReport || { entries: [] };
                const reportEntry = buildTranslationReportEntry(task, normalizedTranslated, qaStatus);
                const compactEntry = compactTranslationProgressEntry(reportEntry);
                translationProgressTasks.set(task.taskKey, compactEntry || reportEntry);
                queueTranslationTaskProgress(reportEntry);
                const reportEntries = translationRunReport.entries || [];
                const replaceableTaskKeys = new Set([task.taskKey, task.retryOfTaskKey].filter(Boolean));
                const existingReportIndex = reportEntries.findIndex(entry => replaceableTaskKeys.has(entry.taskKey));
                if (existingReportIndex >= 0) reportEntries[existingReportIndex] = reportEntry;
                else reportEntries.push(reportEntry);
                translationRunReport.entries = reportEntries;
                if (status === 'success') rememberSuccessfulTranslation(task, normalizedTranslated);

                if (shouldRenderTranslationPreview(status, completedCount)) {
                    addTranslationItem(translationList, task.text, normalizedTranslated, task.rowIndex, task.colIndex, task.profile, targetLang);
                }

                const progress = Math.round((completedCount / totalTasks) * 100);
                updateTranslateProgress(completedCount, totalTasks, progress);
                recordTranslateChannelResult(task, status);
                updateTranslateRunSummary(
                    completedCount,
                    totalTasks,
                    retryTasks
                        ? `${runLanguageLabel}硬问题重译中`
                        : (deferAutoQaRepairForRun ? `${runLanguageLabel}快速翻译运行中` : `${runLanguageLabel}翻译运行中`)
                );

                if (completedCount % TRANSLATION_PROGRESS_SAVE_INTERVAL === 0) {
                    saveCurrentTranslationProgress(task?.rowIndex || 1);
                    updateTranslationRunActions();
                }
                return status;
            }

            function commitUnfinishedTranslateTaskFailures(tasks = [], reason = '当前批次异常，已保留为待补跑') {
                let committed = 0;
                let failed = 0;
                tasks.forEach(task => {
                    if (!task?.taskKey || translationProgressTasks.has(task.taskKey)) return;
                    const status = commitTranslateResult(task, makeTranslateFailureText(task.text, reason));
                    recordChannelOutcome(task, true);
                    committed++;
                    if (status !== 'success') failed++;
                });
                return { committed, failed };
            }

            async function processLocalDiscountTask(task) {
                const localTranslation = getNexusStandaloneDiscountTranslation(task?.text, targetLang);
                if (localTranslation == null) return null;
                throwIfTranslationCancelled(runId);
                updateTranslateChannelProgress(task.profile, {
                    status: 'running',
                    message: '本地折扣规则，无需 AI'
                });
                const result = await prepareTranslationForCommit(task, localTranslation);
                const status = commitTranslateResult(task, result.translated, result.qaStatus);
                recordChannelOutcome(task, status === 'failed' || status === 'missing');
                return status;
            }

            const channelFailureStreaks = new Map();
            const channelCooldowns = new Map();

            function getProfileRunId(profile) {
                return profile?.id || profile?.model || profile?.name || 'default';
            }

            function getChannelCooldown(profile) {
                const profileId = getProfileRunId(profile);
                const cooldown = channelCooldowns.get(profileId);
                if (!cooldown || Date.now() >= cooldown.until) {
                    channelCooldowns.delete(profileId);
                    return null;
                }
                return cooldown;
            }

            async function waitForTranslateChannelRecovery(profile) {
                let cooldown = getChannelCooldown(profile);
                while (cooldown) {
                    throwIfTranslationCancelled(runId);
                    while (isPaused && !isTranslationCancelled) {
                        await waitForResume();
                    }
                    throwIfTranslationCancelled(runId);

                    const remainingMs = Math.max(0, cooldown.until - Date.now());
                    updateTranslateChannelProgress(profile, {
                        status: 'retrying',
                        message: `${cooldown.reason}，冷却 ${Math.ceil(remainingMs / 1000)} 秒后继续`
                    });
                    await new Promise(resolve => setTimeout(resolve, Math.min(1000, remainingMs || 1000)));
                    cooldown = getChannelCooldown(profile);
                }
            }

            // Batch, single-item, and QA-repair calls share one per-channel limiter.
            // This keeps the repair workers from bypassing the channel's effective cap.
            const translationRequestLimiters = new Map();
            const translationRequestAdaptiveCaps = new Map();
            const translationRequestPacers = new Map();

            function setTranslationRequestAdaptiveCap(profile, limit) {
                const key = getTranslateChannelKey(profile);
                const numericLimit = Number(limit);
                if (Number.isFinite(numericLimit) && numericLimit > 0) {
                    translationRequestAdaptiveCaps.set(key, numericLimit);
                }
            }

            function getTranslationRequestLimiter(profile) {
                const key = getTranslateChannelKey(profile);
                if (!translationRequestLimiters.has(key)) {
                    const getCapacity = () => {
                        const configured = getTranslateEffectiveConcurrencyLimit(profile);
                        const state = translateChannelProgressState.get(key);
                        const adaptive = Number(translationRequestAdaptiveCaps.get(key));
                        const adaptiveLimit = Number.isFinite(adaptive) && adaptive > 0 ? adaptive : configured;
                        const lastIncidentAt = Number(state?.lastIncidentAt || 0);
                        const hasRecentIncident = lastIncidentAt > 0 &&
                            Date.now() - lastIncidentAt < TRANSLATION_ADAPTIVE_COOLDOWN_MS;
                        return hasRecentIncident
                            ? 1
                            : Math.max(1, Math.min(configured, adaptiveLimit));
                    };

                    const onCancel = () => throwIfTranslationCancelled(runId);
                    const concurrencyLimiter = createTranslationRequestLimiter(getCapacity, onCancel);
                    const configuredBaseUrl = String(profile?.baseUrl || API_PLATFORMS[profile?.provider]?.baseUrl || '')
                        .trim()
                        .replace(/\/+$/, '');
                    const pacingKey = profile?.provider === 'agnes'
                        ? `agnes:${configuredBaseUrl}`
                        : key;
                    if (!translationRequestPacers.has(pacingKey)) {
                        translationRequestPacers.set(
                            pacingKey,
                            createTranslationRpmPacer(
                                () => {
                                    const configuredRpm = Number(profile?.translationRpm || profile?.requestsPerMinute || 0);
                                    if (Number.isFinite(configuredRpm) && configuredRpm > 0) {
                                        return getTranslationTargetRpm(profile);
                                    }
                                    const hasAgnesCongestion = [...translateChannelProgressState.values()].some(state =>
                                        state?.profile?.provider === 'agnes' &&
                                        Number(state?.congestionCount || 0) > 0
                                    );
                                    const shouldPaceAgnes = Boolean(
                                        retryTasks || hasAgnesCongestion
                                    );
                                    return shouldPaceAgnes ? getTranslationTargetRpm(profile) : 0;
                                },
                                onCancel
                            )
                        );
                    }
                    const waitUntilActive = async () => {
                        while (isPaused && !isTranslationCancelled) await waitForResume();
                        throwIfTranslationCancelled(runId);
                    };
                    translationRequestLimiters.set(
                        key,
                        createTranslationRequestGate(
                            concurrencyLimiter,
                            translationRequestPacers.get(pacingKey),
                            waitUntilActive
                        )
                    );
                }
                return translationRequestLimiters.get(key);
            }

            function recordChannelOutcome(task, isFailed) {
                const profileId = getProfileRunId(task.profile);
                if (!isFailed) {
                    channelFailureStreaks.set(profileId, 0);
                    channelCooldowns.delete(profileId);
                    return;
                }

                const nextStreak = (channelFailureStreaks.get(profileId) || 0) + 1;
                channelFailureStreaks.set(profileId, nextStreak);
                if (nextStreak >= TRANSLATION_CHANNEL_FAILURE_LIMIT) {
                    const profileName = task.profile?.name || getCompactModelLabel(task.profile);
                    const reason = `${profileName} 连续失败 ${TRANSLATION_CHANNEL_FAILURE_LIMIT} 次，已自动降速并等待恢复`;
                    channelCooldowns.set(profileId, {
                        until: Date.now() + TRANSLATION_CHANNEL_RECOVERY_COOLDOWN_MS,
                        reason
                    });
                    channelFailureStreaks.set(profileId, 0);
                    updateTranslateChannelProgress(task.profile, {
                        status: 'retrying',
                        message: reason
                    });
                    setStatus('warning', '翻译通道正在冷却', `${reason}；不会把后续任务直接判失败，冷却后会继续跑，已完成结果会保留。`);
                    console.warn(`⚠️ 翻译通道冷却: ${profileName}`);
                }
            }

            async function prepareTranslationForCommit(task, translated, prepareOptions = {}) {
                let nextTranslated = applyLocalTranslationFixes(task.text, translated, targetLang);
                if (!translatePostCheckInput?.checked) {
                    /*
                     * Monetary semantics and cross-language carryover remain
                     * protected even when the broader post-check switch is
                     * off. These guards are local and deterministic; they
                     * never make an API request.
                     */
                    const baselineIssues = [
                        ...getNexusDiscountQaIssues(task.text, nextTranslated, targetLang),
                        ...getTargetLanguageLeakageIssues(task.text, nextTranslated, targetLang, {
                            ...task,
                            glossaryTerms: task.glossaryTerms || []
                        })
                    ];
                    const uniqueBaselineIssues = [...new Set(baselineIssues)].filter(Boolean);
                    return {
                        translated: nextTranslated,
                        qaStatus: uniqueBaselineIssues.length ? `需确认：${uniqueBaselineIssues.join('；')}` : ''
                    };
                }

                let qaStatus = summarizeTranslationQa(task.text, nextTranslated, task.glossaryTerms || [], targetLang, task);
                if (isTranslateFailureText(nextTranslated) || isTranslationQaPassed(qaStatus)) {
                    return { translated: nextTranslated, qaStatus };
                }
                const deferQaRepair = prepareOptions.deferAutoQaRepair ?? deferAutoQaRepairForRun;
                if (deferQaRepair) {
                    return { translated: nextTranslated, qaStatus };
                }
                if (!shouldAutoRepairTranslationQa(qaStatus, targetLang)) {
                    return { translated: nextTranslated, qaStatus };
                }

                const beforeRepairTranslated = nextTranslated;
                const beforeRepairQaStatus = qaStatus;
                const requestLimiter = getTranslationRequestLimiter(task.profile);
                const maxRepairAttempts = Math.max(0, Math.min(
                    TRANSLATION_QA_REPAIR_MAX_ATTEMPTS,
                    Number(prepareOptions.maxRepairAttempts ?? TRANSLATION_QA_REPAIR_MAX_ATTEMPTS) || 0
                ));
                for (let repairAttempt = 0;
                    repairAttempt < maxRepairAttempts && !isTranslationQaPassed(qaStatus);
                    repairAttempt++) {
                    recordTranslateQaRepairAttempt(task.profile, repairAttempt);
                    updateTranslateChannelProgress(task.profile, {
                        status: 'retrying',
                        message: `QA 未通过，自动修复第 ${repairAttempt + 1} 次`
                    });
                    let repairRequestFailed = false;
                    const repaired = await repairTranslationWithRetry(
                        task,
                        nextTranslated,
                        qaStatus,
                        sourceLang,
                        targetLang,
                        currentProject.rules,
                        task.profile,
                        runSignal,
                        1,
                        {
                            requestLimiter,
                            onFailure: () => {
                                repairRequestFailed = true;
                            }
                        }
                    );
                    const repairedTranslated = applyLocalTranslationFixes(task.text, repaired, targetLang);
                    const repairedQaStatus = summarizeTranslationQa(
                        task.text,
                        repairedTranslated,
                        task.glossaryTerms || [],
                        targetLang,
                        task
                    );
                    const repairChangedTranslation = hasTranslationQaRepairChanged(
                        nextTranslated,
                        repairedTranslated,
                    );
                    const shouldContinueRepair = shouldAttemptNextTranslationQaRepair(
                        nextTranslated,
                        repairedTranslated,
                        repairAttempt,
                        maxRepairAttempts,
                        repairRequestFailed
                    );
                    nextTranslated = repairedTranslated;
                    qaStatus = repairedQaStatus;
                    if (isTranslateFailureText(nextTranslated)) break;
                    if (!repairChangedTranslation && !repairRequestFailed && !isTranslationQaPassed(qaStatus)) {
                        updateTranslateChannelProgress(task.profile, {
                            status: 'retrying',
                            message: 'QA 修复未改变译文，已停止重复修复'
                        });
                        break;
                    }
                    if (!shouldContinueRepair) break;
                }
                const repairRequestsStillActive = requestLimiter.getActiveCount() > 0;
                updateTranslateChannelProgress(task.profile, {
                    status: repairRequestsStillActive ? 'retrying' : 'running',
                    message: repairRequestsStillActive ? 'QA 修复进行中' : 'QA 修复结束，写入结果'
                });

                if (targetLang === 'zh-TW' && /疑似内容流失|疑似译文过短/.test(qaStatus)) {
                    return {
                        translated: makeTranslateFailureText(task.text, '疑似内容流失，已拒绝写入半句译文'),
                        qaStatus
                    };
                }
                if (
                    targetLang !== 'zh-TW' &&
                    isTranslateAutoCompactLongEnabled() &&
                    /译文长度超出建议/.test(beforeRepairQaStatus) &&
                    !/疑似内容流失|疑似译文过短/.test(beforeRepairQaStatus) &&
                    /疑似内容流失|疑似译文过短/.test(qaStatus)
                ) {
                    return { translated: beforeRepairTranslated, qaStatus: beforeRepairQaStatus };
                }
                return { translated: nextTranslated, qaStatus };
            }

            function getDeferredRetryRepairJobs() {
                if (!twoStageRetryRun) return [];
                const reportEntryByTaskKey = new Map();
                (translationRunReport?.entries || []).forEach(entry => {
                    if (entry?.taskKey) reportEntryByTaskKey.set(entry.taskKey, entry);
                });
                return allTranslationTasks.map(task => {
                    const entry = translationProgressTasks.get(task.taskKey) || reportEntryByTaskKey.get(task.taskKey);
                    const kind = classifyTranslationReportEntry(entry);
                    return ['hard', 'missing'].includes(kind) ? { task, entry, kind } : null;
                }).filter(Boolean);
            }

            function replaceTranslateChannelResult(task, previousStatus, nextStatus) {
                const key = getTranslateChannelKey(task.profile);
                const previous = translateChannelProgressState.get(key) || createTranslateChannelProgressRecord(task.profile);
                const wasSuccess = previousStatus === 'success';
                const isSuccess = nextStatus === 'success';
                const wasQaFailed = previousStatus === 'qa_failed';
                const isQaFailed = nextStatus === 'qa_failed';
                const next = {
                    ...previous,
                    profile: task.profile,
                    success: Math.max(0, Number(previous.success || 0) - (wasSuccess ? 1 : 0) + (isSuccess ? 1 : 0)),
                    failed: Math.max(0, Number(previous.failed || 0) - (wasSuccess ? 0 : 1) + (isSuccess ? 0 : 1)),
                    qaFailed: Math.max(0, Number(previous.qaFailed || 0) - (wasQaFailed ? 1 : 0) + (isQaFailed ? 1 : 0)),
                    updatedAt: Date.now()
                };
                if (next.total > 0 && next.completed >= next.total) {
                    next.status = next.failed > 0 ? 'warning' : 'done';
                    next.message = next.failed > 0
                        ? `两阶段修复完成，仍有问题 ${next.failed} 个`
                        : '两阶段修复完成，硬问题已清零';
                }
                translateChannelProgressState.set(key, next);
                renderTranslateChannelProgress();
            }

            function replaceCommittedTranslateResult(task, translated, qaStatusOverride = null) {
                throwIfTranslationCancelled(runId);
                const previousEntry = translationProgressTasks.get(task.taskKey);
                const previousStatus = previousEntry
                    ? getTranslationReportStatus(previousEntry.translatedText, previousEntry.qaStatus)
                    : 'missing';
                const normalizedTranslated = normalizeTranslateResultText(translated, task.text);
                const qaStatus = qaStatusOverride ?? (translatePostCheckInput?.checked
                    ? summarizeTranslationQa(task.text, normalizedTranslated, task.glossaryTerms || [], targetLang, task)
                    : '');
                if (
                    previousEntry?.translatedText &&
                    !isTranslateFailureText(previousEntry.translatedText) &&
                    isTranslateFailureText(normalizedTranslated)
                ) {
                    return { status: previousStatus, entry: previousEntry, changed: false };
                }

                writeTranslationResult(task, normalizedTranslated, qaStatus);
                if (task.retryOfTaskKey && task.retryOfTaskKey !== task.taskKey) {
                    translationProgressTasks.delete(task.retryOfTaskKey);
                    deleteTranslationTaskProgress(task.retryOfTaskKey);
                }
                translationRunReport = translationRunReport || { entries: [] };
                const reportEntry = buildTranslationReportEntry(task, normalizedTranslated, qaStatus);
                const compactEntry = compactTranslationProgressEntry(reportEntry);
                translationProgressTasks.set(task.taskKey, compactEntry || reportEntry);
                queueTranslationTaskProgress(reportEntry);
                const reportEntries = translationRunReport.entries || [];
                const replaceableTaskKeys = new Set([task.taskKey, task.retryOfTaskKey].filter(Boolean));
                const existingReportIndex = reportEntries.findIndex(item => replaceableTaskKeys.has(item.taskKey));
                if (existingReportIndex >= 0) reportEntries[existingReportIndex] = reportEntry;
                else reportEntries.push(reportEntry);
                translationRunReport.entries = reportEntries;
                const nextStatus = getTranslationReportStatus(normalizedTranslated, qaStatus);
                replaceTranslateChannelResult(task, previousStatus, nextStatus);
                if (nextStatus === 'success') rememberSuccessfulTranslation(task, normalizedTranslated);
                return {
                    status: nextStatus,
                    entry: reportEntry,
                    changed: hasTranslationQaRepairChanged(previousEntry?.translatedText || '', normalizedTranslated) ||
                        String(previousEntry?.qaStatus || '') !== String(qaStatus || '')
                };
            }

            async function runDeferredRetryRepairPhase() {
                const allJobs = getDeferredRetryRepairJobs();
                const summary = {
                    eligible: allJobs.length,
                    scheduled: 0,
                    deferred: 0,
                    attempted: 0,
                    changed: 0,
                    resolved: 0,
                    errors: 0,
                    limitedByBudget: false
                };
                if (!allJobs.length) return summary;
                let jobs = allJobs;
                if (!shouldRunDeferredTranslationRepair(allJobs.length)) {
                    summary.limitedByBudget = true;
                    const cursor = Math.max(0, Number(translationRunReport?.deferredRepairCursor || 0)) % allJobs.length;
                    const rotatedJobs = [...allJobs.slice(cursor), ...allJobs.slice(0, cursor)];
                    jobs = rotatedJobs.slice(0, TRANSLATION_RETRY_DEEP_REPAIR_LIMIT);
                    translationRunReport.deferredRepairCursor = (cursor + jobs.length) % allJobs.length;
                    summary.deferred = Math.max(0, allJobs.length - jobs.length);
                    updateTranslateRunSummary(
                        totalTasks,
                        totalTasks,
                        `${runLanguageLabel}批量重译完成，本轮深修 ${jobs.length}/${allJobs.length} 个硬问题`
                    );
                    setStatus(
                        'warning',
                        '已限制第二阶段修复规模',
                        `批量重译后仍有 ${allJobs.length} 个阻断问题；本轮按安全预算只深度处理 ${jobs.length} 个，其余 ${summary.deferred} 个保留原结果，避免再次形成上千次逐条请求。下轮会从后续条目继续。`
                    );
                }
                summary.scheduled = jobs.length;

                let nextIndex = 0;
                let phaseCompleted = 0;
                const workerCount = Math.max(1, Math.min(
                    TRANSLATION_QA_REPAIR_MAX_CONCURRENCY,
                    jobs.length
                ));
                updateTranslateProgress(0, jobs.length, 0);
                updateTranslateRunSummary(0, jobs.length, `${runLanguageLabel}少量残余硬问题深度修复中`);
                setStatus(
                    'processing',
                    `正在深度修复 ${jobs.length} 个残余硬问题`,
                    `第一阶段批量重译已完成；第二阶段只处理剩余阻断项，每条最多一次定向 QA 修复，并发不超过 ${workerCount}。`
                );

                async function worker() {
                    while (true) {
                        const jobIndex = nextIndex++;
                        if (jobIndex >= jobs.length) return;
                        const { task, entry, kind } = jobs[jobIndex];
                        try {
                            throwIfTranslationCancelled(runId);
                            while (isPaused && !isTranslationCancelled) await waitForResume();
                            throwIfTranslationCancelled(runId);
                            summary.attempted++;
                            updateTranslateChannelProgress(task.profile, {
                                status: 'retrying',
                                message: `第二阶段 ${jobIndex + 1}/${jobs.length}：${kind === 'missing' ? '补回缺失译文' : '定向修复硬问题'}`
                            });

                            let prepared = null;
                            if (kind === 'missing' || isTranslateFailureText(entry?.translatedText)) {
                                await waitForTranslateChannelRecovery(task.profile);
                                const translated = await translateTextWithRetry(
                                    task.text,
                                    sourceLang,
                                    targetLang,
                                    currentProject.rules,
                                    task.profile,
                                    1,
                                    runSignal,
                                    task.glossaryTerms,
                                    task,
                                    { requestLimiter: getTranslationRequestLimiter(task.profile) }
                                );
                                if (!isTranslateFailureText(translated)) {
                                    prepared = await prepareTranslationForCommit(task, translated, {
                                        deferAutoQaRepair: true,
                                        maxRepairAttempts: 0
                                    });
                                    if (
                                        !isTranslateFailureText(prepared.translated) &&
                                        shouldAutoRepairTranslationQa(prepared.qaStatus, targetLang)
                                    ) {
                                        prepared = await prepareTranslationForCommit(task, prepared.translated, {
                                            deferAutoQaRepair: false,
                                            maxRepairAttempts: 1
                                        });
                                    }
                                }
                            } else {
                                prepared = await prepareTranslationForCommit(task, entry.translatedText, {
                                    deferAutoQaRepair: false,
                                    maxRepairAttempts: 1
                                });
                            }

                            if (prepared) {
                                const replacement = replaceCommittedTranslateResult(task, prepared.translated, prepared.qaStatus);
                                if (replacement.changed) summary.changed++;
                                if (!isRepairableTranslationReportEntry(replacement.entry)) summary.resolved++;
                            }
                        } catch (error) {
                            if (error?.name === 'AbortError' || error?.message === 'TRANSLATION_CANCELLED' || isTranslationCancelled) {
                                throw error;
                            }
                            summary.errors++;
                            console.warn('Deferred retry repair failed; preserving the first-stage result:', error);
                        } finally {
                            phaseCompleted++;
                            const percent = Math.round((phaseCompleted / jobs.length) * 100);
                            updateTranslateProgress(phaseCompleted, jobs.length, percent);
                            updateTranslateRunSummary(
                                phaseCompleted,
                                jobs.length,
                                `${runLanguageLabel}残余硬问题深度修复中`
                            );
                        }
                    }
                }

                await Promise.all(Array.from({ length: workerCount }, () => worker()));
                await flushTranslationTaskProgress();
                refreshTranslationRunCountsFromReport();
                const reportEntryByTaskKey = new Map(
                    (translationRunReport?.entries || [])
                        .filter(entry => entry?.taskKey)
                        .map(entry => [entry.taskKey, entry])
                );
                const runCounts = countTranslationProgressEntries(
                    allTranslationTasks
                        .map(task => translationProgressTasks.get(task.taskKey) || reportEntryByTaskKey.get(task.taskKey))
                        .filter(Boolean)
                );
                runSuccessCount = runCounts.successCount;
                runFailCount = runCounts.failCount;
                return summary;
            }

            async function processTranslateTask(task) {
                throwIfTranslationCancelled(runId);
                while (isPaused && !isTranslationCancelled) {
                    await waitForResume();
                }
                throwIfTranslationCancelled(runId);

                const localDiscountStatus = await processLocalDiscountTask(task);
                if (localDiscountStatus !== null) return localDiscountStatus;

                updateTranslateChannelProgress(task.profile, {
                    status: 'running',
                    message: '准备单条翻译'
                });
                if (task.passthrough) {
                    updateTranslateChannelProgress(task.profile, {
                        status: 'running',
                        message: '无需翻译，原样写入'
                    });
                    return commitTranslateResult(task, task.text, '通过');
                }
                const memoryKey = buildTranslationMemoryKey(task);
                if (translationMemory.has(memoryKey)) {
                    updateTranslateChannelProgress(task.profile, {
                        status: 'running',
                        message: '复用同文翻译'
                    });
                    const result = await prepareTranslationForCommit(task, translationMemory.get(memoryKey));
                    return commitTranslateResult(task, result.translated, result.qaStatus);
                }
                if (translationMemoryPromises.has(memoryKey)) {
                    updateTranslateChannelProgress(task.profile, {
                        status: 'running',
                        message: '等待同文请求返回'
                    });
                    const translated = await translationMemoryPromises.get(memoryKey);
                    throwIfTranslationCancelled(runId);
                    const result = await prepareTranslationForCommit(task, translated);
                    return commitTranslateResult(task, result.translated, result.qaStatus);
                }

                await waitForTranslateChannelRecovery(task.profile);
                await waitForNetwork(runSignal);

                updateTranslateChannelProgress(task.profile, {
                    status: 'running',
                    message: '单条翻译请求中'
                });
                const translatePromise = translateTextWithRetry(
                    task.text,
                    sourceLang,
                    targetLang,
                    currentProject.rules,
                    task.profile,
                    3,
                    runSignal,
                    task.glossaryTerms,
                    task,
                    { requestLimiter: getTranslationRequestLimiter(task.profile) }
                )
                    .finally(() => translationMemoryPromises.delete(memoryKey));
                translationMemoryPromises.set(memoryKey, translatePromise);
                const translated = await translatePromise;
                throwIfTranslationCancelled(runId);
                const result = await prepareTranslationForCommit(task, translated);
                const status = commitTranslateResult(task, result.translated, result.qaStatus);
                recordChannelOutcome(task, status === 'failed' || status === 'missing');
                return status;
            }

            async function prepareTranslationBatchResults(tasks, translations, profile, adaptiveConcurrency = 1) {
                const results = new Array(tasks.length);
                const repairConcurrency = getTranslationQaRepairConcurrency(
                    getTranslateEffectiveConcurrencyLimit(profile),
                    adaptiveConcurrency,
                    tasks.length
                );
                let nextIndex = 0;
                let firstError = null;

                async function worker() {
                    while (true) {
                        if (firstError) return;
                        const index = nextIndex++;
                        if (index >= tasks.length) return;
                        try {
                            throwIfTranslationCancelled(runId);
                            const task = tasks[index];
                            const translated = translations[index] || makeTranslateFailureText(task.text);
                            results[index] = {
                                result: await prepareTranslationForCommit(task, translated)
                            };
                        } catch (error) {
                            firstError ||= error;
                            results[index] = { error };
                        }
                    }
                }

                await Promise.all(
                    Array.from({ length: repairConcurrency }, () => worker())
                );
                return { results, firstError };
            }

            async function processTranslateTaskBatch(tasks, options = {}) {
                if (!tasks.length) return { completed: 0, failed: 0, shouldSlowDown: false, reason: '' };

                throwIfTranslationCancelled(runId);
                while (isPaused && !isTranslationCancelled) {
                    await waitForResume();
                }
                throwIfTranslationCancelled(runId);

                const profile = tasks[0].profile;
                const incidentCountBefore = getTranslateChannelIncidentCount(profile);
                const hasNewChannelIncident = () =>
                    getTranslateChannelIncidentCount(profile) > incidentCountBefore;
                updateTranslateChannelProgress(profile, {
                    status: 'running',
                    message: `准备批量 ${tasks.length} 条`
                });
                const uncachedTasks = [];
                let localDiscountFailureCount = 0;
                for (const task of tasks) {
                    const localDiscountStatus = await processLocalDiscountTask(task);
                    if (localDiscountStatus !== null) {
                        if (localDiscountStatus !== 'success') localDiscountFailureCount++;
                        continue;
                    }
                    if (task.passthrough) {
                        updateTranslateChannelProgress(task.profile, {
                            status: 'running',
                            message: '无需翻译，原样写入'
                        });
                        commitTranslateResult(task, task.text, '通过');
                        continue;
                    }
                    const memoryKey = buildTranslationMemoryKey(task);
                    if (translationMemory.has(memoryKey)) {
                        updateTranslateChannelProgress(task.profile, {
                            status: 'running',
                            message: '复用同文翻译'
                        });
                        const result = await prepareTranslationForCommit(task, translationMemory.get(memoryKey));
                        commitTranslateResult(task, result.translated, result.qaStatus);
                        continue;
                    }
                    if (translationMemoryPromises.has(memoryKey)) {
                        updateTranslateChannelProgress(task.profile, {
                            status: 'running',
                            message: '等待同文请求返回'
                        });
                        const translated = await translationMemoryPromises.get(memoryKey);
                        throwIfTranslationCancelled(runId);
                        const result = await prepareTranslationForCommit(task, translated);
                        commitTranslateResult(task, result.translated, result.qaStatus);
                        continue;
                    }
                    uncachedTasks.push(task);
                }
                if (!uncachedTasks.length) {
                    return {
                        completed: tasks.length,
                        failed: localDiscountFailureCount,
                        shouldSlowDown: hasNewChannelIncident(),
                        reason: localDiscountFailureCount > 0 ? '本地折扣规则检测到需确认项' : '复用缓存翻译'
                    };
                }

                await waitForTranslateChannelRecovery(profile);
                const representativeTasks = [];
                const duplicateTasksByMemoryKey = new Map();
                const seenBatchMemoryKeys = new Map();
                uncachedTasks.forEach(task => {
                    const memoryKey = buildTranslationMemoryKey(task);
                    if (seenBatchMemoryKeys.has(memoryKey)) {
                        if (!duplicateTasksByMemoryKey.has(memoryKey)) {
                            duplicateTasksByMemoryKey.set(memoryKey, []);
                        }
                        duplicateTasksByMemoryKey.get(memoryKey).push(task);
                        return;
                    }
                    seenBatchMemoryKeys.set(memoryKey, task);
                    representativeTasks.push(task);
                });

                if (representativeTasks.length <= 1) {
                    let failedInSingleMode = localDiscountFailureCount;
                    for (const task of uncachedTasks) {
                        const status = await processTranslateTask(task);
                        if (status !== 'success') failedInSingleMode++;
                    }
                    return {
                        completed: uncachedTasks.length,
                        failed: failedInSingleMode,
                        shouldSlowDown: hasNewChannelIncident(),
                        reason: failedInSingleMode > 0 ? '单条翻译失败或需确认' : ''
                    };
                }

                updateTranslateChannelProgress(profile, {
                    status: 'running',
                    message: `批量翻译 ${representativeTasks.length} 条（每批最多 ${getTranslationBatchSize(profile)}）`
                });
                let batchFailureSummary = '';
                let batchFailureError = null;
                const requestLimiter = getTranslationRequestLimiter(profile);
                const translations = await translateBatchWithRetry(
                    representativeTasks,
                    sourceLang,
                    targetLang,
                    currentProject.rules,
                    profile,
                    runSignal,
                    2,
                    glossaryTermsForRun,
                    {
                        requestLimiter,
                        onBatchStatus: ({ attempt, retries, error, summary, willRetry }) => {
                            batchFailureSummary = summary || batchFailureSummary;
                            batchFailureError = error || batchFailureError;
                            const willSplit = !willRetry &&
                                getTranslationBatchSplitPlan(
                                    uncachedTasks,
                                    error,
                                    Number(options.batchSplitDepth || 0)
                                ).length > 1;
                            recordTranslateChannelIncident(profile, error, { retry: willRetry });
                            updateTranslateChannelProgress(profile, {
                                status: 'retrying',
                                message: `批量第 ${attempt}/${retries} 次失败：${summary}${willRetry ? '，正在重试' : (willSplit ? '，准备拆分批次' : '，准备降级单条')}`
                            });
                        }
                    }
                );
                throwIfTranslationCancelled(runId);

                if (translations && translations.length === representativeTasks.length) {
                    let failedInBatch = localDiscountFailureCount;
                    const preparedBatch = await prepareTranslationBatchResults(
                        representativeTasks,
                        translations,
                        profile,
                        options.qaRepairConcurrency
                    );
                    let firstPreparationError = preparedBatch.firstError;
                    const preparedResults = preparedBatch.results;
                    for (const [index, task] of representativeTasks.entries()) {
                        if (preparedResults[index]?.error) {
                            firstPreparationError ||= preparedResults[index].error;
                            continue;
                        }
                        if (!preparedResults[index]) {
                            firstPreparationError ||= new Error('QA 预处理未返回结果');
                            continue;
                        }
                        const result = preparedResults[index]?.result;
                        if (!result) {
                            firstPreparationError ||= new Error('QA 预处理未返回结果');
                            continue;
                        }
                        const status = commitTranslateResult(task, result.translated, result.qaStatus);
                        recordChannelOutcome(task, status === 'failed' || status === 'missing');
                        if (status !== 'success') failedInBatch++;
                        const memoryKey = buildTranslationMemoryKey(task);
                        for (const duplicateTask of (duplicateTasksByMemoryKey.get(memoryKey) || [])) {
                            const duplicateStatus = commitTranslateResult(duplicateTask, result.translated, result.qaStatus);
                            if (duplicateStatus !== 'success') failedInBatch++;
                        }
                    }
                    if (firstPreparationError) throw firstPreparationError;
                    return {
                        completed: representativeTasks.length,
                        failed: failedInBatch,
                        shouldSlowDown: hasNewChannelIncident(),
                        reason: hasNewChannelIncident()
                            ? '批量翻译或 QA 修复发生通道异常'
                            : (failedInBatch > 0 ? '批量结果存在失败或需确认项' : '')
                    };
                }

                const batchSplitDepth = Math.max(0, Number(options.batchSplitDepth || 0));
                const splitBatches = getTranslationBatchSplitPlan(
                    uncachedTasks,
                    batchFailureError,
                    batchSplitDepth
                );
                if (splitBatches.length > 1) {
                    recordTranslateChannelBatchSplit(
                        profile,
                        uncachedTasks.length,
                        splitBatches.map(batch => batch.length),
                        batchFailureSummary
                    );
                    let failedInSplit = localDiscountFailureCount;
                    for (const splitBatch of splitBatches) {
                        const splitResult = await processTranslateTaskBatch(splitBatch, {
                            ...options,
                            batchSplitDepth: batchSplitDepth + 1
                        });
                        failedInSplit += Number(splitResult?.failed || 0);
                    }
                    return {
                        completed: tasks.length,
                        failed: failedInSplit,
                        shouldSlowDown: hasNewChannelIncident(),
                        reason: hasNewChannelIncident()
                            ? '拆分批次期间发生通道异常'
                            : '批量结构异常，已拆小批次完成'
                    };
                }

                updateTranslateChannelProgress(profile, {
                    status: 'retrying',
                    message: `${batchFailureSummary ? `批量失败：${batchFailureSummary}，` : '批量返回异常，'}已降级单条补跑`
                });
                let failedInFallback = localDiscountFailureCount;
                for (const task of uncachedTasks) {
                    const status = await processTranslateTask(task);
                    if (status !== 'success') failedInFallback++;
                }
                return {
                    completed: uncachedTasks.length,
                    failed: failedInFallback,
                    shouldSlowDown: hasNewChannelIncident(),
                    reason: batchFailureSummary || '批量返回异常，已降级单条'
                };
            }

            async function waitTranslateBatchSettle(profile, waitMs, message = '稳态间隔') {
                const totalWaitMs = Math.max(0, Number(waitMs || 0));
                if (!totalWaitMs) return;
                const startedAt = Date.now();
                while (Date.now() - startedAt < totalWaitMs) {
                    throwIfTranslationCancelled(runId);
                    while (isPaused && !isTranslationCancelled) {
                        await waitForResume();
                    }
                    throwIfTranslationCancelled(runId);
                    const remaining = Math.max(0, totalWaitMs - (Date.now() - startedAt));
                    updateTranslateChannelProgress(profile, {
                        status: 'waiting',
                        message: `${message}，${Math.ceil(remaining / 1000)} 秒后继续`
                    });
                    await new Promise(resolve => setTimeout(resolve, Math.min(500, remaining)));
                }
            }

            async function runTranslateQueues() {
                const tasksByProfile = new Map();
                translationTasks.forEach(task => {
                    const key = getTranslateChannelKey(task.profile);
                    if (!tasksByProfile.has(key)) tasksByProfile.set(key, []);
                    tasksByProfile.get(key).push(task);
                });

                const getMaxConcurrencyForRun = (profile, batchCount) => {
                    const configured = getTranslateEffectiveConcurrencyLimit(profile);
                    return Math.max(1, Math.min(configured, batchCount || 1));
                };

                function getTranslationTaskBatchCost(task) {
                    const textCost = String(task?.text || '').length;
                    const referenceCost = String(task?.referenceText || '').length;
                    const glossaryCost = (task?.glossaryTerms || []).slice(0, 8).reduce((sum, term) =>
                        sum + String(term.source || '').length + String(term.target || term.referenceTarget || '').length,
                    0);
                    const consistencyCost = (task?.consistencyTerms || []).slice(0, 6).reduce((sum, term) =>
                        sum + String(term || '').length,
                    0);
                    return textCost + referenceCost + glossaryCost + consistencyCost;
                }

                function getTranslationBatchCostLimit(profile) {
                    if (profile?.provider === 'youdaoTranslate') return 2200;
                    if (profile?.provider === 'deepseek') return 2400;
                    if (profile?.provider === 'agnes') return 2400;
                    return 2000;
                }

                function createTranslationTaskBatches(queue, profile) {
                    const maxBatchSize = getTranslationBatchSize(profile);
                    const maxCost = getTranslationBatchCostLimit(profile);
                    const batches = [];
                    let current = [];
                    let currentCost = 0;

                    queue.forEach(task => {
                        const taskCost = Math.max(1, getTranslationTaskBatchCost(task));
                        const wouldExceedSize = current.length >= maxBatchSize;
                        const wouldExceedCost = current.length > 0 && currentCost + taskCost > maxCost;
                        if (wouldExceedSize || wouldExceedCost) {
                            batches.push(current);
                            current = [];
                            currentCost = 0;
                        }
                        current.push(task);
                        currentCost += taskCost;
                    });

                    if (current.length > 0) batches.push(current);
                    return batches;
                }

                const runners = [...tasksByProfile.values()]
                    .filter(queue => queue.length > 0)
                    .map(queue => {
                        const profile = queue[0].profile;
                        const batches = createTranslationTaskBatches(queue, profile);
                        const batchCount = batches.length;
                        let nextIndex = 0;
                        let activeCount = 0;
                        let settled = false;
                        let resolveRunner = null;
                        let rejectRunner = null;
                        let nextBatchStartAt = Date.now();
                        const maxConcurrency = getMaxConcurrencyForRun(profile, batchCount);
                        const speedOptimizedRun = retryTasks || deferAutoQaRepairForRun || importedTranslateProgressState?.entries?.length;
                        const initialConcurrency = speedOptimizedRun
                            ? Math.min(2, maxConcurrency)
                            : 1;
                        const adaptive = {
                            current: initialConcurrency,
                            max: maxConcurrency,
                            stableSuccesses: 0,
                            cooldownUntil: 0,
                            lastReason: maxConcurrency > initialConcurrency
                                ? (speedOptimizedRun ? '快速/补跑任务，适度并发起步' : '低并发起步')
                                : ''
                        };

                        function formatAdaptiveMessage(baseMessage = '') {
                            const adaptiveText = adaptive.max > 1
                                ? `自动并发 ${adaptive.current}/${adaptive.max}${adaptive.lastReason ? `，${adaptive.lastReason}` : ''}`
                                : '自动并发 1/1';
                            return baseMessage ? `${baseMessage}；${adaptiveText}` : adaptiveText;
                        }

                        function maybeIncreaseAdaptiveConcurrency() {
                            if (adaptive.current >= adaptive.max) return;
                            if (Date.now() < adaptive.cooldownUntil) return;
                            if (adaptive.stableSuccesses < TRANSLATION_ADAPTIVE_SUCCESS_TO_INCREASE) return;
                            adaptive.current++;
                            setTranslationRequestAdaptiveCap(profile, adaptive.current);
                            adaptive.stableSuccesses = 0;
                            adaptive.lastReason = '连续稳定，谨慎提速';
                            updateTranslateChannelProgress(profile, {
                                status: 'running',
                                message: formatAdaptiveMessage('通道稳定，已小幅恢复并发')
                            });
                        }

                        function reduceAdaptiveConcurrency(reason = '') {
                            const shouldRecordSlowdown = adaptive.current > 1 || Date.now() >= adaptive.cooldownUntil;
                            adaptive.current = 1;
                            setTranslationRequestAdaptiveCap(profile, adaptive.current);
                            adaptive.stableSuccesses = 0;
                            adaptive.cooldownUntil = Date.now() + TRANSLATION_ADAPTIVE_COOLDOWN_MS;
                            adaptive.lastReason = reason ? `已降速保护：${reason}` : '已降速保护';
                            nextBatchStartAt = Math.max(nextBatchStartAt, Date.now() + TRANSLATION_BATCH_FAILURE_SETTLE_DELAY_MS);
                            if (shouldRecordSlowdown) {
                                recordTranslateChannelIncident(profile, null, { slowdown: true });
                            }
                        }

                        function reserveBatchSettleDelay() {
                            const now = Date.now();
                            const scheduledAt = Math.max(now, nextBatchStartAt);
                            nextBatchStartAt = scheduledAt + TRANSLATION_BATCH_SETTLE_DELAY_MS;
                            return Math.max(0, scheduledAt - now);
                        }

                        function finishIfDone() {
                            if (settled) return true;
                            if (activeCount === 0 && nextIndex >= batches.length) {
                                settled = true;
                                resolveRunner?.();
                                return true;
                            }
                            return false;
                        }

                        function scheduleMore() {
                            if (settled) return;
                            while (activeCount < adaptive.current && nextIndex < batches.length) {
                                const taskBatch = batches[nextIndex++];
                                activeCount++;
                                void processBatch(taskBatch);
                            }
                            finishIfDone();
                        }

                        async function processBatch(taskBatch) {
                            try {
                                throwIfTranslationCancelled(runId);
                                const settleDelay = reserveBatchSettleDelay();
                                if (settleDelay > 0) {
                                    await waitTranslateBatchSettle(profile, settleDelay);
                                }
                                updateTranslateChannelProgress(profile, {
                                    status: 'running',
                                    message: formatAdaptiveMessage(`正在翻译第 ${taskBatch[0]?.rowIndex + 1 || '-'} 行附近，批量 ${taskBatch.length} 条，批次间隔 ${TRANSLATION_BATCH_SETTLE_DELAY_MS / 1000}s`)
                                });
                                setTranslationRequestAdaptiveCap(profile, adaptive.current);
                                const batchResult = await processTranslateTaskBatch(taskBatch, {
                                    qaRepairConcurrency: adaptive.current
                                });
                                throwIfTranslationCancelled(runId);

                                if (batchResult?.shouldSlowDown) {
                                    reduceAdaptiveConcurrency(batchResult.reason || '本批存在失败项');
                                    updateTranslateChannelProgress(profile, {
                                        status: 'retrying',
                                        message: formatAdaptiveMessage(batchResult.reason || '本批存在失败项，已自动降速')
                                    });
                                } else {
                                    adaptive.stableSuccesses++;
                                    maybeIncreaseAdaptiveConcurrency();
                                }
                            } catch (error) {
                                const isAbortOrCancel = error.name === 'AbortError' ||
                                    error.message === 'TRANSLATION_CANCELLED' ||
                                    isTranslationCancelled;
                                if (isAbortOrCancel) {
                                    updateTranslateChannelProgress(profile, {
                                        status: 'paused',
                                        message: '任务已暂停或取消'
                                    });
                                    settled = true;
                                    rejectRunner?.(error);
                                    return;
                                } else {
                                    const summary = summarizeTranslateError(error);
                                    if (isTemporaryTranslateApiError(error)) {
                                        recordTranslateChannelIncident(profile, error);
                                        reduceAdaptiveConcurrency(summary);
                                    }
                                    const committedFailures = commitUnfinishedTranslateTaskFailures(taskBatch, summary || '当前批次异常');
                                    if (committedFailures.committed > 0) {
                                        await flushTranslationTaskProgress();
                                        await saveCurrentTranslationProgress(taskBatch[taskBatch.length - 1]?.rowIndex || 1);
                                    }
                                    updateTranslateChannelProgress(profile, {
                                        status: 'retrying',
                                        message: formatAdaptiveMessage(`${summary}；本批未完成 ${committedFailures.committed} 条已标记待补跑，队列继续`)
                                    });
                                }
                                return;
                            } finally {
                                activeCount = Math.max(0, activeCount - 1);
                                scheduleMore();
                            }
                        }

                        updateTranslateChannelProgress(profile, {
                            status: 'waiting',
                            message: formatAdaptiveMessage(`已排队 ${queue.length} 条，批次 ${batchCount} 个`)
                        });

                        return new Promise((resolve, reject) => {
                            resolveRunner = resolve;
                            rejectRunner = reject;
                            scheduleMore();
                        });
                    });

                await Promise.all(runners);
            }

            await runTranslateQueues();
            throwIfTranslationCancelled(runId);

            ensureTranslationReportCoversExpectedTasks();
            if (twoStageRetryRun) {
                deferredRetryRepairSummary = await runDeferredRetryRepairPhase();
                throwIfTranslationCancelled(runId);
                ensureTranslationReportCoversExpectedTasks();
                refreshTranslationRunCountsFromReport();
                updateTranslateProgress(totalTasks, totalTasks, 100);
            }
            translatedWorkbook = buildTranslationWorkbook();
            translatedData = translatedDataLocal;

            progressSection.style.display = 'none';
            downloadSection.style.display = 'block';
            translationRunReport.successCount = successCount;
            translationRunReport.failCount = failCount;
            ensureTranslationReportCoversExpectedTasks();
            const reportFailureCount = getTranslationReportFailureEntries().length;
            const finalIssueSummary = getTranslationReportIssueSummary();
            runReportFailureCount = reportFailureCount;
            const latestEntryByTask = new Map();
            (translationRunReport.entries || []).forEach(entry => {
                if (entry.taskKey) latestEntryByTask.set(entry.taskKey, entry);
            });
            failedTranslationTasks = allTranslationTasks.filter(task => {
                const entry = latestEntryByTask.get(task.taskKey);
                return entry && isRepairableTranslationReportEntry(entry);
            });
            const deliveryGate = getTranslationDeliveryGate();
            runRepairableCount = deliveryGate.blockingCount;
            await flushTranslationTaskProgress();
            if (!deliveryGate.ready) {
                await saveCurrentTranslationProgress(1);
            } else {
                clearTranslationProgress();
            }
            document.getElementById('translatedCount').textContent = translateCount;
            updateTranslationRunActions();
            if (!deliveryGate.ready) {
                markTranslateLanguageFailed(targetLang);
            } else {
                markTranslateLanguageCompleted(targetLang);
            }
            if (!options.skipMultiTarget) {
                updateTranslateLanguageRunState({
                    currentIndex: -1,
                    status: deliveryGate.ready ? 'success' : 'needs_action'
                });
            }
            const finishPhase = !deliveryGate.ready
                ? `${runLanguageLabel}仍有阻断问题，未生成交付版`
                : (reportFailureCount > 0
                    ? `${runLanguageLabel}完成，有软性问题待确认`
                    : (retryTasks ? `${runLanguageLabel}修复完成` : `${runLanguageLabel}翻译完成`));
            updateTranslateRunSummary(totalTasks, totalTasks, finishPhase);

            const statusTitle = !deliveryGate.ready
                ? `${runLanguageLabel}仍有阻断问题，未生成交付版`
                : (retryTasks ? `${runLanguageLabel}修复完成` : `${runLanguageLabel}翻译完成`);
            let autoSaveMessage = '';
            if (options.suppressAutoSave) {
                autoSaveMessage = deliveryGate.ready
                    ? '；交付版已生成，请点击下载按钮保存'
                    : `；仍有 ${deliveryGate.blockingCount} 条阻断问题，未生成交付版`;
            } else {
                try {
                    const savedPaths = await autoSaveTranslationOutputs();
                    autoSaveMessage = deliveryGate.ready
                        ? (savedPaths.length ? `；已自动保存：${savedPaths.join('；')}` : '')
                        : `；仍有 ${deliveryGate.blockingCount} 条阻断问题，未生成交付版${savedPaths.length ? `；问题报告已保存：${savedPaths.join('；')}` : ''}`;
                } catch (saveError) {
                    console.warn('自动保存翻译结果失败:', saveError);
                    recordClientError('translation-auto-save', saveError, { targetLang });
                    autoSaveMessage = deliveryGate.ready
                        ? '；自动保存失败，请点击下载按钮手动保存'
                        : `；仍有 ${deliveryGate.blockingCount} 条阻断问题，未生成交付版；问题报告自动保存失败`;
                }
            }
            const followUpMessage = !deliveryGate.ready
                ? '请点击“一键修复并生成交付版”；系统只处理阻断问题，复检清零后才会输出文件。'
                : (reportFailureCount > 0
                    ? '剩余为软性需确认项；可在报告中填写处理决定，重新导入后会保留该决定。'
                    : '交付版和报告已准备好。');
            const deferredRepairMessage = deferredRetryRepairSummary
                ? (deferredRetryRepairSummary.limitedByBudget
                    ? `批量重译后有 ${deferredRetryRepairSummary.eligible} 个阻断项；本轮按预算深度检查 ${deferredRetryRepairSummary.attempted} 条，其余 ${deferredRetryRepairSummary.deferred} 条保留原结果并轮转到后续批次。`
                    : (deferredRetryRepairSummary.eligible > 0
                        ? `第二阶段深度检查 ${deferredRetryRepairSummary.attempted} 条，更新 ${deferredRetryRepairSummary.changed} 条，解除阻断 ${deferredRetryRepairSummary.resolved} 条${deferredRetryRepairSummary.errors ? `，保留异常 ${deferredRetryRepairSummary.errors} 条原结果` : ''}。`
                        : '批量重译后没有残余硬问题，无需逐条 AI 修复。'))
                : '';
            const issueSummaryText = formatTranslationReportIssueSummary(finalIssueSummary);
            setTranslateDownloadLanguageSummary(`${getTranslateLanguageName(targetLang)}已完成：本轮通过质检 ${runSuccessCount} 个，发现问题 ${runFailCount} 个；当前报告为 ${issueSummaryText}。${deferredRepairMessage}${followUpMessage}`);
            setStatus(deliveryGate.ready ? 'success' : 'warning', statusTitle, `本轮通过质检 ${runSuccessCount} 个，发现问题 ${runFailCount} 个；当前报告为 ${issueSummaryText}。${deferredRepairMessage}${autoSaveMessage}`, function() {
                document.getElementById('translate-tool').scrollIntoView({ behavior: 'smooth' });
            });
            if (!deliveryGate.ready) {
                finishInspectorTaskTimer('warning', statusTitle);
            }
            runOutcome = deliveryGate.ready ? 'success' : 'needs_action';

        } catch (error) {
            if (isTranslationCancelled || error.name === 'AbortError' || error.message === 'TRANSLATION_CANCELLED') {
                console.log('Translate cancelled');
                runOutcome = 'cancelled';
                markUnfinishedTranslateChannels('paused', '任务已取消或暂停，未完成后续翻译');
                updateTranslateLanguageRunState({ status: 'stopped' });
                updateTranslateRunSummary(translateRunSummaryState.completed, translateRunSummaryState.total, `${runLanguageLabel}已取消`);
                setTranslateDownloadLanguageSummary(`${getTranslateLanguageName(targetLang)}翻译已取消，未完成的语言不会继续执行。`);
                setStatus('warning', `${runLanguageLabel}翻译已取消`, '已停止后续请求。现在可以重新选择模型、调整配置，或上传新的文件。');
                finishInspectorTaskTimer('warning', `${runLanguageLabel}翻译已取消`);
            } else if (error.isPreflightFailure) {
                const quotaDepleted = isApiQuotaDepletedError(error);
                const phase = quotaDepleted
                    ? `${runLanguageLabel}未开始：API 额度已用尽`
                    : `${runLanguageLabel}未开始：通道预检失败`;
                const actionText = quotaDepleted
                    ? '当前 API 通道没有可用额度。本次没有发送任何待翻译文本，也没有改写导入报告。请充值/恢复额度，或切换到其他有额度的通道后再次点击重译。'
                    : '本次没有发送任何待翻译文本，也没有改写导入报告。请检查 Key、Base URL 和模型权限，或切换可用通道后重试。';
                console.error('Translate preflight failed:', error);
                recordClientError('startTranslate-preflight', error, { targetLang, runLanguageLabel });
                runOutcome = 'preflight_failed';
                markTranslateLanguageFailed(targetLang);
                updateTranslateRunSummary(0, totalTasks, phase);
                updateTranslationRunActions();
                setTranslateDownloadLanguageSummary(`${phase}。${actionText}`);
                setStatus(
                    'error',
                    phase,
                    `${actionText} 详细原因：${error.message || '未知错误'}`,
                    revealApiConfigPanel,
                    quotaDepleted ? '充值或切换通道' : '检查通道'
                );
            } else {
                console.error('Translate error:', error);
                recordClientError('startTranslate', error, { targetLang, runLanguageLabel });
                runOutcome = 'error';
                ensureTranslationReportCoversExpectedTasks(error.message || '任务异常停止，预期任务未写入结果');
                translatedWorkbook = buildTranslationWorkbook();
                if (translationProgressTasks.size > 0) {
                    await flushTranslationTaskProgress();
                    await saveCurrentTranslationProgress(1);
                }
                markUnfinishedTranslateChannels('failed', error.message || '任务异常停止');
                markTranslateLanguageFailed(targetLang);
                updateTranslateRunSummary(translateRunSummaryState.completed, translateRunSummaryState.total, `${runLanguageLabel}异常停止`);
                updateTranslationRunActions();
                setTranslateDownloadLanguageSummary(`${getTranslateLanguageName(targetLang)}翻译异常停止：${error.message || '未知错误'}`);
                setStatus('error', `${runLanguageLabel}翻译失败`, error.message);
            }
            progressSection.style.display = 'none';
        } finally {
            if (currentTranslateAbortController === runController) {
                currentTranslateAbortController = null;
            }
            if (activeTranslateRunId === runId) {
                activeTranslateRunId = null;
            }
            stopTranslateElapsedTimer();
            isPaused = false;
            pauseBtn.style.display = 'inline-flex';
            resumeBtn.style.display = 'none';
            downloadProgressBtn.style.display = 'none';
            updateTranslationRunActions();
            updateTranslateInspectorRuntime();
            if (options.outputSuffix !== undefined) {
                activeTranslationOutputSuffix = previousOutputSuffix;
            }
        }
        return {
            status: runOutcome,
            targetLang,
            successCount: runSuccessCount,
            failCount: runFailCount,
            failureCount: runReportFailureCount,
            repairableCount: runRepairableCount
        };
    }

    function shouldRenderTranslationPreview(status, completedCount) {
        if (status !== 'success') return true;
        if (completedCount <= 20) return true;
        return completedCount % TRANSLATION_PREVIEW_RENDER_EVERY === 0;
    }

    function addTranslationItem(list, original, translated, row, col, profile = null, targetLang = '') {
        const item = document.createElement('div');
        item.className = 'translation-item';

        const truncatedOriginal = original.length > 50 ? original.substring(0, 50) + '...' : original;
        const truncatedTranslated = translated.length > 50 ? translated.substring(0, 50) + '...' : translated;
        const modelLabel = profile ? getApiProfileLabel(profile) : '';
        const languageLabel = targetLang ? getTranslateLanguageName(targetLang) : '';

        item.innerHTML = `
            <div class="translation-row-info">行 ${row + 1}, 列 ${col + 1}${languageLabel ? ` · ${escapeHtml(languageLabel)}` : ''}${modelLabel ? ` · ${escapeHtml(modelLabel)}` : ''}</div>
            <div class="translation-content">
                <div class="translation-original">${escapeHtml(truncatedOriginal)}</div>
                <div class="translation-arrow">→</div>
                <div class="translation-result ${isTranslateFailureText(translated) ? 'error' : ''}">${escapeHtml(truncatedTranslated)}</div>
            </div>
        `;

        list.insertBefore(item, list.firstChild);

        if (list.children.length > TRANSLATION_PREVIEW_MAX_ITEMS) {
            list.removeChild(list.lastChild);
        }
    }

    function updateTranslateProgress(current, total, percent) {
        document.getElementById('translateProgressText').textContent = `${current} / ${total}`;
        document.getElementById('translateProgressPercent').textContent = `${percent}%`;
        document.getElementById('translateProgressFill').style.width = `${percent}%`;
    }

    async function downloadTranslated() {
        ensureTranslationReportCoversExpectedTasks();
        const deliveryGate = getTranslationDeliveryGate();
        if (!deliveryGate.ready) {
            setTranslateDownloadLanguageSummary(
                `仍有 ${deliveryGate.blockingCount} 条阻断问题，未生成交付版。请先点击“一键修复并生成交付版”；如需查看当前结果，可主动导出未验证版。`
            );
            setStatus(
                'warning',
                '阻断问题未清零，不能下载交付版',
                `当前还有 ${deliveryGate.blockingCount} 条翻译失败、结果缺失或硬质检问题。未验证版可供查看和人工修改，但不能直接交付。`
            );
            return;
        }
        const workbook = translatedWorkbook || buildTranslationWorkbook();
        if (!workbook) {
            alert('没有可下载的翻译结果');
            return;
        }

        translatedWorkbook = workbook;
        const fileName = getTranslationOutputFileName('translated');
        try {
            setTranslateDownloadLanguageSummary('正在保存翻译文件到下载目录...');
            const savedPath = await saveWorkbookFile(workbook, fileName, {
                onProgress: (_phase, message) => setTranslateDownloadLanguageSummary(message)
            });
            setTranslateDownloadLanguageSummary(`交付版已保存：${savedPath}`);
            setStatus('success', '交付版已保存', savedPath);
        } catch (error) {
            console.error('保存翻译文件失败:', error);
            recordClientError('translation-file-download', error);
            setTranslateDownloadLanguageSummary('翻译文件保存失败，请稍后重试。');
            setStatus('error', '翻译文件保存失败', error.message || String(error));
        }
    }

    function hideUnverifiedTranslationExportConfirmation() {
        if (translateUnverifiedExportConfirm) {
            translateUnverifiedExportConfirm.style.display = 'none';
        }
    }

    function showUnverifiedTranslationExportConfirmation() {
        ensureTranslationReportCoversExpectedTasks();
        const deliveryGate = getTranslationDeliveryGate();
        if (deliveryGate.ready) {
            hideUnverifiedTranslationExportConfirmation();
            void downloadTranslated();
            return;
        }
        if (!translationRunReport) {
            setStatus('warning', '暂无可导出的当前译文', '请先完成翻译或导入翻译报告。');
            return;
        }
        if (translateUnverifiedExportMessage) {
            translateUnverifiedExportMessage.textContent =
                `当前仍有 ${deliveryGate.blockingCount} 条阻断问题。导出文件会命名为 *_translated_unverified.xlsx，第一页会标注“未验证译文，请勿直接交付”。`;
        }
        if (translateUnverifiedExportConfirm) {
            translateUnverifiedExportConfirm.style.display = 'grid';
        }
        translateConfirmUnverifiedExportBtn?.focus();
    }

    function buildUnverifiedTranslationWorkbook(deliveryGate = getTranslationDeliveryGate()) {
        const workbook = buildTranslationWorkbook();
        if (!workbook) return null;

        const issueSummary = getTranslationReportIssueSummary();
        const languageCode = translationRunReport?.targetLang || targetLangSelect?.value || '';
        const languageName = getTranslateLanguageName(languageCode) || languageCode || '未指定';
        const noticeSheetName = '未验证说明';
        const noticeRows = [
            ['未验证译文，请勿直接交付'],
            [],
            ['文件状态', `包含 ${deliveryGate.blockingCount} 条阻断问题，尚未达到正式交付条件`],
            ['目标语言', languageName],
            ['生成时间', new Date().toLocaleString('zh-CN')],
            ['翻译失败 / 未返回', issueSummary.failedOrMissing || 0],
            ['硬质检未通过', issueSummary.hardQa || 0],
            ['软性需确认', issueSummary.softRisk || 0],
            [],
            ['正式交付条件', '翻译失败、结果缺失和硬质检问题全部清零'],
            ['建议操作', '返回工具点击“一键修复并生成交付版”，或在翻译报告中填写修订译文后重新导入'],
            ['数据说明', '后续数据工作表是当前译文快照；“翻译报告”工作表列出了具体问题和位置'],
            ['文件命名', '*_translated_unverified.xlsx 只用于查看、人工修改或内部确认，不等同于 *_translated.xlsx 交付版']
        ];
        const noticeSheet = XLSX.utils.aoa_to_sheet(noticeRows);
        noticeSheet['!cols'] = [{ wch: 20 }, { wch: 90 }];
        XLSX.utils.book_append_sheet(workbook, noticeSheet, noticeSheetName);
        workbook.SheetNames = [
            noticeSheetName,
            ...workbook.SheetNames.filter(sheetName => sheetName !== noticeSheetName)
        ];
        return workbook;
    }

    async function downloadUnverifiedTranslation() {
        ensureTranslationReportCoversExpectedTasks();
        const deliveryGate = getTranslationDeliveryGate();
        if (deliveryGate.ready) {
            hideUnverifiedTranslationExportConfirmation();
            await downloadTranslated();
            return;
        }

        const workbook = buildUnverifiedTranslationWorkbook(deliveryGate);
        if (!workbook) {
            setStatus('warning', '没有可导出的当前译文', '请先完成翻译或导入包含当前译文的翻译报告。');
            return;
        }

        const fileName = getTranslationOutputFileName('translated_unverified');
        try {
            if (translateConfirmUnverifiedExportBtn) translateConfirmUnverifiedExportBtn.disabled = true;
            setTranslateDownloadLanguageSummary('正在保存未验证译文到下载目录...');
            const savedPath = await saveWorkbookFile(workbook, fileName, {
                onProgress: (_phase, message) => setTranslateDownloadLanguageSummary(message)
            });
            hideUnverifiedTranslationExportConfirmation();
            setTranslateDownloadLanguageSummary(`未验证译文已保存：${savedPath}。该文件仍有 ${deliveryGate.blockingCount} 条阻断问题，不能直接交付。`);
            setStatus(
                'warning',
                '未验证译文已保存（请勿直接交付）',
                `${savedPath}；当前仍有 ${deliveryGate.blockingCount} 条阻断问题。`
            );
        } catch (error) {
            console.error('保存未验证译文失败:', error);
            recordClientError('translation-unverified-file-download', error);
            setTranslateDownloadLanguageSummary('未验证译文保存失败，请稍后重试。');
            setStatus('error', '未验证译文保存失败', error.message || String(error));
        } finally {
            if (translateConfirmUnverifiedExportBtn) translateConfirmUnverifiedExportBtn.disabled = false;
        }
    }

